window.__D("text/tikkunei-zohar/c004",{"p":[[9500011179,"<p>דְּעִִרְוָה, וְרָזָא דְעִִרְוָה אִתְרְמִיז בִּתְרֵין (בהדי) אַתְוָון עִ\"ר וָ\"ה עִ\"ר רַ\"ע בְּעִינֵי יהו\"ה (בראשית לח ז), וְאִלֵּין עַנְפִין (לא) אִתְפָּרְשׁוּ דִיְהֵא עִִרְוָה בֵּינַיְיהוּ, לַאו אִיהוּ אֶלָּא בַּר מֵאַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ אדנ\"י, הֲדָא הוּא דִכְתִיב (תהלים ה ה) לֹא יְגוּרְךָ רָע, דְּבִסְפִירָן תִּשְׁכַּח אָב וָאֵם וּבֵן כַּחֲדָא, בְּבִינָ\"ה בֶּ\"ן י\"ה, וְלֵית תַּמָּן עִִרְוָה, וְתִשְׁכַּח לוֹן לְתַתָּא אָח וְאָחוֹת תַּרְוַיְיהוּ בְּיִחוּדָא, אָח אִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא ד' אָחוֹת דִּילֵיהּ, וְתַרְוַיְיהוּ אִינוּן חַד בְּלָא פִרוּדָא, אַף עַל גַּב דְּצַדִּיק אִיהוּ יִחוּדָא דְכֻלְּהוּ.</p>\n<p>אַדְהָכִי הָא אֵלִיָּהוּ קָא אִזְדַּמַּן לֵיהּ לְרַבִּי שִׁמְעוֹן, וְאָמַר לֵיהּ רַבִּי רַבִּי, שִׁעוּרָא דְעִִרְיָין הָכִי אִיהוּ וַדַּאי, בְּכָל סְפִירָן לֵית יִחוּדָא חַד בַּחֲבֶרְתָּה כְּגַוְונָא דִדְכַר וְנוּקְבָא אֶלָּא בַּצַּדִּיק, דְּיִחוּדָא דְתַרְוַיְיהוּ לַאו אִיהוּ בְּכָל אֵבָרִין דִּלְהוֹן אֶלָּא בִּבְרִית מִילָה, בִּשְׁאָר אֵבָרִין קוּרְבָא דְאַחֲוָה אִית תַּמָּן וְלַאו דְּיִחוּדָא, וְדָא אִיהוּ רָזָא דְאִילָנָא דְעַנְפּוֹי מִתְפָּרְשִׁין לְעִילָא בְכָל סִטְרָא, וְרָזָא דְמִלָּה וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ וַיָּפוֹזּוּ זְרוֹעִי יָדָיו (בראשית מט כד), אֲבָל לְתַתָּא כֻּלְּהוּ אֲגוּדָה אַחַת יִחוּדָא חָדָא, וּבְגִין דָּא לְתַתָּא בַּצַּדִּיק צָרִיךְ לְקָרְבָא אַתְוָון דְּיהו\"ה עִם שְׁכִינְתֵּיהּ, דְּאִיהִי קוּרְבָא דִילָהּ קָרְבָּן לַיהו\"ה.</p>\n<p>וְהָכִי שְׁכִינְתָּא עִלָּאָה עִם חָכְמָה צָרִיךְ לְקָרְבָא לוֹן בַּצַּדִּיק, וְכָל עַנְפִין תַּמָּן מִתְיַחֲדִין וּמִתְקַשְּׁרִין וּמְשַׁלְּבִין, וּמְקַבְּלִין דָּא מִן דָּא, וְכֹלָּא עַל יְדָא דְצַדִּיק, וּבְלָא צַדִּיק לֵית קוּרְבָא דְיִחוּדָא, אֶלָּא אַחֲוָה, וּבְגִין דָּא חֶסֶד תַּמָּן אִתְקְרֵי ו' אָח וְה' אָחוֹת. מִסִּטְרָא דִימִינָא, וּבְהַאי אֲתַר אִתְּמַר (ויקרא כ יז) וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחוֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְגוֹמֵר חֶסֶד הוּא, וְעִם כָּל דָּא דְחֶסֶד הוּא וְנִכְרְתוּ לְעִינֵי בְּנֵי עַמָּם, מָאן דִּמְחַבֵּר אַתְוָון בַּאֲתַר דְּפִרוּדָא כְּאִלּוּ אַפְרִישׁ בֵּינַיְיהוּ, וּבְגִין דָּא וְנִכְרְתוּ מִדָּה לָקֳבֵל מִדָּה.</p>\n<p>וְהָכִי י\"ה בִּימִינָא אִינוּן בְּאַחֲוָה, וְלֵית יִחוּדָא אֶלָּא עַל יְדֵי דְצַדִּיק, וּבְגִין דָּא בְּהַאי אֲתַר לָא תִקְרְבוּ לְגַלּוֹת עִִרְוָה (שם יח ו), וְהָכִי בְּשׁוֹקָא יְמִינָא וּשְׂמָאלָא תַּמָּן אֱלֹהִים אֲחֵרִים, וְלָא צָרִיךְ לְקָרְבָא תַּמָּן אַתְוָון, בְּזִמְנָא דֶאֱלֹהִים אֲחֵרִים תַּמָּן דְּאִינוּן מִסִּטְרָא דַעֲבוֹדָה זָרָה, וְרָזָא דְמִלָּה וַיַּקְרִיבוּ לִפְנֵי יהו\"ה אֵשׁ זָרָה (שם י א).</p>\n<p>וְכָל אִינוּן עִִרְיָין אִינוּן סמא\"ל וְנָחָשׁ, דְּתָבְעִין לְמֶעֱבַד דִּינִין וּמְגַלִּין לוֹן קֳדָם יהו\"ה, וּבְגִין דָּא אִתְקְרִיאוּ עֲרָיוֹת, וְדָא אִיהוּ רָזָא וְסוֹד אַחֵר אַל תְּגָל (משלי כה ט), דְּדָא גְרִים גָּלוּת וְאִתְגְּלֵי בֵּין עַמְמַיָּא, מָאן דְּגָלֵי עִִרְיָתֵיהּ תַּמָּן הָכִי אִיהוּ אִתְגְּלֵי בֵּין עִִרְיָין דְּאִינוּן אֱלֹהִים אֲחֵרִים, וּמָאן דִּמְכַסֵּי עֲלַיְיהוּ הָכִי אִיהוּ אִתְכַּסֵּי בֵּינַיְיהוּ, וּבְגִין דָּא וְלֹא יְגַלֶּה כְּנַף אָבִיו, דָּא שְׁכִינְתָּא דְגָלַת בֵּין עַמְמַיָּא בְּגִין חוֹבָא דָא, כְּמָה דְאַתְּ אָמַר (ישעיה נ א) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם.</p>\n<p>וְאַרְבַּע זִמְנִין גָּלַת שְׁכִינְתָּא בְּגָלוּתָא, בְּגִין דְּאַעִילוּ עִִרְוָה בֵּין אַרְבַּע אַתְוָון, וְאַף עַל גַּב דְּאִתְּמַר כָּל אִלֵּין עִִרְיָין בִּסְפִירָן וּבִשְׁמָא דְיהוָֹ\"ה, לַאו בְּאַתְרֵיהּ דִּלְעִילָא, אֶלָּא כַּד שְׁכִינְתָּא גָלַת, כָּל סְפִירָן נָחֲתוּ עִמָּהּ, וְלֵית פִּרוּדָא בָהּ וּבֵין עֲשַׂר סְפִירָן, וְכַד נָחְתוּ אִתְלַבְּשׁוּ בְשִׁית יוֹמִין דְחוֹל שִׁית עַנְפִין, חֶסֶד בְּיוֹמָא קַדְמָאָה, גְּבוּרָה בְּיוֹמָא תִנְיָינָא, עַמּוּדָא דְאֶמְצָעִיתָא בְּיוֹמָא תְּלִיתָאָה, תְּלַת סְפִירָן תִּנְיָינִין בִּתְלַת יוֹמִין אָחֳרָנִין, דְּאִינוּן רְבִיעָאָה חֲמִשָּׁאָה וּשְׁתִיתָאָה.</p>\n<p>וַעֲשַׂר אֲמִירָן דָּא י' אַבָּא, חָמֵשׁ אוֹר דָּא ה' אִימָּא, שִׁית זִמְנִין טוֹב ו' דְּאִית בְּשִׁית יוֹמֵי דְחוֹל, ה' דְּהַשִּׁשִּׁי ה' דְיהו\"ה, רֹא\"שׁ דִּבְּרֵאשִׁי\"ת דָּא כֶתֶר רֵישָׁא דְכָל רֵישִׁין.</p>\n<p>וְאַמַּאי אִית פִּרוּדָא, בְגִין דְּלֵית צַדִּיק אוֹת בְּרִית תַּמָּן, וְרָזָא דְמִלָּה אֵין אָדָם צַדִּיק בָּאָרֶץ דְּאִיהוּ אוֹת בְּרִית תַּמָּן, וּבְשַׁבָּת דְּאִיהוּ יוֹמָא שְׁבִיעָאָה תַּמָּן קְרִיבוּ וְיִחוּדָא דִשְׁמָא דְיהו\"ה וְכָל סְפִירָן, וּבְגִין דָּא תַלְמִידֵי חֲכָמִים זִוּוּגַיְיהוּ מִלֵּילֵי שַׁבָּת לְלֵילֵי שַׁבָּת, הַאי עִִרְיָין אִינוּן וַדַּאי לְתַתָּא, אֲבָל לְעִילָא</p>"],[9500011180,"<p>אִתְּמַר (תהלים ה ה) לֹא יְגוּרְךָ רָע, וְצַדִּיק דְּקָרִיב לְאִתְּתֵיהּ בְּיוֹמִין דְּחוֹלָא, הַהוּא בֵּן דְּעָבִיד עֲלֵיהּ אִתְּמַר צַדִּיק וְרַע לוֹ, דְּגָרִים דְּאִתְעֲבִיד קֹדֶשׁ חוֹל דְּאִיהוּ יוֹם הַשְּׁבִיעִי, וּבְהַהוּא זִמְנָא אִיהוּ רָזָא דְצַדִּיק וְרַע לוֹ רָשָׁע וְטוֹב לוֹ, אֲבָל לְעִילָא לֵית עִִרְוָה וְקִצּוּץ וּפִרוּד וּפִרוּץ, וּבְגִין דָּא לְעִילָא (לית לך לידמה ליוצרך, דתימא הכי דלעילא) אִית יִחוּדָא בְּאָח וְאָחוֹת וּבְבֵן וּבְבַת בְּאֵם עִם בֵּן, אִם כֵּן לֵית לָךְ לִידְמֶה לְיוֹצְרָךְ, דְּאַנְתְּ הֲוִית גְּרִים דְּלָא תְהֵא בְּדִיּוֹקְנָא דִילֵיהּ לְעִילָא, כְּמָה דְאַתְּ אָמַר (ישעיה נט ב) כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים בֵּינֵיכֶם לְבֵין אלהיכ\"ם.</p>\n<p>וְתָא חֲזִי בְּשַׁעִִתָּא דְבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי אָדָם, הָכִי הֲוָה בָּעִי לְמֶעֱבַד לֵיהּ כְּגַוְונָא דְּדִיּוֹקְנָא דִילֵיהּ, בְּלָא עִִרְוָה וּבְלָא פֶרֶץ וּפִירוּד, כְּמָה דְאַתְּ אָמַר (בראשית א כו) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, לְמֶהֱוִי כָּל סְפִירָן כְּלִילָן בֵּיהּ, בְּלָא פִרוּד וְקִצּוּץ, וּלְאִתְיַחֲדָא בֵּן עִם בַּת דְּאִינוּן אַחִים, דַּעֲלַיְיהוּ אִתְּמַר אַחִים תְּאוֹמִים, הֲדָא הוּא דִכְתִיב (שמות כו כד) וְיִהְיוּ תוֹאֲמִים מִלְּמַטָּה וְיַחְדָּיו יִהְיוּ תַמִּים עַל רֹאשׁוֹ, בְּאָן אֲתַר, אֶל הַטַּבַּעַת (שם), דָּא טַבַּעַת דְּאוֹת בְּרִית מִילָה, דְאִיהוּ שִׁיעוּר לְכָל עִִרְיָין לְתַתָּא, וְשִׁעוּר דְּיִחוּדָא לְעִילָא, וּלְעִילָא אִתְּמַר בֵּיהּ (בראשית ג כב) וְלָקַח גַּם מֵעִץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם, אֲבָל לְתַתָּא אִתְּמַר בֵּיהּ וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, לָא תְעָרֵב בְּיִחוּדָא טוֹב עִם רָע, וְאִם לַאו (שם ב יז) מוֹת תָּמוּת, אִתְּמַר הָכָא מוֹת תָּמוּת וְאִתְּמַר בְּשַׁבָּת (שמות לא יד) מְחַלְלֶיהָ מוֹת יוּמָת.</p>\n<p>וְאָדָם וַדַּאי אִתְעֲבִיד בְּדִיּוֹקְנָא דִלְעִילָא, וְעָבַד תַּמָּן פִּרוּדָא, וְאִתְפָּרֵישׁ מִתַּמָּן, אָמַר לֵיהּ רַבִּי אֶלְעָזָר אַבָּא אֵיךְ אִתְעֲבִיד בְּדִיּוֹקְנָא דִלְעִילָא, דְּהָא שְׁמַעִִנָא כַמָּה דֵעוֹת תַּמָּן, אָמַר לֵיהּ בְּרִי, כַּד אִתְעֲבִיד. כֻּלְּהוּ סְפִירָן אִתְכְּלִילוּ בְּדִיּוֹקְנָא דְנִשְׁמָתֵיהּ, וְנִשְׁמָתֵיהּ הֲוָה מֶרְכָּבָה לוֹן כְּגַוְונָא דְנִשְׁמָתֵיהּ, דַּעֲלָהּ אִתְּמַר (בראשית א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, כְּגַוְונָא דְעִִשֶׂר סְפִירוֹת בְּלִימָה, וְכֻלְּהוּ גַוָּונִין דְּנִשְׁמָתִין הֲווֹ נָהֲרִין בְּנִשְׁמָתֵיהּ, וַהֲווֹ נְהִירִין עַל אַנְפּוֹי, וּמִנֵּיהּ הֲווֹ מִזְדַעִִזְעִין עִלָּאִין וְתַתָּאִין, וַהֲווֹ סָגְדִין לֵיהּ בְּגִין אִלֵּין נְהוֹרִין דַּהֲווֹ נְהִירִין בֵּיהּ, כְּגַוְונָא דְאָדָם דִּלְעִילָא דַּהֲווֹ סָגְדִין לֵיהּ, הָכִי הֲווֹ סָגְדִין לְאָדָם דִּלְתַתָּא, עַד דַּהֲוָה אָמַר אִיהוּ בּוֹאוּ נִשְׁתַּחֲוְה וְנִכְרָעָה נִבְרְכָה לִפְנֵי יהו\"ה עוֹשֵׂנוּ (תהלים צה ו), וּבְהַהוּא זִמְנָא הֲוָה אִיהוּ שַׁלִּיט עַל כָּל הֲמוֹנֵי עִילָא וְתַתָּא.</p>\n<p>גַּוָּון אוּכָּם דְּעִינָא וְשַׂעֲרוֹי אוּכְמִין וְכָל גַּוָּונִין אוּכְמִין שַׁפִּירִין, אִתְיְיהִיבָן בֵּיהּ מִסִּטְרָא דְאִימָּא, חִוְורוּ דְעִינָא וְחִוְורוּ דְאַנְפִּין וְחִוְורוּ דְמוֹחָא וְחִוְורוּ דְגָרְמִין, אִתְיְיהִיבַת בֵּיהּ מִסִּטְרָא דְאַבָּא, דְּהָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין, דְּלוֹבֶן שֶׁבְּעַיִן וּמוֹחָא וַעֲצָמוֹת אִתְיְיהִיבוּ מֵאַבָּא, וְאוּכְמוּ דְעִינָא וְשַׂעֲרָא אִתְיְיהִיבוּ מֵאִימָּא, וְחִוְורוּ וְאוּכְמוּ תַּרְוַיְיהוּ אִשְׁתַּכְּחוּ מִכִּתְרָא עִלָּאָה, אוּכְמוּ מִלְּבָר וְחִוְורוּ מִלְּגָו, וַעֲלֵיהּ אִתְּמַר (איוב לז כא) וְעַתָּה לֹא רָאוּ אוֹר בָּהִיר הוּא בַּשְּׁחָקִים, וְכָתוּב אַחֵר אוֹמֵר (תהלים יח יב) יָשֶׁת חֹשֶׁךְ סִתְרוֹ.</p>\n<p>וְהָא אוּקְמוּהוּ חַבְרַיָּא, אוּכְמוּ נוּקְבָא לְחִוְורוּ, וְאוֹרַיְיתָא מִתַּמָּן אִיהִי חִוְורוּ מִלְּגָאו אוּכְמוּ מִלְּבָר, וּלְעִילָא אַבָּא וְאִימָּא אָמְרוּ עַל עַמּוּדָא דְאֶמְצָעִיתָא וּשְׁכִינְתֵּיהּ נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ (בראשית א כו), עַמּוּדָא דְאֶמְצָעִיתָא בְחִוְורוּ, וּשְׁכִינְתָּא בְאוּכְמוּ, הֲדָא הוּא דִכְתִיב (שיר א ה) שְׁחוֹרָה אֲנִי וְנָאוָה, וְתָא חֲזִי אִימָּא עִלָּאָה הֲוַת אוּכְמָא קֳדָם הַהוּא נְהוֹרָא דִלְגָאו מִינָהּ, אֲבָל כַּד נָחְתָא לְתַתָּא אִתְחֲזִיַית גַּוְונָהָא בְחָמֵשׁ סְפִירָן, דְּאִינוּן ה' עַנְפִין דְּאִילָנָא, דְּרוֹעָא יְמִינָא וּשְׂמָאלָא וְגוּף וּתְרֵין שׁוֹקִין, צַדִּיק נָטִיל כָּל גַּוָּונִין, הֲדָא הוּא דִכְתִיב (בראשית ט טז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם, וּרְאִיתִיהָ בְגַוָּונִין נְהִירִין, וְהָכִי שְׁכִינְתָּא תַּתָּאָה אִתְחֲזִיַית בְּחָמֵשׁ גַּוָּונִין מִתַּתָּא לְעִילָא, וְאִלֵּין גַּוָּונִין דְּשִׁית סְפִירָן, וַעֲלַיְיהוּ אִתְּמַר (שמות כה ד) וּתְכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי</p>"],[9500011181,"<p>וְשֵׁשׁ וְעִזִּים, וּכְמָה דְּאִתְכְּלִילָן כָּל גַּוָּונִין מֵעִילָא לְתַתָּא בַּצַּדִּיק, הָכִי אִתְכְּלִילָן כָּל גַּוָּונִין מִתַּתָּא לְעִילָא בְּעַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>תָּא חֲזִי אַרְבַּע עַנְפִין רַבְרְבִין הֲווֹ בְאִילָנָא, וְאִינוּן הֲווֹ תְרֵין דְּרוֹעִין וּתְרֵין שׁוֹקִין, וְכֻלְּהוּ בְשִׁעוּרָא דְאָת ו' עִלָּאָה, וּבְכָל אַמָּה ה' עַנְפִין זְעִירִין דְּאִינוּן זֶרֶת, דְּאִתְּמַר בֵּיהּ (ישעיה מ ב) וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן, וְאִינוּן שִׁעוּרָא דְה', וְעַל ה' עַנְפִין הֲוָה י' דְּאִיהוּ כַּף הַיָּד, וְדָא אִיבָּא דְאִילָנָא, וְכַמָּה שִׁרְטוּטִין מְרַקְּמָן בְּכַף דְּיָד, דְּאִינוּן גַּוָּונִין שַׁפִּירִין דְּאִיבָּא, דִּבְהוֹן אִתְפַּתְּחַת שׁוֹשַׁנָּה דְאִתְעֲבִידַת מִינָהּ אִיבָּא, וְאִינוּן כַּפְתּוֹר וָפֶרַח, לְשֵׁשֶׁת הַקָּנִים הַיּוֹצְאִים מִן הַמְּנוֹרָה (שמות כה לג), וְאִלֵּין תְּלַת גָּרְמִין בִּדְרוֹעָא יְמִינָא, וּתְלַת בִּדְרוֹעָא שְׂמָאלָא, מְנַרְתָּא גוּפָא דְאֶמְצָעִיתָא.</p>\n<p>בְּרִי בְכָל אִלֵּין תִּקּוּנִין בָּרָא לְאָדָם וּבַת זוּגֵיהּ, (ואי) וְאִיהוּ עָבַד פִּרוּדָא לְעִילָא בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, דְּגָרִים לְסַלְקָא שְׁכִינְתא מִקּוּדְשָׁא בְּרִיךְ הוּא, הָכִי קוּדְשָׁא בְּרִיךְ הוּא סָלִיק מִנֵּיהּ בַּת זוּגֵיהּ, וְאִסְתַּלַּק קוּדְשָׁא בְּרִיךְ הוּא מִנֵּיהּ, דְּבַאֲתַר דְּלָא שַׁרְיָא שְׁכִינְתָּא תַמָּן, קוּדְשָׁא בְּרִיךְ הוּא לָא שַׁרְיָא תַמָּן, וּמְנָלָן דְּאִסְתַּלִּיק בַּת זוּגֵיהּ מִנֵּיהּ, כְּמָה דְאַתְּ אָמַר (בראשית ב יח) וַיֹּאמֶר יהו\"ה לֹא טוֹב היוֹת הָאָדָם לְבַדּוֹ, וְדָא גָרִים לְיַעֲקֹב דְּאִתְּמַר בֵּיהּ (שם לב כה) וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ, וּבְהַהוּא זִמְנָא נָצַח לֵיהּ סמא\"ל, וַיִּגַּע בְּכַף יְרֵיכוֹ (שם כו), בְּאָן אֲתַר פָּרַח בְּגִיד הַנָּשֶׁה, דְּפָרַח י' מִגִּיד הַנָּשֶׁה דְאִיהִי י' דְּיַעֲקֹב, וְאִשְׁתָּאַר אִיהוּ עָקֵב, דְאִיהוּ דָשׁ בְּעָקֵב, וְדָא רָזָא וְיָדוֹ אוֹחֶזֶת בַּעֲקֵב עִשָׂו (שם כה כו) (דאיהו דש בעקב בגלותא ובעולא דמלכותא דשבעין אומין דהוא לזנב ולא לראש).</p>\n<p>כְּמָה דְגָרִים אָדָם דִּשְׁכִינְתָּא אִתְפָּרְשַׁת מִקּוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמַר (ישעיה נ א) וּבְפִשְׁעִיכֶם שֻׁלְּחָה אִמְּכֶם, וְאִשְׁתָּאַר קוּדְשָׁא בְּרִיךְ הוּא יְחִידָאי בְּלָא מַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב (ישעיה נז א) הַצַּדִּיק אָבָד, מַאי אָבָד, אָבַד לְמַטְרוֹנִיתָא, וּבְגִין דָּא לֹא טוֹב היוֹת אָדָם לְבַדּוֹ (בראשית ב יח) אֱעִִשֶׂה לּוֹ עִזֶר כְּנֶגְדּוֹ (שם), דָא אָחֳרָא, דְלֵית אִיהִי בַת זוּגֵיהּ, מִסִּטְרָא דְעִץ הַדַּעַת טוֹב וָרָע, בְּאִסּוּר וְהֶיתֵּר טוּמְאָה וְטַהֲרָה כָּשֵׁר וּפָסוּל דַּם טָהוֹר וְדַם נִדָּה, וּבְגִין דָּא אוּקְמוּהוּ זָכָה נַעֲשֶׂה לּוֹ עִזֶר, לֹא זָכָה כְּנֶגְדּוֹ, דְּאִסְתַּלַּק מִנֵּיהּ אִתְּתָא דְאִיהִי עִץ הַחַיִּים, דְּאִתְּמַר בָּהּ (משלי ג יה) עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהַבְתָּ (קהלת ט ט), דַּעֲלָהּ אִתְּמַר (בראשית ג כב) וְלָקַח גַּם מֵעִץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם, דְּאִיהוּ הֲוָה חָרוּת עַל הַלּוּחוֹת, חֵירוּ מִמַּלְאַךְ הַמָּוְת, חֵירוּ מִשִּׁעִִבּוּד מַלְכִיּוֹת, חֵירוּ מִכָּל מַרְעִין בִּישִׁין, מֵעֲנִיּוּתָא וְטִפְּשׁוּתָא וְצַעֲרָא וְדוֹחֲקָא וְכַפְנָא, וַעֲלָהּ אִתְּמַר (דברים ח ט) אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם וכו'.</p>\n<p>אִסְתַּלַּק מִינֵיהּ, וְאִתְיַיהִב לֵיהּ אָחֳרָא מִסִּטְרָא דְסִיהֲרָא, דְאִתְּמַר בָּהּ (קהלת ג ב) עִת לָלֶדֶת וְעִת לָמוּת וכו', דְּאִיהִי פַלְגוּ דִילָהּ חַיִּים עוּתְרָא, וּפַלְגוּ דִילָהּ מָוְת עֲנִיּוּתָא, כְּגַוְונָא דְלִבָּא דְאִתְּמַר בֵּיהּ (שם י ב) לֵב חָכָם לִימִינוֹ וְלֵב כְּסִיל לִשְׂמֹאלוֹ, תְּרֵין בְּשׁוּתָּפוּ, וּבְגִין דָּא אִם זָכָה עִזֶר בְּמִלּוּיָא דְסִיהֲרָא, וְאִם לָא זָכָה כְּנֶגְדּוֹ בְּחֶסְרוֹנָה דְסִיהֲרָא.</p>\n<p>עֲרָיוֹת מִסִּטְרָא דְי\"ה, עִ\"ר יָ\"ה תֵעוֹר קַשְׁתֶּךָ (חבקוק ג ט), עֲרָיוֹת מִסִּטְרָא דְו\"ה לֹא תִקְרְבוּ לְגַלּוֹת עִ\"ר וָ\"ה (ויקרא יח ו), וְדָא לִילִי\"ת דְּאִיהִי עִִרְוַת אִשָּׁה וּבִתָּהּ (שם יז), דְּאִינוּן ה\"ה, עִִרְוַת כַּלָּתְךָ (שם טו) דָּא י' זְעִירָא דְאדנ\"י, דְּאִיהִי כַּלָּה הָאֲמוּרָה בְּשִׁיר הַשִּׁירִים. תָּא חֲזִי שְׁכִינְתָּא תַּתָּאָה אִתְקְרִיאַת בִּתָּהּ מִסִּטְרָא דְאִימָּא עִלָּאָה, כַּלָּה מִסִּטְרָא דְכָּ\"ל כָּ\"ל ה', אָחוֹת מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא, שְׁאֵר בְּשָׂרוֹ (שם ו) מִסִּטְרָא דְהַהוּא דְאִתְּמַר בֵּיהּ (בראשית ו ג) בְּשַׁגַּם הוּא בָשָׂר, מִסִּטְרָא דְּדַרְגֵּיהּ.</p>"],[9500011182,"<p>בְּרֵאשִׁית תְּרֵי שְׁבָ\"א, וְאִינוּן תְּרֵין נְקוּדִין תְּרֵי יְצִירוֹת, דְּאִתְּמַר בְּהוֹן (בראשית ב יט) וַיִּיצֶר יהו\"ה אלהי\"ם מִן הָאֲדָמָה כָּל חַיַּת הַשָּׂדֶה וְאֵת כָּל עוֹף הַשָּׁמַיִם, וַיָּבֵא אֶל הָאָדָם לִרְאוֹת מַה יִּקְרָא לוֹ וכו'. תָּא חֲזִי כַּמָּה נִשְׁמָתִין וְכַמָּה צִיּוּרִין צִיֵּיר קוּדְשָׁא בְּרִיךְ הוּא בְּדִיּוֹקְנָא דְמֶרְכָּבוֹת דִּלְעִילָא, דְאִינוּן חַיּוֹת הַקֹּדֶשׁ, דְּיָרְתִין בְּנֵי נָשָׁא נִשְׁמָתִין מִנַּיְיהוּ, וְאַיְיתֵי קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם בְּגִלְגוּלָא עַל כֻּלְּהוּ, לִרְאוֹת מַה יִּקְרָא לוֹ, וְלָא אַשְׁכַּח עִזֶר בְּהוֹן, הֲדָא הוּא דִכְתִיב (שם יח) וּלְאָדָם לֹא מָצָא עִזֶר כְּנֶגְדּוֹ, וְאִיהוּ קָרָא לוֹן לְכָל חַד שְׁמָהָן כְּפוּם חֵילָא דִלְעִילָא, דְּאִתְּמַר בְּהוֹן (ישעיה מ כו) הַמּוֹצִיא בְמִסְפָּר צְבָאָם לְכֻלָּם בְּשֵׁם יִקְרָא, לְכָל חַיָּה וּמַלְאָךְ וְאוֹפַן קָרָא לוֹן בְּשֵׁם יָדוּעַ, לְכָל חַד עַל מַתְכּוּנְתּוֹ בַּעֲבוֹדָתוֹ וּבְמִשְׁמַרְתּוֹ.</p>\n<p>תָּא חֲזִי אָדָם הֲוָה יָדַע כָּל מַלְאָךְ וְאוֹפַן וְחַיָּה וְשָׂרָף, כָּל חַד דַּהֲוָה מְמַנָּא עַל שְׁלִיחוּתֵיהּ, וַהֲוָה יָדַע כָּל שְׁמָא דְכָל חַד דַּהֲוָה כְּפוּם שְׁלִיחוּתֵיהּ, וְהָכִי הֲוָה קָרֵי לֵיהּ, דְּהָכִי אַשְׁכַּחְנָא בְּסֵפֶר רזיא\"ל דְּאִתְיְהֵיב לְאָדָם קַדְמָאָה, דְמטטרו\"ן קָרָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא שְׁמָהָן סַגִּיאִין, לְזִמְנִין אִתְקְרֵי מיטטו\"ר (מי\"מטור) בְּזִמְנָא דִמְמַנָּא עַל מִטְרָא וּלְזִמְנִין אִתְקְרֵי פתחו\"ן סגרו\"ן (אטימו\"ן) (נ\"א אטמון), אטמו\"ן בְּזִמְנָא דְאִיהוּ אוֹטֵם חוֹבִין דְּיִשְׂרָאֵל, סגרו\"ן בְּזִמְנָא דְסָגַר תַּרְעִין דִּצְלוֹתָא, פתחו\"ן בְּזִמְנָא דְפָתַח תַּרְעָא דִצְלוֹתָא, (פסקו\"ן) (נ\"א פיסקו\"ן) בְּזִמְנָא דְפוֹסֵק הֲלָכוֹת דְּמַתְנִיתִין בִּמְתִיבְתָּא תַּתָּאָה, וְהָכִי כָּל שְׁמָהָן כְּפוּם שְׁלִיחוּתֵיהּ, וְהָכִי כָּל מַלְאָךְ אִשְׁתַּנִּי שְׁמֵיהּ כְּפוּם שְׁלִיחוּתֵיהּ, הֲדָא הוּא דִכְתִיב (שופטים יג יח) לָמָּה זֶּה תִּשְׁאַל לִשְׁמִי וְהוּא פֶּלִאי, וּכְפוּם נִיסָא דְעָבְדִין הָכִי אִיהוּ שְׁמַיְיהוּ.</p>\n<p>וּלְכָל שְׁלִיחוּתָא וּשְׁלִיחוּתָא דִלְהוֹן אִית רִגְעָא וְשַׁעִִתָּא יְדִיעָא, וּמַזָּל יְדִיעַ, וְיוֹם יְדִיעַ, וְכֹכָב יְדִיעַ, וְתַמָּן אִשְׁתַּנִּי, הַאי מַלְאָךְ אִתְקְרֵי בַּשִּׁשִּׁים רִבּוֹא שְׁמָהָן דְּמַלְאָכַיָּא, הוּא אִתְקְרֵי חסדיא\"ל בְּזִמְנָא דְעָבִיד חֶסֶד עִם עָלְמָא, גַּבְרִיאֵ\"ל בְּזִמְנָא דְעָבִיד גְּבוּרָה בְעָלְמָא, סתוריא\"ל בְּזִמְנָא דְסָתִיר בְּנֵי עָלְמָא בְגַדְפוֹי מֵאִלֵּין מַלְאֲכֵי חַבָּלָה, הֲדָא הוּא דִכְתִיב (תהלים צא ד) וְתַחַת כְּנָפָיו תֶּחְסֶּה צִנָּה, וְאִתְקְרֵי חתמיא\"ל בְּזִמְנָא דְחָתִים זַכְוָון וְחוֹבִין עַל בְּנֵי עָלְמָא, כתביא\"ל בְּזִמְנָא דְכָתַב חוֹבִין וְזַכְוָון.</p>\n<p>וְכָל מַלְאָכָא כְּפוּם שְׁמֵיהּ אִית לֵיהּ קְרָא בְאוֹרַיְיתָא, כתביא\"ל עַל שֵׁם (שמות לב טז) וְהַמִּכְתָּב מִכְתַּב אלהי\"ם הוּא וְגוֹמֵר, זכריא\"ל עַל שֵׁם זוֹכֵר בְּרִית אָבוֹת, וְאִית לֵיהּ קְרָא זָכְרֵנוּ לְחַיִּים, וְאִתְכַּפְיָא בְּזָכוֹר, שמריא\"ל בְּשָׁמוֹר, חסדיא\"ל בְּחֶסֶד, גַּבְרִיאֵ\"ל בִּגְבוּרָה, צדקיא\"ל בְּצֶדֶק, רְפָאֵ\"ל (ברפואה, יתוא\"ל) בְּתִפְאֶרֶת, מלכיא\"ל בַּמַּלְכוּת, לֵית מַלְאָךְ דְּלֵית לֵיהּ עִקָּרָא וִיסוֹדָא בִסְפִירָן, וְכָל סְפִירָה אִית לָהּ שֵׁם יְדִיעַ וַהֲוַיָּ\"ה יְדִיעָה, וְכָל שְׁמָהָן תַּמָּן אִית לוֹן עִקָּרָא וִיסוֹדָא.</p>\n<p>וְהַאי כְּלָלָא נְקוֹט בִּידָךְ דְּכָל מְמַנָּן דִּלְעִיל שְׁמָהָן דִּלְהוֹן תַּלְיָין בִּסְפִירָן וּשְׁמָהַתְהוֹן כָּל חַד אִית לֵיהּ קְרָא עַל שֵׁם שְׁמָא דִילֵיהּ.</p>\n<p>וְכָל מַלְאָכַיָּא דְסוּסֵיהוֹן סוּסֵי אֶשָּׁא, וּמֶרְכָּבוֹתֵיהֶן אֶשָּׁא וְקַשְׁתּוֹתֵיהוֹן אֶשָּׁא וְרוֹמְחֵיהוֹן אֶשָּׁא, וְכָל מָאנֵי קְרָבָא דִלְהוֹן אֶשָּׁא, יְסוֹדֵיהוֹן בִּגְבוּרָה, וּמַלְאֲכֵי חַבָּלָה דְאִנּוּן אֶשָּׁא, יְסוֹדָא דִלְהוֹן בְּגֵיהִנָּם, וְאִית מַלְאָכַיָּא דְאִתְּמַר בְּהוֹן (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת, יְסוֹדָא דִלְהוֹן בְּעַמּוּדָא דְאֶמְצָעִיתָא, וְאִית מַלְאָכַיָּא דְאִינוּן מִמַּיָּא דִרְקִיעָא, דְאִתְּמַר בְּהוֹן (שם קמח ד) וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם, מִסִּטְרָא דִימִינָא, כֻּלְּהוֹן עִקָּרֵיהוֹן לְעִילָא, וְלֵית מַלְאָכָא דְלָא אִשְׁתַּכַּח בֵּיהּ שֵׁם יהו\"ה, דְּאִשְׁתַּכַּח בְּכָל אֲתַר, כְּגַוְונָא דְנִשְׁמָתָא דְאִשְׁתַּכְּחַת בְּכָל אֵבֶר וְאֵבֶר, וּבְגִין דָּא אִית לְבַר נַשׁ לְאַמְלָכָא יהו\"ה בְּכָל סְפִירָן, וּבְכָל כָּרְסַיָּין, וּבְכָל מַלְאָכִין, וּבְכָל אֵבֶר וְאֵבֶר דְּבַר נַשׁ, דְּלֵית אֲתַר פָּנוּי מִנֵּיהּ לָא בְּעִלָּאִין וְלָא בְתַתָּאִין, יהו\"ה לָא אִתְקְרֵי בְּיִחוּדָא דְאַרְבַּע אַתְוָון אֶלָּא בְּעִלַּת הָעִלּוֹת דִּמְיַחֵד לוֹן, וּבְגִין דְּאִיהוּ מְיַחֵד</p>"],[9500011183,"<p>אַרְבַּע אַתְוָון, בֵּיהּ אִתְקְרִיאוּ יהו\"ה בְּיִחוּדָא חֲדָא יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד, וּבְגִין דָּא שַׁוִּי אֱמוּנָה דְיִשְׂרָאֵל בְּאַרְבַּע אַתְוָון אִלֵּין, וְכָל שְׁמָהָן שַׁוִּי כִּנּוּיִין לִשְׁמָא דָא, לֵית שְׁמָא עַד אֵין סוֹף וְעַד אֵין תַּכְלִית רַבְרְבָא וְשָׁלְטָנָא מִן דָּא, לְעִילָא עַד אֵין סוֹף, וּלְתַתָּא עַד אֵין תַּכְלִית, וְכָל חֲיָילִין וּמַשִּׁרְיָין מִנֵּיהּ דַּחֲלִין וּמִזְדַּעִִזְעִין.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם (איהי) אֶת, בַּת יְחִידָה אִיהִי בַּת מֶלֶךְ פְּנִימָה, (איהי) אֶת אֲמָתָא דִילָהּ, וַעֲלָהּ אִתְּמַר (בראשית ב כא) וַיַּפֵּל יהו\"ה אלהי\"ם תַּרְדֵּמָה עַל הָאָדָם וַיִּישָׁן וכו', מַאי וַיִּסְגּוֹר, פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, וִירִיחוֹ סוֹגֶרֶת וּמְסוּגֶרֶת (יהושע ו טו), מַאי וִירִיחוֹ, דָא אִיהִי יָרֵחַ דְּאִיהִי גוּפָא דִילָהּ, אֲמָתָא מִבְּרַתָּא דְמַלְכָּא, דְאִיהִי נְקוּדָּה דִילָהּ, סוֹגֶּרֶת וּמְסוּגֶּרֶת מִלְּגָאו, כְּגַוְונָא דָא כּ.</p>\n<p>וּבְגִינָהּ אִתְּמַר (שמות כה כז) לְעְִמַּת הַמִּסְגֶּרֶת תִּהְיֶינָה הַטַּבָּעוֹת וְגוֹמֵר, מַאי הַטַּבָּעוֹת אִלֵּין תְּרֵין אוּדְנִין דְּלִבָּא דְאִינוּן עֲגוּלִין כַּטַּבָּעוֹת, וְלִבָּא אִיהוּ לִשְׂמָאלָא, הָכִי פָּתוֹרָא צָרִיךְ לִשְׂמָאלָא, שֻׁלְחָן בַּצָּפוֹן, לְבָתִּים לְבַדִּים (שם), מַאי לְבָתִּים אִינוּן תְּרֵי בָתֵּי לִבָּא, מַאי לְבַדִּים אִינוּן תְּרֵין כֻּלְיָין, תַּרְוַיְיהוּ לְבָר, עֲלַיְיהוּ אִתְּמַר (שם כו כד) וְהָיוּ תוֹאֲמִים מִלְּמַטָּה, תְּרֵי כַּנְפֵי רֵיאָה, וְיַחְדָּיו יִהְיוּ תַמִּים עַל רֹאשׁוֹ, וּבְגִין דִּשְׁמִיעָה תַּלְיָא בְלִבָּא, אוּקְמוּהוּ מָארֵי מַתְנִיתִין הַלֵּב שׁוֹמֵעַ.</p>\n<p>תָּא חֲזִי, אִתְּמַר בְּהַאי צֵלָע (בראשית ב כב) וַיִּקַּח, וּלְבָתַר וַיִּבֶן יהו\"ה אלהי\"ם אֶת הַצֵּלָע, מַאי וַיִּבֶן, אֶלָּא (מלכים א ח יג) בָּנֹה בָנִיתִי בֵּית זְבוּל לָךְ וְגוֹמֵר, וְהַבַּיִת בְּהִבָּנוֹתוֹ אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה, תְּרֵי בָּתֵּי לִבָּא אִינוּן תְּרֵי בִּנְיָנִין דְּהַאי קְרָא, הֲדָא הוּא דִכְתִיב (שם ו ז) וְהַבַּיִת בְּהִבָּנוֹתוֹ דָּא בַּיִת רִאשׁוֹן, אֶבֶן שְׁלֵמָה מַסָּע נִבְנָה דָּא בַּיִת שֵׁנִי, וּלְקִבְלַיְיהוּ אָמַר בָּנֹה בָּנִיתִי תְּרֵין בִּנְיָנִין, חַד אִתְקְרִיאַת בִּנְיָינָא דְאִימָּא עִלָּאָה, וְתִנְיָינָא בִּנְיָינָא דְאִימָּא תַתָּאָה.</p>\n<p>וְעוֹד וַיִּבֶן, לִישָׁנָא וְאִבָּנֶה גַם אָנֹכִי מִמֶּנָּה (בראשית ל ג), בִּנְיָינָא דְיִבּוּם, וּכְמָה דְהַאי נְקוּדָה אִיהִי סוֹגֶרֶת וּמְסוּגֶרֶת, הָכִי צְרִיכָה בְּרַתָּא דְאִיהִי בְּתוּלָה, לְמֵיהֱוִי סְגוּרָה וּמְסוּגֶרֶת בְּבֵית אָבִיהָ, (שם כד) בְּתוּלָה וְאִישׁ לֹא יְדָעָהּ (שם כד טז), וַתֵּרֶד הָעַיְנָה דָּא בַּת עִינָא, סוֹגֶרֶת וּמְסוּגֶרֶת בְּעִינָא, וּתְלַת גַּוָּונִין סַחֲרִין לָהּ, וַעֲלַיְיהוּ אִתְּמַר (איוב לג כד) הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר. וְכַד נָחִית לוֹן מֹשֶׁה אוֹרַיְיתָא לְיִשְׂרָאֵל מִינָהּ, אָמַר הֱיוּ נְכוֹנִים לִשְׁלֹשֶׁת יָמִים אַל תִּגְּשׁוּ אֶל אִשָּׁה (שמות יט טו), שְׁלֹשֶׁת יָמִים לָקֳבֵל תְּלַת גַּוָּונִין דְּעִינָא, וְאִיהִי טְמִירָא וּסְתִירָא בְּהוֹן, וְאִישׁ לֹא יְדָעָהּ בְּהוֹן, עַד דְּאִתְפַּשְׁטַת מִנַּיְיהוּ.</p>\n<p>וּבְהַהוּא זִמְנָא דְאִתְפַּשְׁטַת מֵאִלֵּין לְבוּשִׁין, אִתְיַחֲדַת עִם בַּעִִלָהּ בְּקִרוּב בִּשְׂרָא, הֲדָא הוּא דִכְתִיב (בראשית ב כג) עִִצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי לְזֹאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לוּקֳחָה זֹּאת, עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד, דְּכַךְ דַּרְכָּא לְאִתְיַחֲדָא דְכַר וְנוּקְבָא בְּקִרוּב בָּשָׂר, וְדָא דִבּוּקָא (נ\"א קורבא) דְּיִחוּדָא דִלְעִילָא, דְלָא יְהֵא דָבָר חוֹצֵץ, וּבְגִין דָּא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, דְּכַד בַּר נַשׁ מְצַלֵּי וּמְיַיחֵד קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיהּ דְּלָא יְהֵא דָבָר חוֹצֵץ בֵּינוֹ לְבֵין הַקִּיר, שְׁכִינְתֵּיהּ (קרקוריה דקיר קירות הלב), דְּלָא יַעֲבִיד פִּרוּד וְקִצּוּץ בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְרָזָא דְמִלָּה וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִים הָאָדָם וְאִשְׁתּוֹ (שם כה), עֲרוּמִים בְּקִרוּב בִּשְׂרָא בְּלָא לְבוּשָׁא כְּלָל, וּבְהַהוּא זִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ כַּחֲדָא בְּלָא לְבוּשָׁא כְּלָל, אִתְּמַר בֵּיהּ (ישעיה ל כ) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ, וְהָיוּ עִינֶיךָ רוֹאוֹת אֶת מוֹרֶיךָ.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אַבָּא, מַאי סִיּוּמָא דִקְרָא (בראשית ב כה) וְלֹא</p>"],[9500011184,"<p>יִתְבּוֹשָׁשׁוּ, אָמַר לֵיהּ בְּרִי בַּאֲתַר דְּאִית עִִרְוָה אִית בֹּשֶׁת, וְדָא אִיהוּ יָרֵא בֹּשֶׁת, וּמָאן דְּלֵית לֵיהּ בֹּשֶׁת בְּוַדַּאי לָא עָמְדוּ רַגְלֵי אֲבָהָתוֹי עַל טוּרָא דְסִינַי, וּבֹשֶׁת אִיהוּ בִּתְלַת גַּוָּונִין חִוָּור וְסוּמַק וְיָרוֹק בְּאַנְפִּין, דְּאִתְּמַר בְּהוֹן (ישעיה כט כב) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב בְּגַוָּון סוּמַק וְיָרוֹק, וְלֹא עַתָּה פָּנָיו יֶחוָורוּ (שם) בְּגַוָּון חִוָּור, וְאִלֵּין תְּלַת גַּוָּונִין דְּאִית בְּהוֹן בֹּשֶׁת אִלֵּין אִינוּן תְּלַת גַּוָּונִין דִּתְלַת קְלִיפִין דֶּאֱגוֹזָא, דְּאִינוּן עִִרְיָין דִּבְהוֹן אִתְלַבְּשַׁת קֶשֶׁת וְאִתְחַזְיָיא בְּהוֹן.</p>\n<p>וּבְגִין דְּאִינוּן עֲרָיוֹת תְּלַת קְלִיפִין, אִתְּמַר בְּהוֹן אֵין דּוֹרְשִׁין בַּעֲרָיוֹת בִּשְׁלֹשָׁה, וַאֲסִיר לְאִסְתַּכְּלָא בְּהוֹן, וּבְגִין דָּא אֲסִיר לְעַמָּא קַדִּישָׁא לְאִסְתַּכְּלָא בְּגַוָּונִין דְּקֶשֶׁת, וְדָא רָזָא דְעָרְלָה דְאִית לָהּ תְּלַת קְלִיפִין, דְּצָרִיךְ לְאַעֲבָרָא לוֹן מֵאוֹת בְּרִית קֹדֶשׁ, וּמִיָּד וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם (בראשית ט טז), וְעַל אִלֵּין תְּלַת קְלִיפִין אִתְּמַר (שמות ג ה) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ, וּמִיָּד וּרְאִיתִיהָ, וּבְזִמְנָא דְמֹשֶׁה הֲוָה מִתְלַבֵּשׁ בְּהוֹן, מַה כְּתִיב בֵּיהּ (שם) אַל תִּקְרַב הֲלוֹם, מִיָּד דְּאִתְפַּשַּׁט מִנַּיְיהוּ אִתְקַרִיב תַּמָּן.</p>\n<p>וְדָא רָזָא דְקָרְבָּנָא, דַהֲוָה נָחִית אֶשָּׁא לְאַדְלָקָא אִלֵּין תְּלַת קְלִיפִין, הֲדָא הוּא דִכְתִיב (ויקרא ו ב) זֹאת תּוֹרַת הָעוֹלָה הִיא הָעוֹלָה עַל מוֹקְדָה וְגוֹמֵר, הָא תְּלַת גַּוָּונִין דְּאֶשָּׁא, דַהֲווֹ נָחֲתִין בִּתְלַת צְלוֹתִין לְאַדְלָקָא וּלְאוֹקָדָא אִלֵּין קְלִיפִין, וּבְהַהוּא זִמְנָא הֲוָה קוּדְשָׁא בְּרִיךְ הוּא מִתְקָרֵב בִּשְׁכִינְתֵּיהּ, וַהֲווֹ מִתְקָרְבִין אַתְוָון דִּילֵיהּ י' בְּה' ו' בְּה', וּבְזִמְנָא דַהֲווֹ מִתְלַבְּשִׁין בְּאִלֵּין קְלִיפִין, אִתְּמַר בְּהוֹן (שם ינ ו) לֹא תִקְרְבוּ לְגַלּוֹת עִִרְוָה, וְלָא צָרִיךְ לְקָרְבָא אַתְוָון י' בְּה' ו' בְּה'.</p>\n<p>וּבְגִין דָּא תַּקִּינוּ תְּלַת צְלוֹתִין בְּכָל יוֹמָא, לְאַעֲבָרָא תְּלַת קְלִיפִין אִלֵּין דְּעָרְלָה מֵאוֹת בְּרִית דְּאִיהִי שְׁכִינְתָּא, וּבְדָא שַׁרְיָא בִּתְלַת גַּוָּונִין נְהִירִין, דְּאִינוּן כֹּהֲנִים לְוִיִּים וְיִשְׂרָאֵל, דַּעֲלַיְיהוּ אִתְּמַר (שיר ז ב) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב, וְאִינוּן נְעִילַת חַגִּין וּזְמַנִּין וּמוֹעֲדִין, דַּעֲלַיְיהוּ אִתְּמַר (שמות כג יד) שָׁלֹשׁ רְגָלִים תָּחֹג לִי בַּשָּׁנָה, תְּלַת קְלִיפִין עֲלַיְיהוּ אִתְּמַר (בראשית ג כא) וַיַּעֲשׂ יהו\"ה אלהי\"ם לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם, בְּקַדְמֵיתָא כָּתְנוֹת אוֹר, וּלְבָתַר דְּחָאבוּ כָּתְנוֹת עוֹר, מֵעוֹר דְּאִיהוּ מִשְׁכָא דְחִוְיָא, וּלְשַׁבְעִין שְׁנִין אִתְפַּשַּׁט הַהוּא (חויא) (נ\"א משכא) מִנֵּיהּ.</p>\n<p>דִּתְלַת גַּוָּונִין דִּלְבוּשִׁין דִּשְׁכִינְתָּא אִינוּן תְּלַת וָוִי\"ן דְּוַיִּסַּע וַיָּבֹא וַיֵּט, בְּזִמְנָא דְמִתְעַבְּרִין כָּתְנוֹת עוֹר דְּחִוְיָא, נַהֲרִין תְּלַת גַּוָּונִין דִּנְהוֹרָא דִשְׁכִינְתָּא, וּמִיָּד וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם, וְאִינוּן תְּלַת וָוִי\"ן אִינוּן תְּלַת גַּגִּין דְּאָת ב, חַד לִשְׁמַיָּא וְחַד לְאַרְעָא וְחַד לְיַמָּא, וּמֵהַאי ב' תַּלְיָין שִׁבְעִין גַּוָּונִין, וְאִינוּן שִׁבְעִין וּתְרֵין, דַּעֲלַיְיהוּ אִתְּמַר (ישעיה יט א) הִנֵּה יהו\"ה רוֹכֵב עַל עָב קַל וּבָא מִצְרַיִם, עַל עָ\"ב בְּשַׁבְעִין וּתְרֵין גַּוָּונִין נְהִירִין, וּמִיָּד (שם) וְנָעוּ אֱלִילֵי מִצְרַיִם מִפָּנָיו.</p>\n<p>וְאִינוּן תְּלַת גַּוָּונִין רְמִיזִין בְּה', ה' תְּלַת גַּגִּין דִּילָהּ אִינוּן לְבוּשִׁין נְהִירִין דִּבְּרַתָּא דְמַלְכָּא, דְּאִיהִי י' בַּת עַיִן, וְאִיהִי חָמֵשׁ אַלְפִין שְׁנִין דִּבְּרִיאַת עָלְמָא, וְאִיהִי ה' זְעִירָא דְאַבְרָהָם דְּדַרְגֵּיהּ חֶסֶ\"ד, דְּסָלִיק לְשַׁבְעִין וּתְרֵין, ה' י' מִן אלהי\"ם. ה\"י מִן יו\"ד ה\"א וא\"ו ה\"א. (נ\"א יו\"ד ה\"י וא\"ו ה\"י). ה' לְבוּשָׁא דְכַסִּי עַל י'.</p>\n<p>בְּרֵאשִׁית כִּי בָאֵשׁ יהו\"ה נִשְׁפָּט (שם כו טז), דְּאִינוּן כָּתְנוֹת עוֹר דְּצָרִיךְ בְּהוֹן הַבְדָּלָה, כַּד אָמְרִין יִשְׂרָאֵל בּוֹרֵא מְאוֹרֵי הָאֵשׁ, וְאָמְרִין הַמַּבְדִּיל בֵּין אוֹר לְחֹשֶׁךְ.</p>"],[9500011185,"<p>. חֹשֶׁךְ אוּכַם, כָּתְנוֹת עוֹר דִּילֵיהּ אוּכְמִין, דְּאִתְּמַר בְּהוֹן (שיר ה יא) שְׁחוֹרוֹת כָּעוֹרֵב, (בראשית ג א) וְהַנָּחָשׁ הָיָה עָרוּם מִנַּיְיהוּ, דִּלְכָל חַיָּה בָרָא לְבוּשִׁין, וּלְכָל בִּרְיָין דְּאִתְבְּרִיאוּ בְּשִׁית יוֹמֵי בְּרֵאשִׁית, וְאִשְׁתָּאֲרוּ גוּפִין דְּמַזִּיקִין לְמֶעֱבַד וְלָא עָבִיד לוֹן, בְּגִין דַּהֲוָה עִִרֶב שַׁבָּת, וְדָא אִיהוּ (בראשית ב ג) אֲשֶׁר בָּרָא אלהי\"ם לַעֲשׂוֹת, וּבְגִין דָּא וְהַנָּחָשׁ הָיָה עָרוּם מִכָּל חַיַּת הַשָּׂדֶה אֲשֶׁר עָשָׂה יהו\"ה אלהי\"ם (בראשית ג א), דִּלְכֻלְּהוּ עָבַד לְבוּשִׁין, וְלֵיהּ לָא עָבַד, בְּגִין דַּהֲווֹ מַזִּיקִין דְּעָלְמָא.</p>\n<p>וְאַמַּאי לָא עָבִיד לוֹן, בְּגִין דַּהֲוָה לֵיהּ לְמִבְרֵי לְאָדָם עִִרֶב שַׁבָּת, וּבְגִינֵיהּ לָא בָּרָא לוֹן, וּבְגִין דָּא עָאל קִנְאָה בְּלִבֵּיהּ דְּחִוְיָא עִם אָדָם, בְּגִין דְּאִשְׁתָּאַר עָרוּם בְּגִינֵיהּ בְּלָא לְבוּשִׁין, וְאִיהוּ גָרַם לְבָתַר דְּאִתְפַּשַּׁט אָדָם מִלְּבוּשׁוֹי, וְיָרִית לוֹן נִמְרוֹד וְעִשָׂו, דַּהֲוָה עִשָׂו דִּיּוֹקְנֵיהּ דְּחִוְיָא, וּבְגִין דָּא וְהַנָּחָשׁ הָיָה עָרוּם, עָרוּם לְבִישׁ, דְּגָרַם בְּעָרְמָה דִילֵיהּ נוּקְבָא בִישָׁא סַם הַמָּוְת מִיתָה לְאָדָם וּלְאִתְּתֵיהּ, וְעָרְמָה דִּילֵיהּ הֲוָה דְפַתִּי לְחַוָּה, בְּגִין דְּדַעִִתָּן שֶׁל נָשִׁים קַלָּה, וּמַה אָמַר לָהּ (שם) וַיֹּאמֶר הַנָּחָשׁ אֶל הָאִשָּׁה אַף כִּי אָמַר אלהי\"ם לֹא תֹאכְלוּ מִכֹּל עִץ הַגָּן, וְקוּדְשָׁא בְּרִיךְ הוּא לָא אָמַר, אֶלָּא מִכֹּל עִץ הַגָּן אָכֹל תֹּאכֵל, דְּאִיהוּ לָא מַנִּי לֵיהּ דְּלָא לְמֵיכַל אֶלָּא מֵעִץ הַדַּעַת טוֹב וָרָע, דְּאִיהוּ עִרְבוּבְיָא דְטוֹב וָרָע, אִילָנָא דְשִׁקְרָא, חַד בְּלֵב וְחַד בַּפֶּה, לִבֵּיהּ מָלֵי שִׁקְרָא, וּפַתִּי בְּפוּמֵיהּ בְּמִלִּין דִּקְשׁוֹט.</p>\n<p>וְחִוְיָא בִּישָׁא אַעֲבַר הָכָא עַל לֹא תַעֲנֶה בְרֵעֲךָ עִד שָׁקֶר (שמות כ יג), וְעַל לֹא תִרְצַח, וְעַל לֹא תִנְאָף, וְעַל לֹא תִגְנוֹב, וְלֹא תִשָּׂא אֶת שֵׁם יהו\"ה אלהי\"ך לַשָּׁוְא, עַל לֹא תַעֲנֶה בְרֵעֲךָ דְּסָהִיד שִׁקְרָא דְאָמַר (אף כי אמר אלהי\"ם לא תאכלו מכל עץ הגן ועל לא תגנוב דגנב דעת חוה כגוונא דא דאמר אף כי אמר אלהי\"ם וגומר) כִּי יוֹדֵעַ אלהי\"ם כִּי בְּיוֹם אֲכָלְכֶם מִמֶּנּוּ וְנִפְקְחוּ עִינֵיכֶם וִהְיִיתֶם כֵּאלֹהִי\"ם יוֹדְעִי טוֹב וָרָע (בראשית ג ה), בְּגִין דְּלָא תֶהֱוָון בְּדִיּוֹקְנֵיהּ, וְעָבַר עַל לֹא תִנְאָף, דְּהִטִּיל זוּהֲמָא בְּחַוָּה, וְעָבַר עַל לֹא תִרְצַח, דְּקָטַל לְאָדָם וּלְחַוָּה, דְּהָכִי אָרְחָא דְיִצְרָא בִישָׁא מְפַתֵּי לִבְנֵי נָשָׁא, וּלְבָתַר סָלִיק וְאַלְשִׁין לֵיהּ, וְנָטִיל רְשׁוּ וְנָחִית וְנָטִיל נְשָׁמָה.</p>\n<p>בְּרֵאשִׁית דָּא בְּרִי\"ת, דְּאִתְּמַר בֵּיהּ עִץ הַחַיִּים, וְהָא אוּקְמוּהָ, וּבְהִפּוּכָא תְבִי\"ר, דְּגָרַם תְּבִירוּ לְאָדָם הָרִאשׁוֹן, וְדָא עִץ הַדַּעַת טוֹב וָרָע, טוֹב אִיהוּ אִילָנָא, הַהוּא דִכְתִיב (בראשית ג ו) וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעִץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעִינַיִם, וְאִיבָּא דִילֵיהּ רָע, כְּפוּם חֵיזוּ דִּילָהּ הָכִי הֲוָה (נ\"א איהו) אִתְחַזְיָא לָהּ מִלְּבָר, כְּגַוְונָא דְפוּמָא מִלִּין שַׁפִּירִין מִלְּבָר, וְלִבָּא מַלְיָיא טִנּוּפִין מִלְּגָאו, וְדָא לָא הֲוַת יָדְעָא דְסַם הַמָּוְת הֲוָה מִלְּגָאו דְאִיבָּא, הֲדָא הוּא דִכְתִיב וַ\"תִּקַּח מִ\"פִּרְיוֹ וַ\"תֹּאכַל, וַתִּתֵּן גַּם לְאִישָׁהּ וְגוֹמֵר (שם), הֲרֵי אִיבָּא דְאִילָנָא דְתַמָּן מָוְ\"ת (מלגאו גרם לה דאכלה).</p>\n<p>וְאִית קְלִיפִין דְּאִיבָּא דְּאִינוּן תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ וּתְהוֹם, דִּקְלִיפִין אִלֵּין אִינוּן רָע, מוֹחָא מִלְּגָאו טוֹב, אִילָנָא דְחַיֵּי קְלִיפִין דִּילֵיהּ שַׁפִּירִין וּמוֹחָא דִילֵיהּ שַׁפִּיר, וְדָא אִיהוּ עָפְיֵיהּ שַׁפִּיר וְאִנְבֵּיהּ שַׂגִּיא (דניאל ד ט), וְאִית אִילָנָא דְכוּלֵיהּ בִּישׁ, מוֹחָא וּקְלִיפָה כֻלְּהוּ מְרִירָן, וּמַיִּין דִּלְהוֹן מְרִירָן, הֲדָא הוּא דִכְתִיב (שמות טו כג) וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם וְגוֹמֵר, וַיּוֹרֵהוּ יהו\"ה עִץ וְגוֹמֵר, וּבֵיהּ וַיִּמְתְּקוּ הַמָּיִם, עִץ מָתוֹק דְּמִנֵּיהּ נָפְקִין עַנְפִין וְשָׁרָשִׁין, דְּאִתְּמַר בְּהוֹן (תהלים יט יא) וּמְתוּקִים מִדְּבַשׁ וְנֹפֶת</p>"],[9500011186,"<p>צוּפִים, וּבְגִין דָּא אִית עִץ דְּעַנְפִין דִּילֵיהּ מְתִיקָן, וְעִץ דְּעַנְפִין דִּילֵיהּ מְרִירָן, וְאִית מַיִּין מְתִיקָן וּמַיִּין מְרִירָן, דְּדָא לָקֳבֵל דָּא עָבַד קוּדְשָׁא בְּרִיךְ הוּא, וְאִית דְּאִיהוּ פַּלְגוּ דִילֵיהּ מְתִיקָא וּפַלְגוּ דִילֵיהּ מְרִירָא, וְדָא עִץ הַדַּעַת טוֹב וָרָע, כְּגַוְונָא דְכַסְפָּא מְעוּרָב בְּעוֹפָרֶת, וְאִית אִילָנָא דִקְלִיפִין דִּילֵיהּ בִּישִׁין מִלְּבָר וּמוֹחָא מְתִיקָא מִלְּגָאו, הָכִי תִשְׁכַּח בַּר נַשׁ בִּישׁ בְּמִלֵּי פוּמוֹי (נ\"א ובפומוי מפיק ביש מלבר) וְטַב בְּלִבֵּיהּ מִלְּגָאו, וְאִית מִפִּימוֹי טַב וְלִבֵּיהּ בִּישׁ, הַאי אִיהוּ עִץ הַדַּעַת טוֹב וָרָע, הָכָא מְקַנֵּן נָחָשׁ רַמַּאי.</p>\n<p>הָכִי אִיהוּ בַּר נַשׁ דְּתִשְׁכַּח לֵיהּ גּוּפֵיהּ שַׁפִּיר, וְסִימָנִין דִּילֵיהּ כֻּלְּהוּ שַׁפִּירָן, וְנִשְׁמָתֵיהּ נֶפֶשׁ חַיָּיבָא מִלְּגָאו, וְתִשְׁכַּח בַּר נַשׁ גּוּפֵיהּ בִּישׁ בְּכָל סִימָנִין דִּילֵיהּ, וְנִשְׁמָתֵיהּ מִלְּגָאו שַׁפִּירָא, דָא אִיהוּ צַדִּיק וְרַע לוֹ, אֲבָל מָאן דְּאִיהוּ טַב מִלְּבָר וְרַע מִלְּגָאו, אִיהוּ רָשָׁע וְטוֹב לוֹ, בְּגִין דְּלָא יְהֵא לֵיהּ חוּלָקָא בְעָלְמָא דְאָתֵי, טוֹב מִלְּבָר וּמִלְּגָאו צַדִּיק וְטוֹב לוֹ, בִּישׁ מִלְּגָאו וּמִלְּבָר רָשָׁע וְרַע לוֹ, וְהָא אוּקְמוּהָ.</p>\n<p>טַב מִלְּגָאו וּלְבוּשָׁא דִילֵיהּ בִּישׁ, דָּא אִיהוּ עָנִי וְרוֹכֵב עַל חֲמוֹר (זכריה ט ט), רַע מִלְּגָאו וּלְבוּשָׁא דִילֵיהּ שַׁפִּיר מִלְּבָר, עַל הַאי אִתְּמַר (קהלת י ז) רָאִיתִי עֲבָדִים עַל סוּסִים, וְכֹלָּא אִשְׁתְּמוֹדָע בְּעוֹבָדוֹי דְבַר נַשׁ, מָאן דְּאִיהוּ מִלְּגָאו, וְלַאו לְמַגָּנָא אוּקְמוּ קַדְמָאִין לֹא הַמֶּדְרָשׁ הוּא הָעִקָּר אֶלָּא הַמַּעֲשֶׂה הוּא הָעִקָּר, דְּשַׁטְיָין מִסְתַּכְּלִין בְּגוּפָא דְאִיהוּ לְבוּשָׁא, הֲדָא הוּא דִכְתִיב (איוב י יא) עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי, וְצַדִּיקַיָּא בְעוֹבָדִין טָבִין.</p>\n<p>וְעוֹד (שמות טו כה) וַיּוֹרֵהוּ יהו\"ה עִץ, דָּא מַטֶּה דְמֹשֶׁה, דַהֲוָה מִתְהַפֵּךְ מִמַּטֶּה לְנָחָשׁ וּמִנָּחָשׁ לְמַטֶּה, כְּגוֹן לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת (בראשית ג כד), וְדָא מטטרו\"ן, דְּבֵיהּ הֲוָה מִשְׁתַּמֵּשׁ מֹשֶׁה רַבֵּינוּ, כְּגַוְונָא דְעַמּוּדָא דְאֶמְצָעִיתָא דְהוּא מִשְׁתַּמֵּשׁ בֵּיהּ, וַהֲוָה מַנְהִיג תַּתָּאִין בֵּיהּ, אוּף הָכִי מֹשֶׁה דַהֲוָה כְּגַוְונָא דִילֵיהּ, הֲוָה מִשְׁתַּמֵּשׁ בְּמַטֶּה, וְאַמַּאי אִתְקְרֵי מטטרו\"ן מַטֶּה, דִלְזִמְנִין מַטֶּה כְּלַפֵּי זְכוּ לַצַּדִּיקַיָּא, וּלְזִמְנִין מַטֶּה כְּלַפֵּי חוֹבָא לְרַשִּׁיעַיָּא, וּבְגִין דָּא אִתְהַפַּךְ מִמַּטֶּה לְנָחָשׁ לְרַשִּׁיעַיָּא לְאַלְקָאָה לוֹן בֵּיהּ, וּמִנָּחָשׁ לַמַּטֶּה לַצַּדִּיקַיָּא לְמֵיהַב לוֹן בֵּיהּ אַגְרָא.</p>\n<p>דְּהָכִי אִיהוּ עַל הַאי מַלְאָכָא קוּדְשָׁא בְּרִיךְ הוּא, כְּגַוְונָא דְנִשְׁמָתָא דְרָכִיב עַל גּוּפָא, וְצַדִּיק בְּהַאי אֲתַר אִתְּמַר בֵּיהּ (שמואל ב כ״ג:ג׳) צַדִּיק מוֹשֵׁל יִרְאַת אלהי\"ם, בְּגִין דְּאִיהוּ מְהַפֵּךְ דִּינָא לְרַחֲמֵי, וּבְהַאי אֲתַר צָרִיךְ שִׁנּוּי מַעֲשֶׂה, בְּגִין דְּיִתְהַפַּךְ מִדִּינָא לְרַחֲמֵי, וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מָקוֹם, וְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ מִלְּגָאו, אִתְּמַר בֵּיהּ (מלאכי ג ו) אֲנִי יהו\"ה לֹא שָׁנִיתִי, דְּאִיהוּ רַחוּם וְחַנּוּן, לֵית בֵּיהּ דִּינָא כְלָל וְלָא שִׁנּוּיִין.</p>\n<p>וְכַד בַּר נַשׁ שַׁלִּיט עַל יִצְרֵיהּ, נֶהְפַּךְ נָחָשׁ לַמַּטֶּה, וְאִם יִצְרֵיהּ שַׁלִּיט עֲלֵיהּ, נֶהְפַּךְ מִמַּטֶּה לְנָחָשׁ, וּמִיָּד וַיָּנָס מֹשֶׁה מִפָּנָיו (שמות ד ג), מַאי וַיָּנָס, אֶלָּא הָכִא רְמִיז שִׁנּוּי מָקוֹם, דְּבָרַח מֵאַתְרֵיהּ וּמִקַּמֵּיהּ, וְדָא אִיהוּ רָזָא וַתִּפָּקַחְנָה עִינֵי שְׁנֵיהֶם (בראשית ג י), וּבְמַאי אִתְפַּקְחוּ, לְמִנְדַּע טוֹב וָרָע, דְּאִיהוּ מַטֶּה כְלִיל מִתַּרְוַיְיהוּ, כַּד אִתְהַפַּךְ מִנָּחָשׁ לַמַּטֶּה אִתְּמַר בֵּיהּ צַדִּיק וְטוֹב לוֹ, וְכַד אִתְהַפַּךְ מִמַּטֶּה לְנָחָשׁ אִתְּמַר בֵּיהּ רָשָׁע וְטוֹב לוֹ.</p>\n<p>בְּרֵאשִׁית דָּא מַחֲשָׁבָה, אלהי\"ם דָּא אִימָּא עִלָּאָה עוֹבָדָא, דְתַרְוַיְיהוּ דְחִילוּ וּרְחִימוּ, אֶת הַשָּׁמַיִם דָּא קָלָא, וְאֶת הָאָרֶץ דָּא דִבּוּרָא, וּבְכֹלָּא חָאבוּ אָדָם וְחַוָּה, אַפְרִישׁוּ בֵּין אַבָּא וְאִימָּא דְאִינוּן מַחֲשָׁבָה וְעוֹבָדָא, וּבֵין קוֹל וְדִבּוּר דְּאִינוּן בְּרָא וּבְרַתָּא, וּבְגִין דָּא וַיִּשְׁמְעוּ אֶת קוֹל יהו\"ה אלהי\"ם מִתְהַלֵּךְ בַּגָּן לְרוּחַ הַיּוֹם (שם), אֶ\"ת קוֹ\"ל דָּא</p>"],[9500011187,"<p>עַמּוּדָא דְאֶמְצָעִיתָא, וּשְׁכִינְתָּא עִמֵּיהּ, יהו\"ה אלהי\"ם אַבָּא וְאִימָּא, וְאִינוּן אַרְבַּע אַתְוָון יהו\"ה, י' אַבָּא ה' אִימָּא ו' בְּרָא ה' בְּרַתָּא, דְּאִינוּן מַחֲשָׁבָה וּמַעֲשֶׂה קָלָא וְדִבּוּרָא, (ורזא דמלה מחשבה מצטרפא למעשה ודא רזא יו\"ד דהיא י' וקלא ודבור דאיהו שמים וארץ וכל צבאם), קוֹל דַּהֲוָה אָזִיל בַּגָּן דָּא עַמּוּדָא דְאֶמְצָעִיתָא, שָׁמַע קָלֵיהּ דַּהֲוָה אָזִיל בְּגִנְּתָא בְּעַנְפֵי אִילָנָא, מֵהַהוּא אִילָנָא דְחָאב בֵּיהּ אָדָם קַדְמָאָה, דַּהֲוָה אָמַר אִילָנָא לְסמא\"ל חַיָּיבָא נָחָשׁ הַקַּדְמוֹנִי, רָשָׁע אַל תִּגַּע בִּי, וּבְאָן אֲתַר הֲוָה אָזִיל קָלָא בְּגִנְּתָא דְאִיהִי אדנ\"י דִינָ\"א, לְסִטְרָא דִשְׂמָאלָא, דְּאִתְּמַר בֵּיהּ (איוב א ו) וַיְהִי הַיּוֹם וַיָּבֹאוּ בְּנֵי הָאלהי\"ם לְהִתְיַצֵּב עַל יהו\"ה, וְדָא אִיהוּ לְרוּחַ הַיּוֹם, וּמַה הֲווֹ אָמְרִין בְּנֵי הָאלהי\"ם, אֶלָּא אָתוּ לְהִתְיַצֵּב עַל מֵימְרָא דַיהו\"ה, דְּכַד אָמַר קוּדְשָׁא בְּרִיךְ הוּא (בראשית א כו) נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ, אָמְרוּ אִינוּן מָה אָדָם וַתֵּדָעִהוּ (תהלים קמד ג), (ס\"א אמרו אינון מה אנוש כי תזכרנו וגומר) (שם ח ה).</p>\n<p>וְעוֹד וַיִּשְׁמְעוּ אֶת קוֹל יהו\"ה אלהי\"ם, הַהוּא קָלָא הֲוָה בְּגִנְּתָא דְאִיהִי שְׁכִינְתָּא, דְתַמָּן עִץ הַחַיִּים נָטוּעַ, חַוָּה גָרְמַת דְּאִתְעַקַּר אִילָנָא מִגִּנְתָא, וְאָדָם גָּרִים בְּמַחֲשַׁבְתָּא דִילֵיהּ דְּאִסְתַּלִּיק נְבִיעוּ דְאִילָנָא, דַהֲוָה נָחִית לְגִנְּתָא, וְאִשְׁתְּאָרַת יַבָּשָׁה, יהו\"ה דָּא אִילָנָא, ה\"ה עַנְפּוֹי וְשָׁרְשׁוֹי, ו' גּוּפָא דְאִילָנָא, י' אִיבָּא דִילֵיהּ, נְבִיעוּ דִילֵיהּ, נְקוּדָה דִילֵיהּ כְּגַוְונָא דָא יהו\"ה, דְּאִיהוּ אֶחָד וּשְׁמוֹ אֶחָד, וּמְנָלָן דְּאִתְקְרֵי נְבִיעוּ אֶחָד, כְּמָה דְאִתְּמַר (בראשית א ט) יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד, וְתֵרָאֶה הַיַּבָּשָׁה אדנ\"י.</p>\n<p>וּבְגִין דָּא וַיִּתְחַבֵּא הָאָדָם וְאִשְׁתּוֹ מִפְּנֵי יהו\"ה אלהי\"ם (שם ג ח), וְכִי יָכִיל בַּר נַשׁ לְאִתְכַּסְיָא מִנֵּיהּ, וְהָא כְּתִיב (ירמיה כג כד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם יהו\"ה, אֶלָּא כָּסּוּ פָנָיו חֲרֻלִּים (משלי כד לא), אִתְכַּסִּיאוּ אַנְפּוֹי מִבֹּשֶׁת, דְּאִתְפַּקְחוּ עִינַיְיהוּ וְחָזוּ מַה דְּעָבְדוּ לְעִילָא, דְגָרִימוּ לְאַעִִקָרָא אִילָנָא מֵאַתְרֵיהּ, וּנְבִיעוּ לְסַלְקָא מִתַּמָּן, וְדָא אִיהוּ וַיִּתְחַבֵּא הָאָדָם וְגוֹמֵר, תַּמָּן אִתְכַּסִּיאוּ אַנְפּוֹהִי, מִן בֹּשֶׁת, דְּתַמָּן חָאבוּ, בַּמֶּה דַהֲוָה בְּתוֹךְ עִץ הַגָּן, תַּמָּן אִתְכַּסִּיאוּ אַנְפּוֹהִי, אִית מָאן דְּאָמַר בְּתוֹךְ עִץ דָּא צַדִּיק, וּבַאֲתַר דָּא וַיַּסְתֵּר מֹשֶׁה פָּנָיו (שמות ג ו), דְּאִדְכַּר מַה דְּאִירַע לֵיהּ בְּקַדְמֵיתָא, אַדְכִּיר חוֹבֵיהּ וְאִתְכַּסֵּי מִבֹּשֶׁת, וּבְגִין דָּא זָכָה וּתְמוּנַת יהו\"ה יַבִּיט (במדבר יב ה), וְדָא י' דְּאִיהוּ חָכְמָה תַּתָּאָה, וְאִיהוּ אִיבָּא דְאִילָנָא, דַהֲוָה בְּרֵישׁ צַדִּיק, ו' גּוּפָא דִבְּרִית, ה\"ה דָּא אֲתַר דְּעָרְלָה וּפְרִיעָה, אַרְבַּע אַתְוָון הֲווֹ עַל צַדִּיק דְּאִיהוּ עִץ פְּרִי, אִיהוּ גְרִים דְּאִסְתַּלְקוּ מִנֵּיהּ, וְאִתְעַקַּר אִיהוּ מִגִּנְתָא, הָכִי אַעִִקַר קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם מִגּוּפֵיהּ, וְתָרִיךְ לֵיהּ מִגִּנְתֵיהּ, כְּמָה דְאַתְּ אָמַר (בראשית ג כד) וַיְגָרֶשׁ אֶת הָאָדָם.</p>\n<p>בְּרֵאשִׁית תַּמָּן בַּ\"ת, תַּמָּן אֵ\"שׁ (נ\"א תמן אשרי), בְּהַהוּא זִמְנָא אִסְתַּלַּק קוּדְשָׁא בְּרִיךְ הוּא מִשְּׁכִינְתֵּיהּ, וְאִשְׁתְּאָרַת בַּת יְחִידָה, הֲדָא הוּא דִכְתִיב (איכה א א) אֵיכָה יָשְׁבָה בָדָד, וְרָזָא דְמִלָּה וַיִּקְרָא יהו\"ה אלהי\"ם אֶל הָאָדָם וַיֹּאמֶר לוֹ אַיֶּכָּה (בראשית ג ט), אַיֵּה כֹּ\"ה, אָמַר לֵיהּ, אַף עַל גַּב דְּגָרְמַת כּוּלֵי הַאי, וְעָבְדַת פִּרוּדָא בְּאַתְוָון דְּאִסְתַּלַּק י' מִן ה' ו' מִן ה', וְאִשְׁתְּאָרַת שְׁכִינְתָּא לְעִילָא יְחִידָאָה, וּשְׁכִינְתָּא לְתַתָּא יְחִידָאָה, בְּגִין דָּא וַיֹּאמֶר לוֹ אַיֶּכָּה, אַיֵּ\"ה כֹּ\"ה, וַיֹּאמֶר אֶת קוֹלְךָ שָׁמַעְתִּי בַּגָּן, בְּגִין דָּא וָאִירָא כִּי עֵירוֹם אָנֹכִי וָאֵחָבֵא, וְעוֹד וָאֵחָבֵא, רָזָא דְמִלָּה, עָרוּם רָאָה רָעָה וְנִסְתָּר (משלי כג ב), מַאי סְתִירָה דְבַר נַשׁ, אֶלָּא תָּא חֲזִי בְּזִמְנָא דְאִית רְשׁוּ לִמְחַבְּלָא לְחַבֵּל,</p>"],[9500011188,"<p>אִתְּמַר בֵּיהּ (שמות כב ה) כִּי תֵצֵא אֵשׁ וּמָצְאָה קוֹצִים וכו', וּבְהַהוּא זִמְנָא וְהָיָה כַצַּדִּיק כָּרָשָׁע (בראשית יח כה), וּבְגִין דָּא אִית לֵיהּ לְבַר נַשׁ בְּהַהוּא זִמְנָא לְאִתְטַמְרָא וּלְאִתְכַּסְיָיא, דְלָא יִשְׁתַּכַּח בֵּינַיְיהוּ, דִבְהַהוּא זִמְנָא יֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט, וּבְגִין דָּא (שם) וָאִירָא כִּי עִירוֹם אָנֹכִי וָאֵחָבֵא, וּבְמַאי נִסְתָּר בַּר נַשׁ מֵאִלֵּין דִּינִים וְקַטְרוּגִין דְּלָא שָׁלְטִין עֲלֵיהּ, בִּתְיוּבְתָּא, הֲדָא הוּא דִכְתִיב (תהלים צא א) יוֹשֵׁב בְּסֵתֶר עִִלְיוֹן, דָּא אִימָּא דְאִיהִי סֵתֶר, עִִלְיוֹן מִנָּהּ דָּא חָכְמָה, דְלָא אִשְׁתְּמוֹדָע אֶלָּא בְּה', בְּצֵל שד\"י יִתְלוֹנָן (שם) דָּא אִימָּא תַּתָּאָה, (נ\"א עלאה) צֵל דְּשד\"י דְּאִיהוּ אוֹת בְּרִית קֹדֶשׁ, דְּאִתְּמַר בֵּיהּ (שם לט ז) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ, וְדָא שְׁכִינְתָּא תַּתָּאָה, דְאִיהִי צַלְמוֹ דְקוּדְשָׁא בְּרִיךְ הוּא, וַעֲלֵיהּ אִתְּמַר (בראשית א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, בְּצַלְמוֹ מַמָּשׁ דָּא שְׁכִינְתָּא, צַלְמוֹ דְקוּדְשָׁא בְּרִיךְ הוּא, בְּמִדָּה דִילֵיהּ בְּשִׁעוּר דִּילֵיהּ דְּלָא אוֹסִיף וְלָא גָרַע, מַאי הָאָדָם דָּא שְׁכִינְתָּא, (נ\"א דא עמודא דאמצעיתא).</p>\n<p>אָמַר רַבִּי אֶלְעָזָר וְהָא בִשְׁכִינְתָּא לָא כְתִיב בָּהּ בְּרִיאָה אֶלָּא אֲצִילוּת, וְעוֹד דַּהֲוָה לֵיהּ לְמֵימַר וַיִּבְרָא יהו\"ה אֶת הָאָדָם, מַאי אלהי\"ם אֶלָּא שְׁכִינְתָּא אִתְקְרֵי אלהי\"ם, וְעַל הַהִיא נִשְׁמָתָא דְאִתְיְהִיבַת בְּבַר נַשׁ אִתְּמַר וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, בְּדִיּוֹקְנָא דִשְׁכִינְתָּא, וְעַל הַהִיא נִשְׁמָתָא אִתְּמַר אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ, דְּהָא בְזִמְנָא דְאִסְתַּלִּיק מִבַּר נַשׁ נִשְׁמָתָא לָא יָכִיל לְאִתְנַעֲנָעָא. אָמַר לֵיהּ, בְּרִיךְ בְּרִי לְעַתִּיק יוֹמִין, וּבְרִי כָּל מָאן דְּפָגִים הַאי דִּיּוֹקְנָא, כְּאִלּוּ מְמַעִט אֶת הַדְּמוּת, וּשְׁכִינְתָּא לָא שַׁרְיָא תַמָּן, וּבְהַהוּא זִמְנָא שָׁלְטִין עֲלֵיהּ כָּל מְקַטְרְגִין מִסִּטְרָא דְהַהוּא פְּגִימוּ, וְרָזָא דְמִלָּה (דברים לא יז) עַל כִּי אֵין אלה\"י בְּקִרְבִּי מְצָאוּנִי הָרָעוֹת הָאֵלֶּה, הָרָעוֹת מְצָאוּנִי בְּגִין דְּאִסְתַּלַּק שְׁכִינְתָּא מִנִּי דְאִיהִי אלה\"י.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, מַאי אלהי\"ם מִי אֵלֶּה, וְעַל הַאי מִי אִתְּמַר (בראשית ג יא) מִי הִגִּיד לְךָ כִּי עִירוֹם אָתָּה וְגוֹמֵר, אֲשֶׁר צִוִּיתִיךָ (שם), הַהִיא דְאִתְּמַר בָּהּ אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו, וְהַהִיא דְאִתְּמַר בָּהּ (תהלים א א) אַשְׁרֵי הָאִישׁ אֲשֶׁר לֹא הָלַךְ בַּעֲצַת רְשָׁעִים, דְּהִיא רְשׁוּת הָרַבִּים אֵשֶׁת זְנוּנִים, מַאי רְשָׁעִים דָּא סמא\"ל וְנָחָשׁ, הַהִיא דְאָמַר עֲלָהּ פַּרְעֹה (שמות ה ב) מִי יהו\"ה אֲשֶׁר אֶשְׁמַע בְּקוֹלוֹ, אֲשֶׁר דְּאִתְּמַר בֵּיהּ (שם ב ב) אֲשֶׁר הוֹצֵאתִיךָ מֵאֶרֶץ מִצְרַיִם, מִי וַדַּאי, דְּאִיהִי תְיוּבְתָּא, אַסְוָותָא לְכָל מַרְעִין וּמַכְתְּשִׁין, הֲדָא הוּא דִכְתִיב (איכה ב י) מִי יִרְפָּא לָךְ, וַעֲלָהּ אִתְּמַר (ישעיה ו י) וָשָׁב וְרָפָא לוֹ, רִפְאוּת תְּהִי לְשָׁרֶךָ (משלי ג ח), זַכָּאָה אִיהוּ מָאן דְּתָב לְגַבֵּי בַּעִִלָהּ דִּידָהּ אִיהוּ רָזָא דִתְיוּבְתָּא, דְיַחֲזִיר וְיֵתוּב הַהוּא דַרְגָּא דְרָחִיק לֵיהּ מֵאַתְרֵיהּ, דְּיַחֲזִיר לָהּ לְאַתְרָהּ וִיקָרֵב לָהּ תַּמָּן, בְּהַהוּא זִמְנָא דִשְׁכִינְתָּא מְרַחֲקָא מִבַּעִִלָהּ, אִתְּמַר בְּבַר נַשׁ (דברים כח כ) וְהָיוּ חַיֶּיךָ תְּלוּאִים לְךָ מִנֶּגֶד, חַיֶּיךָ אִתְקְרִיאַת, הֲדָא הוּא דִכְתִיב (בראשית ב ז) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, זַכָּאָה אִיהוּ מָאן דְּקָרִיב לָהּ לְגַבֵּי בַּעִִלָהּ, מַאי (נ\"א ומיד) קָרוֹב יהו\"ה לְכָל קוֹרְאָיו וכו' (תהלים קמה יח), דְּמָאן דְּקָרָא לֵיהּ בְּשִׁקְרָא רָחוֹק הוּא מִנֵּיהּ.</p>\n<p>אֱמֶת א' בְּרֵישָׁא דְאַלְפָא בֵּיתָא, מ' בְּאֶמְצָעִיתָא, ת' בְּסוֹפֵיהּ, (נ\"א ד' אתוון) עִשּׂוּרָא דִילֵיהּ יו\"ד ה\"א וא\"ו ה\"א אֱמֶת, דְּאִיהוּ עִישׂוּר דְּאַרְבַּע מֵאָה וְאַרְבְּעִין וְחַד, הָא רָזָא דְחַמְשָׁא וְאַרְבְּעִין מ\"ה, בְּזִמְנָא דְיִשְׂרָאֵל מְשַׁקְּרִין בְּתוֹרַת אֱמֶת, בְאוֹמָאָה דְשִׁקְרָא, אִתְּמַר בֵּיהּ (דניאל ח יב) וְתַשְׁלֵךְ אֱמֶת אַרְצָה, מַאי אַרְצָה דָּא שְׁכִינְתָּא, וּבְזִמְנָא דְיִשְׂרָאֵל מְקַיְימִין תּוֹרַת אֱמֶת בְאוֹמָאָה דִקְשׁוֹט, אִתְּמַר בֵּיהּ (תהלים פה יב) אֱמֶת מֵאֶרֶץ תִּצְמָח, וּבְגָלוּתָא אִתְּמַר (ישעיה נט טו)</p>"],[9500011189,"<p>. וַתְּהִי הָאֱמֶת נֶעִִדֶּרֶת, וְשִׁקְרָא שָׁלְטָא בְעָלְמָא, (ובזמנא דאתתקן אמת ואסתלק לאתריה אתמחי שקרא מעלמא, הדא הוא דכתיב (משלי יב יט) שפת אמת תכון לעד, כוננת לא כתיב אלא תכון לעד (אמת), ועד ארגיעה לשון שקר (שם), מאי אמת עמודא דאמצעיתא, שכינתא דיליה תורת אמת, היתה בפיהו (מלאכי ב ו)), וּמָאן שֶׁקֶר דָּא סמא\"ל, בְּזִמְנָא דֶאֱמֶת שָׁלְטָא אִתְעֲבַר שִׁקְרָא מֵעָלְמָא.</p>\n<p>אֱמֶת אִיהוּ בְּסוֹף תֵּיבִין, וְאִינוּן בָּרָ א אֱלֹהִי ם לַעֲשׂוֹ ת, בָּרָ א אֱלֹהִי ם אֶ ת, בֵּיהּ בָּרָא עָלְמָא, וַעֲלֵיהּ אִתְקְרֵי וְקַיְימָא כָל עָלְמָא, וְכָל מָאן דְּאוֹמֵי בְּשִׁקְרָא כְּאִלּוּ וְתַשְׁלֵךְ אֱמֶת אַרְצָה, וְשִׁקְרָא שָׁלְטָא כַּבְיָכוֹל בַּאֲתַר (נ\"א אתרך מאתר) דִּילֵיהּ דְּאִיהוּ יְרוּשָׁלַםִ, וְדָא גְרִים דְּאִתְחָרַב בֵּיתָא, וְאִתְחַזַּר עָלְמָא לְתֹהוּ וָבֹהוּ, דְּהָכִי אוּקְמוּהוּ חָרַב בַּיִת רִאשׁוֹן וְהָאָרֶץ הָיְתָה תֹהוּ, חָרַב בַּיִת שֵׁנִי וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם, דֶּאֱמֶת הוּא סָבִיל עִלָּאִין וְתַתָּאִין, וּבְזִמְנָא דְאִתְעֲבִיד שִׁקְרָא יִתְהָרֵס הַבִּנְיָן, בְּהַהוּא זִמְנָא אִתְּמַר בִּשְׁכִינְתָּא (עמוס ה ב) נָפְלָה לֹא תוֹסִיף קוּם, הֲדָא הוּא דִכְתִיב (ישעיה יד יב) אֵיךְ נָפַלְתָּ מִשָּׁמַיִם הֵילֵל בֶּן שָׁחַר, נָפְלָה עֲטֶרֶת רֹאשֵׁנוּ (איכה ה טז), דְּאִינוּן ה' עִלָּאָה ה' תַּתָּאָה, ו' עַמּוּדָא דְאֶמְצָעִיתָא סָבִיל תַּרְוַיְיהוּ, יְסוֹדָא דְכֹלָּא י', דָּא בְרִית, כָּל מָאן דִּמְשַׁקֵּר וְעָבַר בֵּיהּ, כְּאִלּוּ אַעִִקַר כֹּלָּא וְאַפִּיל לֵיהּ, וְהַאי י' הִיא אֶבֶן הַשְּׁתִיָּה דְמִינָהּ הוּשְׁתַת עָלְמָא, וַעֲלֵיהּ אִתְּמַר (תהלים קיח כב) אֶבֶן מָאֲסוּ הַבּוֹנִים וכו', וְאִיהִי יְסוֹדָא דְכֹלָּא, וַעֲלָהּ אִתְבְּנֵי, וַוי לֵיהּ לְמָאן דְּחָאב בְּאוֹת שַׁבָּת וּבְאוֹת תְּפִלִּין וּבְאוֹת יוֹמִין טָבִין וּבְאוֹת בְּרִית מִילָה, כְּאִלּוּ אַעִִקַר לֵיהּ מֵאַתְרֵיהּ, וְאַהֲדַר עָלְמָא לְתֹהוּ וָבֹהוּ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אַבָּא וְהָא י' לְעִילָא אִיהִי, אַמַּאי אִיהִי לְתַתָּא הָכָא, אָמַר לֵיהּ בְּרִי, דָא רָזָא עִלָּאָה, מֵאַרְבַּע אַתְוָון תַּלְיָין אַרְבַּע שְׁמָהָן, מִן י' יהו\"ה, מִן ה' הוי\"ה (נ\"א הוי\"ה), מִן ו' והי\"ה, מִן ה' הוה\"י (נ\"א והי\"ה הוה\"י), עֲלַיְיהוּ אִתְּמַר וַדַּאי וְרָאִיתָ אֶת אֲחוֹרָי, (ופני לא יראו) (שמות לג כג), וּמִסִּטְרָא דַאֲחוֹרַיִם אִיהִי י' לְתַתָּא, וּמִסִּטְרָא דְפָנִים לְעִילָא, וְדָא אִיהוּ רָזָא דְאִתְהַפַּךְ שְׁמָא מִדִּינָא לְרַחֲמֵי וּמֵרַחֲמֵי לְדִינָא, כַּד אִתְהַפַּךְ לְדִינָא אִיהוּ הוה\"י י' לְתַתָּא, דְּאִתְּמַר בֵּיהּ אֶבֶן מָאֲסוּ הַבּוֹנִים, מָאֲסוּ יִסּוּרִין דִּילָהּ, וְאִלֵּין דַּחֲבִיבִין יִסּוּרִין אִתְהַפַּךְ לוֹן מִדִּינָא לְרַחֲמֵי יהו\"ה, וּבְהַהוּא זִמְנָא אֶבֶן מָאֲסוּ וכו', מַה דַּהֲוַת י' לְתַתָּא אִתְחַזְרַת לְעִילָא, וּמִסִּטְרָא דְוהי\"ה אִיהִי י' בְּאֶמְצַע, בְּהַהוּא זִמְנָא אִשְׁתַּטַּח לְגַבֵּיהּ, וְאָמַר זַכָּאָה חוּלָקֵי דְזָכִינָא לְהַאי, דְּדָא עִיקָרָא וִיסוֹדָא דְכֹלָּא.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, תַּמָּן אִישׁ תַּמָּן אִשָּׁה עִם ה' דֶאלהי\"ם, וַעֲלַיְיהוּ אִתְּמַר (שיר ב ה) סַמְּכוּנִי בָּאֲשִׁישׁוֹת, בְּאִישׁ וְאִשָּׁה, וּמָאן גָּרִים דָּא, בְּגִין דְּאִתְפַּשְׁטוּ מִכָּתְנוֹת אוֹר אָדָם וְחַוָּה, וּבְגִין דָּא סַמְּכוּנִי בָּאֲשִׁישׁוֹת, בְּכָתְנוֹת עוֹר דְּאִינוּן לָקֳבֵל וְעוֹרוֹת אֵילִים מְאָדָּמִים וכו' (שמות כה ה).</p>\n<p>וְכִי אָדָם גָּרִים, וְהָא כְתִיב (בראשית ג ב) וַיֹּאמֶר הָאָדָם הָאִשָּׁה אֲשֶׁר נָתַתָּ עִמָּדִי וְגוֹמֵר, וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאִתְּתָא מֶה עָבְדַת, כְּמָה דְאַתְּ אָמַר (שם יג) וַיֹּאמֶר יהו\"ה אלהי\"ם אֶל הָאִשָּׁה מַה זֹּאת עָשִׂית, כָּל חוֹבָה דְעָבְדַת לִשְׁכִינְתָּא דְאִיהִי זֹאת עָבְדַת, וּבְגִין דָּא מַה זֹּאת עָשִׂית, דְּאִיהִי מַה שְּׁמוֹ, מַה זֹּאת וַדַּאי, מָה יהו\"ה אלהי\"ך שׁוֹאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה (דברים י יב), וְאַל תִּקְרֵי אִם אֶלָּא אֵם (הדא הוא דכתיב (ויקרא יט ג) איש אמו ואביו תיראו דאיהו י\"ה אבא ואימא עלאה), וְאַנְתְּ לָא דְחֵילְתְּ מֵאִימָּא עִלָּאָה, לְזֹאת עָבְדַת כָּל דָּא וַדַּאי, דְאִתְּמָר בָּה (בראשית ט יב) זֹאת אוֹת הַבְּרִית.</p>\n<p>דְּאָדָם</p>"],[9500011190,"<p>וְאִתְּתֵיהּ אִתְבְּרִיאוּ בְּדִיּוֹקְנָא דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וּבְגִין דָּא חוֹבָא דְאָדָם הֲוָה תַלְיָא בְּעַמּוּדָא דְאֶמְצָעִיתָא, וְחוֹבָה דְחַוָּה בִּשְׁכִינְתָּא, וּבְגִין דָּא מַה זֹּאת עָשִׂית, לְזֹאת עָשִׂית וַדַּאי, וְחוֹבָא דָא גָרַם דְּנָחְתַת שְׁכִינְתָּא בְגָלוּתָא, דַהֲווֹ יִשְׂרָאֵל עָבְדִין מַעֲשֵׂה אֲבוֹתֵיהֶם, וּבְגִין דָּא אָמַר (ויקרא כו מד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים וכו', וּבָהּ אָמַר דָּוִד (תהלים כז ג) אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי וְגוֹמֵר, בְּזֹאת אֲנִי בוֹטֵחַ וְגוֹמֵר, דָּא אִתְּמַר בְּמִלְחֶמֶת גּוֹג וּמָגוֹג, וּמָאן גָּרִים לְמֶהֱוִי אִיהוּ נָטִיר בָּהּ, בְּגִין דַּעֲלֵיהּ אִתְּמַר (שם קלב ד) אִם אֶתֵּן שְׁנָת לְעִינָי לְעַפְעַפַּי תְּנוּמָה עַד אֶמְצָא מָקוֹם לַיהו\"ה וְגוֹמֵר.</p>\n<p>וְהַאי אִיהִי חָכְמַת שְׁלֹמֹה, וַעֲלָהּ אִתְּמַר (קהלת ט טז) וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה, וַעֲלָהּ אִתְּמַר (שמואל א ב ל) כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקָלּוּ, כַּד נָחִית שְׁלֹמֹה מִמַּלְכוּתֵיהּ הֲוָה חָכְמָה דִילֵיהּ בְּזוּיָה בְּעִינֵי שַׁטְיָין, וְכַד אִסְתַּלַּק בְּמַלְכוּתֵיהּ אִתְּמַר בֵּיהּ (מלכים א ה י) וַתֵּרֶב חָכְמַת שְׁלֹמֹה, דְאִתְרַבִּיאַת עַד דִּמְטָאת לְהַאי אֲתַר דְּאִתְנְטִילַת מִתַּמָּן, לַאֲתַר דְּחָכְמָה עִלָּאָה, דְאִיהִי חָכְמָה בְּרֵישָׁא, וְאִיהִי חָכְמָה בַסּוֹף, וְאִיהִי תּוֹרָה בְּאֶמְצָעִיתָא, בְּעַמּוּדָא דְאֶמְצָעִיתָא תּוֹרַת אֱמֶת, לְעִילָא תּוֹרַת חָכָם, לְתַתָּא חָכְמַת שְׁלֹמֹה, וּבְגִין דָּא מִסִּטְרָא דִשְׁלֹמֹה אִתְּמַר וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה, דִּנְחִיתַת בֵּיהּ, וּסְלִיקַת בֵּיהּ, כְּמָה דְאִתְּמַר בֵּיהּ וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם. אםל בְּחַיָּיבַיָּא מַה כְּתִיב בְּהוּ, (איכה א יד) נְתָנַנִי יהו\"ה בִּידֵי לֹא אוּכַל קוּם, (עמוס ה') נָפְלָה וְלֹא תוֹסִיף קוּם (עמוס ה ב), וְאַף עַל פִּי דְלֵית לָהּ רְשׁוּ לְמֵיקַם מִגַּרְמָהּ, קוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לָהּ, כְּמָה דְאַתְּ אָמַר (שם ט יא) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנֹּפֶלֶת, וּמָאן גָּרִים דְּנָחְתַת לָהּ מֵאַתְרָהּ דָּא נָחָשׁ, כְּמָה דְאַתְּ אָמַר (בראשית ג יד) וַיֹּאמֶר יהו\"ה אלהי\"ם אֶל הַנָּחָשׁ כִּי עָשִׂיתָ זֹּאת, דְּאִיהִי שְׁכִינְתָּא, דְּגָרְמַת דְּאִשְׁתַּכְּחַת יַבָּשָׁה וְנָפְלַת מֵאַתְרָהּ, אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגוֹמֵר (שם), לַיִיט לֵיהּ דְּלָא יְהֵא לֵיהּ מַלְכִין וְשַׁלִּיטִין עַל מַה דְּסָמִיךְ, דְּאִינוּן רַגְלוֹי וִידוֹי דְּקָצִיץ לוֹן, כְּמָה דְאִיהוּ גְרִים קִצּוּץ וּפִרוּד לְעִילָא, וּבְגִין דָּא עַל גְּחוֹנְךָ תֵלֵךְ וְעָפָר תֹּאכַל כֹּל יְמֵי חַיֶּיךָ (שם), וְדָא אִיהוּ דְאָמַר יִצְחָק לְעִשָׂו (שם כז לט) מִשְׁמַנֵּי הָאָרֶץ יִהְיֶה מוֹשָׁבֶךָ.</p>\n<p>עִִּשֶׂר לְוָטַיָּא לַיִיט לְחִוְיָא, בְּגִין דְּגָרִים דְּאִתְפַּרַשׁ שְׁכִינְתָּא דְאִיהִי עֲשִׂירָאָה מִבַּעִִלָהּ, וְעִִשֶׂר לְאָדָם, וְעִִשֶׂר לְחַוָּה, וְתִשְׁעָה לְאַרְעָא, דְחָבַאת לַצַּדִּיק דְּאִיהוּ תְשִׁיעָאָה, כֻּלְּהוּ חָאבוּ לַעֲשִׂירָאָה, וְאַרְעָא לַצַּדִּיק, וּמִמַּאי (נ\"א ואמאי) חָאבַת לַצַּדִּיק, דְּהָא בַּעֲבוּרֶךָ אָמַר לְאָדָם, וְעוֹד בְּגִין אָדָם לַיִּיט לְאַרְעָא דְּאִתְנְטִיל מִינָהּ, הֲדָא הוּא דִכְתִיב (שם ב ז) וַיִּיצֶר יהו\"ה אלהי\"ם אֶת הָאָדָם עָפָר מִן הָאֲדָמָה, אִם כֵּן מַה חָבַאת לַצַּדִּיק דְּאִיהוּ תְשִׁיעָאָה.</p>\n<p>אֶלָּא בְּגִין דְּאִתְּמַר בָּהּ (שם ט) וַיַּצְמַח יהו\"ה אלהי\"ם מִן הָאֲדָמָה כָּל עִץ נֶחְמָד לְמַרְאֶה וְטוֹב לְמַאֲכָל וְעִץ הַחַיִּים בְּתוֹךְ הַגָּן וְעִץ הַדַּעַת טוֹב וָרָע, וַהֲוָה לֵיהּ רְשׁוּ לְמִמְחָא בִידָא דְאָדָם דְּלָא יֵכוּל מֵאִילָנָא דְמוֹתָא, וְלָא מָחַאת, בְּגִין דָּא אָמַר בַּעֲבוּרֶךָ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר, וְכִי אִית דַּעַת בְּאַרְעָא לְכוּלֵי הַאי, אָמַר לֵיהּ אִין, הֲדָא הוּא דִכְתִיב (משלי ג יט) יהו\"ה בְּחָכְמָה יָסַד אָרֶץ, אָמַר לֵיהּ וְהָא בְּחָכְמָה עִלָּאָה וּבְאַרְעָא דְקוּדְשָׁא בְּרִיךְ הוּא אִתְּמַר הַאי קְרָא, אָמַר לֵיהּ בְּרִי דָא לָקֳבֵל דָּא עָבַד קוּדְשָׁא בְּרִיךְ הוּא, אִית חָכְמָה וְאִית חָכְמָה, אִית אַרְעָא וְאִית אַרְעָא.</p>\n<p>אָמַר לֵיהּ אִם כֵּן מַה חָבַאת אַרְעָא לַצַּדִּיק דְּלָקְתָה תִּשְׁעָה, אָמַר לֵיהּ בְּגִין דְּעִץ הַדַּעַת טוֹב וָרָע אִיהוּ כְּגַוְונָא דִּבְרִית, אוֹת בְּרִית מִלְּגָאו טוֹב עָרְלָה רָע, דָּא מִלְּגָאו וְדָא מִלְּבָר, וּבְגִין דְּחוֹבָא דְעִץ הַדַּעַת גָּרִים פִּרוּדָא בֵּין צַדִּיק וּשְׁכִינְתָּא, בְּגִין דָּא לָקַאת אַרְעָא תִּשְׁעָה, וְאִינוּן דְּחָאבוּ בִּשְׁכִינְתָּא דְאִיהִי עֲשִׂירִית לָקוּ עִִשֶׂר עִִשֶׂר. וְתָא חֲזִי שִׁבְעָה אַרְעִין אִינוּן אֶרֶץ אֲדָמָה אַרְקָא גֵּיא נְשִׁיָּה צִיָּה תֵּבֵל, וְאָדָם חָאב</p>"],[9500011191,"<p>בְּבַת שֶׁבַע, וְאִתְּמַר בֵּיהּ (משלי כד טז) כִּי שֶׁבַע יִפּוֹל צַדִּיק, הִרְהֵר תְּיוּבְתָּא וְאִתְּמַר בֵּיהּ (שם) וָקָם, וַהֲוָה סָלִיק, וְכַד נָחִית תַּמָּן הֲוָה עָבִיד עוֹבָדִין וְתוֹלָדִין בְּכָל אַרְעָא וְאַרְעָא, מִנְּהוֹן הֲווֹ צָמְחִין וּמִנְהוֹן לָא הֲווֹ צָמְחִין, וְאִית תַּמָּן בִּרְיָין מִנְּהוֹן בִּתְרֵין רֵישִׁין וְאִית מִנְּהוֹן בִּתְלַת עַד שֶׁבַע, וְאִית תַּמָּן אֲתַר דְּנַהֲרָא שִׁמְשָׁא וְסִיהֲרָא וְכֹכְבַיָּא וּמַזָּלֵי, וְאִית אֲתַר דְּלֵית בֵּיהּ נְהוֹרָא כְּלָל אֶלָּא חֲשׁוֹכָא וְקִבְלָא.</p>\n<p>הָכִי אִינוּן אִלֵּין דְּנָחֲתִין לְשִׁבְעָה מִינֵי עֲנִיּוּתָא, אִית מִנְּהוֹן דְּלֵית לוֹן נְהוֹרָא כְּלָל, דְּכָל יוֹמֵיהוֹן אִינוּן בַּעֲנִיּוּתָא, וְאִית מִנְּהוֹן דְּאִית לְהוֹן נְהוֹרָא כָּל יוֹמֵיהוֹן וְאִינוּן בְּעוּתְרָא, וְאִית מִנְּהוֹן דִּלְזִמְנִין אִית לוֹן נְהוֹרָא וּלְזִמְנִין חֲשׁוֹכָא, אִלֵּין אִינוּן דְּאִתְיַילִּידוּ בְּאֶמְצָעִיתָא דְסִיהֲרָא בֵינוּנִיִּים, לְזִמְנִין אִית לוֹן עוּתְרָא וְסָלְקִין, וּלְזִמְנִין עֲנִיּוּתָא וְנָחֲתִין, וְאִית אָחֳרָנִין דְּעָבְדִין תּוֹלָדִין וּמַצְלִיחִין, וְאִית מִנְּהוֹן דְּלָא מַצְלִיחִין, וְאִית מִנְּהוֹן דְּמַצְלִיחִין (נ\"א צמחין) עַד פַּלְגוּ יוֹמֵיהוֹן וּמַיְיתִין בְּקַצְרוּת יוֹמִין, אִלֵּין דְּאִתְיְלִידוּ בְּמִלּוּיָיא דְסִיהֲרָא אִינוּן צָמְחִין וְחַיִּין וּמַשְׁלִימִין כָּל יוֹמֵיהוֹן, וְאִינוּן דְּאִתְיְלִידוּ בְּחֶסְרוֹנָא דְסִיהֲרָא לָא צָמְחִין וּמַיְיתִין מִיָּד, וְאִינוּן דְּאִתְיְלִידוּ בְּאֶמְצָעִיתָא דְסִיהֲרָא מִתְקַצְּרִין בְּפַלְגוּת יוֹמֵיהוֹן.</p>\n<p>וְאִית אַרְעִין דְּאִתְּמַר בְּהוֹן (בראשית לז כד) וְהַבּוֹר רֵק אֵין בּוֹ מָיִם, מַיִם אֵין בּוֹ אֲבָל נְחָשִׁים וְעַקְרַבִּים אִית בֵּיהּ, אוּף הָכִי אִית בִּרְיָין דְּאִינוּן עַמֵּי הָאָרֶץ, דְּבָתֵּיהוֹן מַלְיָין מַלְאֲכֵי חַבָּלָה, דְאִינוּן נְחָשִׁים וְעַקְרַבִּים וְנָשְׁכִין לוֹן בְּכַמָּה נִשּׁוּכִין דְּיִסּוּרִין, דְּאִינוּן גָּרְמוּ קֳדָם דְּיֵיתוּן לְעָלְמָא, (בגין דייתו) בְּגִלְגוּלָא בְּאִלֵּין גּוּפִים וּבְאִלֵּין בָּתִּים, וְכַד נָשְׁכִין לוֹן אִינוּן נְחָשִׁים וְעַקְרַבִּים בְּכַמָּה יִסּוּרִין אִינוּן צָוְוחִין וַוי וַוי, וְאִית לוֹן קְטָטָה לְכֻלְּהוּ בְּבֵיתָא, וְצָוְוחִין בְּאִלֵּין מָארֵי דְגֵיהִנָּם דְּנִדּוֹנִין בּוֹ, וְאִית אָחֳרָנִין דְּכָל יוֹמֵיהוֹן בְּחֶדְוָה וּבְשַׁלְוָה בְּלָא עֲצִיבוּ כְּלָל, מִכָּל מַה דְּאִתְרַבֵּי בְשִׁבְעָה אַרְעִין, וְאִתְדַנּוּ בְשִׁבְעָה מְדוֹרֵי גֵיהִנָּם, וְאִית בִּבְנֵי נָשָׁא כְּגַוְונָא דָא, וְחַכִּימֵי דְרָזִין אִלֵּין לוֹן אִתְמַסַּר לְמִנְדַּע.</p>\n<p>בְּרֵאשִׁית בָּ'רָ'א אֱ'לֹהִי'ם (רישי תיבין וסופי תיבין א\"ב וא\"ם תמן דאינון י\"ה), תַּמָּן אֵם, וְרָזָא דְמִלָּה (שם ג ב) וַיִּקְרָא הָאָדָם שֵׁם אִשְׁתּוֹ חַוָּה כִּי הִיא הָיְתָה אֵם כָּל חָי, כְּגַוְונָא דְהַהִיא דְאִתְּמַר בָּהּ (משלי ב ג) כִּי אִם לַבִּינָה תִקְרָא, הַאי אֵם כָּל חָי לַאו אִיהִי כְאִתְּתָא קַדְמָאָה, דְאִתְּמַר בָּהּ (בראשית ג יב) הָאִשָּׁה אֲשֶׁר נָתַתָּ עִמָּדִי, דְגָרְמַת מִיתָה לְכָל עָלְמָא, דְּהָא אֵם כָּל חָי כְּתִיב בָּהּ, דְּאִתְּמַר בָּהּ (קהלת ט ט) רְאֵה חַיִּים עִם אִשָּׁה אֲשֶׁר אָהָבְתָּ.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, וְכִי תְרֵין נְשִׁין הֲווֹ לֵיהּ, אָמַר לֵיהּ אִין, חַד יֵצֶר הַטּוֹב וְחַד יֵצֶר הָרָע, חֲדָא מִסִּטְרָא דְעִִצֶם תַּקִּיפָא דִינָא קַשְׁיָא, וַחֲדָא מִסִּטְרָא דְבִשְׂרָא, מִתַּמָּן אִינוּן רַכִּיכֵי לִבָּא, וְאִינוּן דְּגַרְמָא אִינוּן קְשֵׁי קְדָל, וְעַל אִתְּתָא דְאִתְנְטִילַת מִגַּרְמָא אָמַר בֶּן סִירָא, גַרְמָא דְנָפִיל בְּחוּלָקָךְ טַב אוֹ בִישׁ גַּרְרֵיהּ, וְעַל אִתְּתָא דְגַרְמָא אָמַר אָדָם הָאִשָּׁה אֲשֶׁר נָתַתָּ עִמָּדִי, לָא קְרָא לָהּ אִתְּתֵיהּ, כְּגַוְונָא דְחַוָּה דְאִתְּמַר בָּהּ וַיִּקְרָא הָאָדָם שֵׁם אִשְׁתּוֹ חַוָּה, דְּאָחֳרָא שִׁפְחָה הֲוַת דְּמִסִּטְרָא דְעִץ הַדַּעַת טוֹב וָרָע, חֲדָא רַע וַחֲדָא טוֹב, וּמִסִּטְרָא דְעִץ הַחַיִּים תַּרְוַיְיהוּ חַיִּים.</p>\n<p>וּבְסִתְרֵי תּוֹרָה חַוָּה ח' ו\"ה ח' חָכְמָה כֹּ\"חַ מָ\"ה, כְּלָלָא דִשְׁמָא קַדִּישָׁא, ח' אִיהִי כְגַוְונָא דְאִימָּא עִלָּאָה דְאִיהִי תְמִינָאָה לְעִִשֶׂר סְפִירָן מִתַּתָּא לְעִילָא, וְחָכְמָה בָּהּ אִשְׁתְּמוֹדָע, וַעֲלָהּ אִתְּמַר (משלי ג ג) עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, וּמִסִּטְרָא דִילָהּ וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים (בראשית ב ז), וַעֲלָהּ אִתְּמַר (שם כג) לְזֹאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לֻקֳחָה זֹּאת, וְלָא אָחֳרָא דְאִתְנְטִילַת מִגַּרְמָא, דְגַרִימַת לֵיהּ מִיתָה, דְהָא שִׁפְחָה גָרְמַת וַיֵּדְעוּ כִּי עִירֻמִּם הֵם (שם ג ז), וּבְגִין דָּא (שם כא) וַיַּעַשׂ יהו\"ה אלהי\"ם לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם.</p>"],[9500011192,"<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר אַמַּאי אָמַר, בְּגִינָהּ כִּי מֵאִישׁ לֻקֳחָה זֹּאת (בראשית ב כג), כִּי מֵאָדָם הֲוָה לֵיהּ לְמֵימַר, אַמַּאי מֵאִישׁ, אֶלָּא מֵאִישׁ תַּמָּן אֵ\"ם וְתַמָּן יֵ\"שׁ, תַּמָּן יֵ\"שׁ הֲדָא הוּא דִכְתִיב (משלי ח כא) לְהַנְחִיל אֹהֲבַי יֵשׁ, תַּמָּן אֵם כִּי אִם לַבִּינָה תִקְרָא (שם ב ג), וְאִינוּן אַבָּא וְאִימָּא חָכְמָה וּבִינָה, דְמִתַּמָּן אִתְנְטִילַת, וּבְגִין דָּא כִּי מֵאִישׁ לֻקֳחָה זֹּאת.</p>\n<p>וְאִית לֵיהּ אָחֳרָא דְאִתְקְרִיאַת בַּת זוּגֵיהּ, הֲדָא הוּא דִכְתִיב (בראשית ה ב) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם וַיִּקְרָא אֶת שְׁמָם אָדָם. תָּא חֲזִי אָדָם הָרִאשׁוֹן בְּדִיּוֹקְנָא דְיהו\"ה אִתְבְּרִי, וּבְדִיּוֹקְנָא דְעִִשֶׂר סְפִירָאן דְּאִינוּן יו\"ד ה\"א וא\"ו ה\"א, מִסִּטְרָא דְיהו\"ה, מִסִּטְרָא דְי' אִתְקְרֵי אִישׁ, וּמִסִּטְרָא דְה' עִלָּאָה אִתְּתֵיהּ אִתְקְרִיאַת אִשָּׁה אֵם כָּל חָי, וּמִסִּטְרָא דְו\"ה חַוָּה אִתְּתֵיהּ, וּמִסִּטְרָא דְיו\"ד ה\"א וא\"ו ה\"א חַוָּה אִתְקְרֵי אָדָם, וּבְכָל מַה דַּהֲוָה בְדִיּוֹקְנֵיהּ לָקָה.</p>\n<p>בְּרֵאשִׁית בָּרָא שִׁית, דָּא אָדָם דְּכָלִיל שִׁית, וְאִינוּן תְּרֵין שְׁפָחוֹת מִסִּטְרָא דְאִילָנָא דְטוֹב וָרָע עִִצֶם וּבָשָׂר, אִישׁ וְאִשָּׁה דְּאִתְּמַר בָּהּ (בראשית ב כג) כִּי מֵאִישׁ לֻקֳחָה זֹּאת, הָא אַרְבַּע, אָדָם זָכָר וּנְקֵבָה, הֲדָא הוּא דִכְתִיב זָכָר וּנְקֵבָה בְּרָאָם וְגוֹמֵר, הָא שִׁית, וּבְגִין דָּא (שם ג כב) וַיֹּאמֶר יהו\"ה אלהי\"ם הֵן הָאָדָם הָיָה כְּאַחַד מִמֶּנּוּ לָדַעַת טוֹב וָרָע וְגוֹמֵר, וְאוּקְמוּהוּ קַדְמָאִין כְּאַחַד מִמַּלְאֲכֵי הַשָּׁרֵת.</p>\n<p>אַדְהָכִי הָא אֵלִיָּהוּ אִזְדַּמַּן לְגַבֵּיהּ וְאָמַר רַבִּי כְּאַחַד מֵהֶם הֲוָה לֵיהּ לְמֵימַר אִם עַל מַלְאֲכֵי הַשָּׁרֵת הֲוָה אָמַר, מַאי כְּאַחַד מִמֶּנּוּ, וְעוֹד הֵן אָדָם הֲוָה לֵיהּ לְמֵימַר, מַאי הָאָדָם בְּתוֹסֶפֶת ה', אֶלָּא ה' דְּהָאָדָם הָיָה כְּאַחַד מִמֶּנּוּ, יְהֵא (נ\"א הוא) לָא כְתִיב אֶלָּא הָיָה, חַד מֵאַרְבַּע אַתְוָון דְּאִינוּן יהו\"ה כְּחַד מִן אַרְבַּע אַתְוָון דְּאִיהוּ ו'.</p>\n<p>וְעַתָּה פֶּן יִשְׁלַח יָדוֹ (שם) דָא י', אִם זָכָה וְלָקַח גַּם מֵעִץ הַחַיִּים (שם) דָּא ו' (נ\"א ה'), וְאָכַל וָחַי לְעוֹלָם (שם) דָּא ו', חַי וַדַּאי, כַּד ה' הֲוַת יְחִידָא מִנֵּיהּ עָאלַת בֵּין טוֹב לָרָע, הֲדָא הוּא דִכְתִיב (שם ב ז) וַיִּיצֶר יהו\"ה אלהי\"ם אֶת הָאָדָם תְּרֵין יְצִירוֹת טוֹב וָרָע, לְמִנְדַּע (ואתמר בהון (שם) ויפח באפיו נשמת חיים ודא ה' לדעת טוב ורע למנדע) מַה דַּהֲווֹ גָרְמִין לְמֶעֱבַד, וּבְגִין דָּא עָאלַת בֵּינַיְיהוּ.</p>\n<p>בָּתַר דְּחָאב אָדָם דִּיצִירָה, אִתְפַּרְשַׁת ה' עִלָּאָה וְאִסְתַּלְקַת מִנֵּיהּ, וּבְגִין דְּלָא אִתְחַזְרַת לְגַבֵּיהּ, אָמַר אִם זָכָה וְלָקַח גַּם מֵעִץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם, וְהַאי עִץ הַחַיִּים הֲוָה נָטוּעַ בְּעִץ הַגָּן, וּבְגִין דְּלָא זָכָה לְמֵיכַל מִנֵּיהּ, מַה כְּתִיב בֵּיהּ וַיְשַׁלְּחֵהוּ יהו\"ה אלהי\"ם מִגַּן עִדֶן (שם ג כג) לַעֲבוֹד אֶת הָאֲדָמָה אֲשֶׁר לֻקַּח מִשָּׁם, הַהוּא דְאִתְּמַר בֵּיהּ (שם ב ז) וַיִּיצֶר יהו\"ה אלהי\"ם אֶת הָאָדָם עָפָר מִן הָאֲדָמָה דְּלָא הֲוָה כְדַאי לְמֶהֱוֵי בְגִנְּתָא דְאוֹרַיְיתָא, כֵּיוָן דְּלָא נָטִיר בָּהּ עִץ הַדַּעַת טוֹב וָרָע בְּאִסּוּר וְהֶתֵּר, וְעָבַר עַל מֵימְרָא דְמָארֵיהּ, דְּאִם הֲוָה נָטִיר דְּלָא עָבַר עַל מֵימְרָא דְמָארֵיהּ, וְלָקַח גַּם מֵעִץ הַחַיִּים דְּאִתְּמַר בָּהּ (משלי יג יד) תּוֹרַת חָכָם מְקוֹר חַיִּים לָסוּר מִמּוֹקְשֵׁי מָוְת, עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ (שם ג יח), וְדָא אִיהוּ וְלָקַח גַּם מֵעִץ הַחַיִּים וְאָכַל וָחַי לְעוֹלָם, גַּם לְרַבּוֹת נוּקְבָא, אִיבָּא דְאִילָנָא פְּרִי צַדִּיק.</p>\n<p>וְעוֹד הֵן הָאָדָם הָיָה כְּאַחַד מִמֶּנּוּ, אָמְרוּ מַלְאָכִין קַדִּישִׁין בְּגִין לְמֶהֱוִי אִיהוּ כְּאַחַד מִינָנָא כְּמָא דְאָמַר חִוְיָא (בראשית ג ה) וִהְיִיתֶם כֵּאלֹהִי\"ם יוֹדְעִי טוֹב וָרָע, וְדָא אִיהוּ לָדַעַת טוֹב וָרָע, דָּא גְרִים לֵיהּ מוֹתָא, דְּאִם זָכָה לְמֵיכַל מֵאִילָנָא דְחַיֵּי דְאִיהוּ עִץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, מַה כְּתִיב בָּהּ וְלָקַח גַּם מֵעִץ הַחַיִּים וְגוֹמֵר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן וַוי לוֹן לְאִינוּן דְּמַנִּיחִין לְאִשְׁתַּדְלָא בְּאוֹרַיְיתָא דְאִתְּמַר בָּהּ וְלָקַח גַּם מֵעִץ הַחַיִּים, וּבְפִקּוּדִין דִּילָהּ דְּאִינוּן אִיבָּא דְאִילָנָא דְאִתְּמַר בֵּיהּ וְאָכַל וָחַי לְעוֹלָם, וְאָזְלִין בָּתַר אִלֵּין דִּמְפַתֵּי לוֹן מִסִּטְרָא דְנָחָשׁ הַקַּדְמוֹנִי, דְאָמְרֵי לוֹן הִשְׁתַּדְלוּן בְּמַלְאָכַיָּא דִמְמַנָּן עַל כֹּכְבַיָּא וְשִׁמְשָׁא וְסִיהֲרָא, וְעַל אִלֵּין דִּמְמַנָּן עַל רוּחִין וְשֵׁדִין, לְמֶהֱוִי כֵאלֹהִי\"ם יוֹדְעִי טוֹב וָרָע, וַעֲלַיְיהוּ</p>"],[9500011193,"<p>אִתְּמַר, (עי, מ\"ב כג, וירמיה מד), כֹּה אָמַר יהו\"ה לַמְזַבְּחִים וְלַמְקַטְּרִים לַכֹּכָבִים וְלַמַּזָּלוֹת וְלַשֶּׁמֶשׁ וְלַיָּרֵחַ וּלְכָל צְבָא הַשָּׁמַיִם אֲשֶׁר לֹא צִוִּיתִי, וְדָא אִיהוּ דְמַנִּי קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ וְגוֹמֵר, וּבִלְעָם חַיָּיבָא בְהַאי הֲוָה מִשְׁתַּדֵּל, וְדוֹר אֱנוֹשׁ וְדוֹר הַמַּבּוּל וְדוֹר הַפְלָגָה, וְקוּדְשָׁא בְּרִיךְ הוּא אַעִִקַר לוֹן מֵעָלְמָא דֵין וּמֵעָלְמָא דְאָתֵי, וְדָא אִיהוּ (בראשית ב יז) כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת, מוֹת בְּעָלְמָא דֵין וְתָמוּת בְּעָלְמָא דְאָתֵי, וְחוֹבָא דָא גָרִים חָרְבָּן בֵּי מַקְדְּשָׁא וְגָלוּת יִשְׂרָאֵל בֵּין אוּמִין דְּעָלְמָא וְאִתְקְטִילוּ מִנַּיְיהוּ.</p>\n<p>דְּכָל חַד הֲוָה מְזַבַּח וּמְקַטֵּר, וַהֲווֹ נָחְתִין חֲיָילִין דִּלְעִילָא, וְכַד הֲוָה נָבִיא מְיַסֵּר לוֹן, מַה כְּתִיב בְּהוֹן (עי, ירמיה מד ה) וְלֹא שָׁמְעוּ לְקוֹל נָבִיא וְחוֹזֶה, וּבַמֶּה הֲוָה מְיַסֵּר לוֹן נָבִיא, הֲוָה אוֹמֵר לְהוֹן דִּיְהוֹן חָזְרִין בִּתְיוּבְתָּא, וְאִי לַאו וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ (דברים יא יז), וְאִינוּן הֲווֹ מְזַלְזְלִין בֵּיהּ, וַהֲווֹ אָמְרִין אֲנַן אוֹמִינָן לְאִלֵּין דִּמְמַנָּן עַל מִטְרָא, וְכָפִינָן לְהוֹן לְנַחְתָא מִטְרָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַחֲלִיף לְהוֹן לִמְמַנָּן בִּשְׁלִיחוּתַיְיהוּ בְּגִינַיְיהוּ, וְקָטִיל לוֹן וְחָרִיב בֵּי מַקְדְּשָׁא בְגִינַיְיהוּ, וְגָלוּ יִשְׂרָאֵל בֵּין אוּמִין דְּעָלְמָא, וְדָא אִיהוּ חוֹבָא דְאָדָם דְּגָרַם לֵיהּ חִוְיָא מִיתָה לֵיהּ וּלְאִתְּתֵיהּ, דְּפַתֵּי לוֹן בְּהַהוּא אִילָנָא, הֲדָא הוּא דִכְתִיב (בראשית ג ה) כִּי יוֹדֵעַ אלהי\"ם וכו', וּבְגִין דָּא מַנִּי קוּדְשָׁא בְּרִיךְ הוּא לְבַר נַשׁ בַּמֶּה שֶׁהוֹרְשֵׁתָ הִתְבּוֹנָן אֵין לָךְ עִסֶק בַּנִּסְתָּרוֹת.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר בַּמֶּה הֲווֹ נָחֲתִין אִלֵּין חֲיָילִין, אָמַר לֵיהּ בְּרִי מָה אַתְּ חָשִׁיב דַּהֲווֹ נָחֲתִין, וַדַּאי הָא רָזָא דְאִילָנָא דְעִץ הַדַּעַת טוֹב וָרָע, דְּלָא עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְגַלְיָיא לֵיהּ מְפוּרְסָם לְעָלְמָא אֶלָּא בֵּינֵי חַבְרַיָּא, עַד דְּיֵיתֵי דָרָא דְמַלְכָּא מְשִׁיחָא, אָמַר לֵיהּ כֵּיוָן דְּאִיהוּ אִתְגַּלְיָא בֵּינֵי חַבְרַיָּא מַאי נִיהוּ, אָמַר לֵיהּ בְּנִי, מִמַּרְאֵה מָתְנָיו וּלְמָעִִלָה הֲוָה טוֹב, מִמַּרְאֵה מָתְנָיו וּלְמַטָּה הֲוָה רָע, נְבוּכַדְנֶצַּר הֲוָה יָדַע בֵּיהּ, וְהָכִי עָבִיד צַלְמָא דִילֵיהּ, וּבֵיהּ אִשְׁתְּמוֹדָע אִילָנָא דְטוֹב וָרָע, הֲדָא הוּא דִכְתִיב (דניאל ב לב) רֵישֵׁיהּ דִּי דְהַב טָב, חֲדוֹהִי וּדְרָעוֹהִי דִי כְסָף, עַד הָכָא הֲוָה מִסִּטְרָא דְטוֹב, וּבְגִין דָּא אָמַר דִּי דְהַב טָב, מִמַּרְאֵה מָתְנָיו וּלְמַטָּה רַע, הֲדָא הוּא דִכְתִיב (שם) מֵעוֹהִי וְיַרְכָתֵיהּ דִּי נְחַשׁ מִסִּטְרָא דְנָחָשׁ הַקַּדְמוֹנִי.</p>\n<p>וּמֵהַאי אִילָנָא נָחֲתִין נִשְׁמָתִין דְּעִרֶב רַב דְּאִינוּן דְּעִרְבוּבְיָא דְטוֹב וָרָע, וְכַמָּה נִימִין תַּלְיָין מֵהַאי אִילָנָא דְאִינוּן צְבָא הַשָּׁמַיִם, דִּי מְמַנָּן עַל כֹּכְבַיָּא וּמַזָּלֵי, וְכֻלְּהוּ מְעוּרָבִין טוֹב וָרָע, וַהֲווֹ עַנְפִין תַּלְיָין מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא, אִלֵּין מְמִיתִין וְאִלֵּין מְחַיִּין, אִלֵּין שֵׁדִים מִסִּטְרָא דִשְׂמָאלָא, וְאִלֵּין מַלְאָכִים מִסִּטְרָא דִימִינָא, וַהֲווֹ יָדְעִין כָּל גַּוָּונִין דְּעַנְפִין דְּאִילָנָא דְאִינוּן מַזָּלוֹת וְכֹכָבִים, וַהֲווֹ לָקְטִין עִשְׂבִּין כְּגַוְונָא דְאִלֵּין גַּוָּונִין, וַהֲווֹ עָבְדִין דִּיּוֹקְנִין כְּפוּם הַהוּא מַזָּל דַּהֲווֹ בָּעָאן לְנַחְתָא לֵיהּ, כְּגוֹן טָלֶה אוֹ שׁוֹר אוֹ בְּתוּלָה אוֹ תְאוֹמִים דְּאִיהוּ צוּרַת אָדָם דּוּ פַּרְצוּפִין, דְּאִיהִי דִיּוֹקְנָא דְנוּקְבָא, אוֹ סַרְטָן אוֹ אַרְיֵה אוֹ מֹאזְנַיִם אוֹ עַקְרָב אוֹ קֶשֶׁת אוֹ גְדִי אוֹ דְלִי אוֹ דָגִים, וַהֲווֹ מְקַטְּרִין לוֹן בְּאִלֵּין עִשְׂבִּין בְּכָל גַּוָּון, לְכָל חַד כְּפוּם גַּוָּון דִּילֵיהּ לְעִילָא, וְהָכִי הֲווֹ עָבְדִין דִּיּוֹקְנִין דְּצוּרַת חַמָּה וּלְבָנָה וְשִׁבְעָה כֹּכְבֵי לֶכֶת, וַהֲווֹ מְקַטְּרִין לְכָל צוּרָה דַהֲווֹ בָּעָאן לְנַחְתָא לְעָלְמָא, וּבְגִין דָּא אִתְּמַר עֲלַיְיהוּ כֹּה אָמַר יהו\"ה לַמְקַטְּרִים וְלַמְזַבְּחִים לַכֹּכָבִים וְלַמַּזָּלוֹת וְלַשֶּׁמֶשׁ אוֹ לַיָּרֵחַ אוֹ לְכָל צְבָא הַשָּׁמַיִם אֲשֶׁר לֹא צִוִּיתִי.</p>\n<p>אָמַר לֵיהּ מַאי לַמְזַבְּחִים, אָמַר לֵיהּ לְכָל דִּיּוֹקְנָא הֲווֹ עָבְדִין, דְּנָטְלִין בְּעִירָן אוֹ עוֹפִין כְּפוּם הַהוּא מַזָּל, וַהֲווֹ דָבְחִין עֲלַיְיהוּ, וְדָא אִיהוּ לַמְזַבְּחִים, וַהֲווֹ נָחֲתִין לוֹן וּמְמַלְּלִין עִמְּהוֹן וַהֲווֹ עָבְדֵי רְעוּתֵהוֹן, וְהַווּ סָגְדִין לוֹן וְהֵמָנִין בְּהוֹן, אָמַר לֵיהּ בְּמַאי הֲווֹ נָחֲתִין לוֹן, אָמַר לֵיהּ בְּרִי הֲווֹ יָדְעִין כָּל שְׁמָהָן דִּשְׁמָא מְפָרַשׁ, וַהֲווֹ מַשְׁבִּיעִין לוֹן, וּלְבָתַר עָאלִין שְׁמָא מְפָרַשׁ</p>"],[9500011194,"<p>בְּפוּמֵיהוֹן דְאִלֵין דִּיּוֹקְנִין וַהֲווֹ מְמַלְלָן, וְדָא אִיהוּ רָזָא דִקְרָא (ירמיה נא מד) וְהוֹצֵאתִי אֶת בִּלְעוֹ מִפִּיו, נָפַל שְׁמָא מְפָרַשׁ וּמִיָּד נָפְלַת צַלְמָא עַל אַנְפּוֹהִי, אָמַר לֵיהּ רַבִּי אֶלְעָזָר וְכִי אֵיךְ הֲוָה שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא מַלִּיל בְּהוֹן, אָמַר לֵיהּ בְּרִי עַל הַאי אִתְּמַר (שמות כ ז) לֹא תִשָּׂא אֶת שֵׁם יהו\"ה אלהי\"ך לַשָּׁוְא כִּי לֹא יְנַקֶּה וכו', אָמַר לֵיהּ וְכִי יָכִיל בַּר נַשׁ לְאוֹלִיף שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא לְמַגָּנָא, אָמַר לֵיהּ אִין.</p>\n<p>וּכְגַוְונָא דָא מָאן דְּנָפִיק מֵרְשׁוּת הַיָּחִיד וְאַעִיל בִּרְשׁוּת הָרַבִּים, אוֹ דְאַפִּיק זֶרַע מִנֵּיהּ מֵאוֹת בְּרִית קֹדֶשׁ וְאַעִיל בִּרְשׁוּת נוּכְרָאָה, כְּאִלּוּ הַאי נָטַע אִילָנָא דְטוֹב וָרָע, וּבְגִין הַאי בַּר דְּנָטַע בְּזוֹנָה אוֹ שִׁפְחָה אוֹ גוֹיָה אוֹ נִדָּה, אִתְּמַר (שם ד) לֹא תַעֲשֶׂה לְּךָ פֶסֶל, וְעַל בְּרַתָּא דְאִתְעֲבִידַת בְּגַוָּונָא דָא אִתְקְרִיאַת מַסֵּכָה, וַעֲלַיְיהוּ אִתְּמַר (דברים כז טו) אָרוּר הָאִישׁ אֲשֶׁר יַעֲשֶׂה פֶסֶל וּמַסֵּכָה וְגוֹמֵר, וְשָׂם בַּסָּתֶר, מַאי בַּסָּתֶר בְּסִתְרוֹ דְעָלְמָא, וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא (שמות כ כג) לֹא תַעֲשׂוּן (אתי) אֱלֹהֵי כֶסֶף וִאלֹהֵי זָהָב, וְהָכִי אוּקְמוּהוּ חַבְרַיָּא לֹא תַעֲשׂוּן אִתִּי כִדְמוּת שַׁמָּשַׁי שֶׁמְּשַׁמְּשִׁין אוֹתִי (נ\"א לפני) בַּמָּרוֹם, לְצַיְירָא בַסֵּתֶר דִּילִי שׁוּם צִיּוּר אוֹ דִמְיוֹן, דְּכָל מָאן דְּצִיֵּיר לְעִיל לְקוּדְשָׁא בְּרִיךְ הוּא, בַּסָּתֶר (דאיהי שכינתיה, כלילא מעשר ספיראן), שׁוּם צִיּוּר וְצֶלֶם וּדְמוּת כְּגַוְונָא דִמְצַיְירִין בְּשַׁמָּשִׁין דִּילֵיהּ, נִשְׁמָתֵיהּ אִתְלַבְּשַׁת בְּהַהוּא צַלְמָא, כַּד נָפְקַת מֵהַאי עָלְמָא, קָלָא נָפְקַת לְגַבָּהּ לְצַלְמָא תּוֹקְדוּן בְּנוּרָא, וּבְגִין דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא (ישעיה מ כה) וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוְה יֹאמַר קָדוֹשׁ, וְאֶל מִי תְּדַמְּיוּן אֵ\"ל וּמַה דְּמוּת תַּעַרְכוּ לוֹ (שם יח).</p>\n<p>וּבְרִי וַדַּאי כָּל מָאן דְּנָפִיק מֵרְשׁוּת הָרַבִּים וְאַעִיל בִּרְשׁוּת הַיָּחִיד אוֹ מֵרְשׁוּת הַיָּחִיד וְאַעִיל בִּרְשׁוּת הָרַבִּים, כְּאִלּוּ עָרַב שְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא בַּעֲבוֹדָה זָרָה, וְעָבִיד אִילָנָא דְטוֹב וָרָע, וְדָא הוּא רָזָא דַהֲוָה נָפִיק בְּלָעוֹ מִפִּיו, דְּבֵיהּ הֲוָה אָמַר צַלְמָא דִנְבוּכַדְנֶצַּר אָנֹכִי יהו\"ה אלהי\"ך, וּבְגִין דָּא לֹא תִשָּׂא אֶת שֵׁם יהו\"ה אלהי\"ך לַשָּׁוְא, וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַעִִקָרָא הַאי אִילָנָא מֵעָלְמָא וּלְאוֹקָדָא לֵיהּ בְּגֵיהִנָּם, הֲדָא הוּא דִכְתִיב (שם א לא) וְהָיָה הֶחָסֹן לִנְעֹרֶת וְגוֹמֵר.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, אִם כֵּן אֲסִיר לְעַמָּא לְאִשְׁתַּמְּשָׁא בְּשׁוּם מַלְאָךְ וְלָא בִשְׁמָא בְעָלְמָא בָתַר דְּאִית עִרְבוּבְיָא, אָמַר לֵיהּ בְּרִי לַאו הָכִי, דְהָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם (בראשית ב טז) מִכֹּל עִץ הַגָּן אָכוֹל תֹּאכֵל, מֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל, אָמַר רַבִּי אֶלְעָזָר הַאי הֲוָה קֳדָם דְּחָאב, בָּתַר דְּחָב וְנָחִית מֵאַתְרֵיהּ וְאִתְעָרַב בְּאִילָנָא דְטוֹב וָרָע, אָמַר לֵיהּ וַדַּאי הָכִי הוּא, וּבְזִמְנָא דְיִשְׂרָאֵל אִינוּן בְּגָלוּתָא, כְּאִלּוּ הֲווֹ מְעוּרָבִין בְּאִילָנָא דְטוֹב וָרָע, וּבְגִין דָּא אוּקְמוּהוּ קַדְמָאִין, יִשְׂרָאֵל בְּגָלוּתָא עוֹבְדִין עֲבוֹדָה זָרָה בְּטַהֲרָה הֵם.</p>\n<p>אֲבָל אִלֵּין דְּיָדְעִין אִילָנָא דְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ עִץ הַחַיִּים, נָטוּעַ בְּגַן דִּילֵיהּ דְּאִיהִי שְׁכִינְתָּא דִילֵיהּ, דְּאִתְּמַר בָּהּ (תהלים ה ה) לֹא יְגוּרְךָ רָע, יָכְלִין לְנַחְתָא חֵילָא מִתַּמָּן לְגַבֵּי שְׁכִינְתֵּיהּ בְּלָא עִרְבוּבְיָא כְלָל, בְּכָל פִּקּוּדָא וּפִקּוּדָא, אִיהוּ עִץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ (בראשית יא א), נָטוּעַ בְּגַן בְּלָא עִרְבוּבְיָא כְּלָל, וּבְגִין דָּא אָמַר לְמִינוֹ, אֲבָל עִץ הַדַּעַת טוֹב וָרָע לָא אִתְּמַר בֵּיהּ לְמִינוֹ, אֲבָל מְעוּרָב מִין דְּלָא בְמִינֵיהּ, וּבְגִינֵיהּ אִתְּמַר (ויקרא יט יט) שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם וכו', שַׁעַטְנֵז לֹא יַעֲלֶה עָלֶיךָ.</p>\n<p>זַכָּאָה אִיהוּ מָאן דְּסָלִיק אֱמוּנָה דְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהִי שְׁכִינְתֵּיהּ כְּלִילָא מֵעִִשֶׂר אֲמִירָן, בְּמַחֲשַׁבְתָּא חֲדָא בִּרְעוּתָא חֲדָא בְּלָא עִרְבוּבְיָא כְּלָל, דְּכָל סְפִירָה וּסְפִירָה נְטוּעָה בֵּיהּ, וְאִיהִי גַן דְּכֻלְּהוּ סְפִירָן בָּהּ אִינוּן חָד, וְכָל חַד עָבִיד בָּהּ פְּרִי לְמִינוֹ, אִיהִי מִין דְּכָל חַד וְחַד לָא נָפִיק מִנֵּיהּ זַרְעִין לְבָר, הָכִי צָרִיךְ בַּר נַשׁ דְּלָא אַפִּיק זַרְעָא לְבָר מִבַּת זוּגֵיהּ, דְּאִיהִי מִין דִּילֵיהּ יִחוּדָא דִילֵיהּ, וּבְהַהוּא זִמְנָא דְצָרִיךְ בַּר נַשׁ לְיַחֲדָא לְקוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיהּ, צָרִיךְ לְהַפְשִׁיט מִנֵּיהּ כָּל מַחֲשָׁבִין דְּאִינוּן קְלִיפִין, דְּאִתְּמַר בְּהוֹן (משלי יט כא) רַבּוֹת מַחֲשָׁבוֹת בְּלֶב אִישׁ, וּלְסַלְקָא שְׁכִינְתֵּיהּ לְגַבֵּיהּ בְּמַחֲשַׁבְתָּא חֲדָא, הֲדָא הוּא דִכְתִיב (שם) וַעֲצַת יהו\"ה הִיא תָקוּם, כְּגַוְונָא דְבַר נַשׁ דְּמִתְיַחֵד בְּבַת זוּגֵיהּ, וְאִתְפַּשַּׁט מִלְּבוּשׁוֹי לְמֶהֱוִי עִמָּה חַד, הֲדָא הוּא דִכְתִיב (בראשית ב כא) וְהָיוּ לְבָשָׂר אֶחָד, הָכִי צָרִיךְ לְאַפְשָׁטָא מִנֵּיהּ כָּל מַחֲשָׁבִין אָחֳרָנִין, בְּזִמְנָא דִמְיַחֵד לְקוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹמָא תְּרֵין זִמְנִין, שְׁמַע יִשְׂרָאֵל יהו\"ה אלהינ\"ו יהו\"ה אֶחָד.</p>"],[9500011195,"<p>בְּרֵאשִׁית בָּרָא אלהי\"ם דָּא מטטרו\"ן, דְּבָרָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא קַדְמוֹן וְרֵאשִׁית לְכָל צְבָא הַשָּׁמַיִם דִּלְתַתָּא, וְדָא אִיהוּ אָדָם הַקָּטֹן, דְּקוּדְשָׁא בְּרִיךְ הוּא עָבַד לֵיהּ בְּדִיּוֹקְנָא וְצִיּוּרָא דִלְעִילָא בְּלָא עִרְבוּבְיָא, וַעֲלֵיהּ אִתְּמַר (בראשית א כד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ, וְאִיהוּ עִץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ (שם יא ז), כְּגַוְונָא דִלְעִילָא וַי מָאן דְּעָבִיד עִרְבוּבְיָא לְעִילָא וּלְתַתָּא, דְּהַאי אִילָנָא דְעִרְבוּבְיָא, עִרְבוּבְיָא מֵאִילָנָא דְמוֹתָא, בְּגִין דָּא אִתְקְרֵי מַטֶּה, דְּאִתְהַפַּךְ לְנָחָשׁ לְאַלְקָאָה בֵּיהּ לְחַיָּבַיָּא, וּמָאן אִיהוּ דְאַפִּיךְ לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דְּשַׁלִּיט עֲלֵיהּ וְהָא אוּקְמוּהָ.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר אַבָּא, כֵּיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה יָדַע דְּאִילָנָא דָא הֲוָה עָתִיד לְגָרְמָא מִיתָה לְאָדָם (ולכל בריין דעתידין למהוי אבתריה) אַמַּאי בָּרָא לֵיהּ לְאָדָם דְּעָתִיד לְמֶחטֵי קַמֵּיהּ, אָמַר לֵיהּ בְּרִי דִּיּוֹקְנָא דִלְעִילָא לָא הֲוָה שְׁלִים עַד דְּבָרָא לְאָדָם, דְּהָכִי הֲוָה אָדָם דִּלְעִילָא (כ\"י לגבי אדם דלתתא), כְּגַוְונָא דְנִשְׁמָתָא לְגַבֵּי גוּפָא, וּכְמָה דְלָא אִית עוֹבָדָא לְנִשְׁמָתָא בְלָא גוּפָא, הָכִי הֲוָה צָרִיךְ לְמֶעֱבַד דִּיּוֹקְנָא לְתַתָּא לְאַפָּקָא בֵּיהּ עוֹבָדָא, וְכֹלָּא כְּגַוְונָא (כעובדא) דִלְעִילָא, אָדָ\"ם אִיהוּ לְחֻשְׁבַּן זְעִיר דַּחֲנוֹ\"ךְ תֵּשַׁע נְקוּדִין, פְּעוּלָה דִילֵיהּ שְׁכִינְתָּא כְּלִילָא בְּכָל (מכל) אַתְוָון דְּאוֹרַיְיתָא, וְכֹלָּא כְּגַוְונָא דִלְעִילָא.</p>\n<p>אָדָם דִּלְעִילָא לָא הֲוָה שְׁלִים בְּלָא נוּקְבָא, הֲדָא הוּא דִכְתִיב (שם ה ב) זָכָר וּנְקֵבָה בְּרָאָם וַיִּקְרָא אֶת שְׁמָם אָדָם, אָדָם דְּכַר, וְאָדָם נוּקְבָא, וְכַד אִתְבְּרִי אָדָם דִּלְתַתָּא דְאִיהוּ נוּקְבָא, הֲדָא הוּא דִכְתִיב (שם א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, אִשְׁתַּלִּים דִּיּוֹקְנָא דִלְעִילָא, וְדָא אִיהוּ רָזָא כִּי לֹא הִמְטִיר יהו\"ה אלהי\"ם וכו' (שם ב ה), וְאַמַּאי בְּגִין דְּאָדָם אַיִן, וּבְגִין דָּא מוּכְרַח הֲוָה אָדָם לְמִבְרֵי לֵיהּ, לְאִשְׁתַּלִּים בֵּיהּ דִּיּוֹקְנָא דִלְעִילָא, וְנוּקְבָא בְּהַאי אָדָם בָּהּ הֲוָה חָד, הֲדָא הוּא דִכְתִיב (ישעיה נא ב) כִּי אֶחָד קְרָאתִיו וְגוֹמֵר, וְדָא רָזָא דְנִשְׁמָתָא.</p>\n<p>לְבָתַר אָמַר (בראשית ב יח) לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לּוֹ עִזֶר כְּנֶגְדּוֹ, דָּא גוּפָא דְּאִיהוּ עִִבֶד שִׁפְחָה כְּלִיל מִטּוֹב וָרָע, בְּגִין לְמֶהֱוֵי לֵיהּ אַגְרָא וְעוּנְשָׁא, וּבְגִינָהּ אָמַר (דברים ל טו) רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים וְאֶת הַטּוֹב אֶת הַמָּוְת וְאֶת הָרָע, וְאָמַר לֵיהּ וּבָחַרְתָּ בַּחַיִּים, דְּאִם לָא יַהֲבָה בִּידֵיהּ, לָא הֲוָה לֵיהּ אַגְרָא וְעוּנְשָׁא, וַהֲוָה כִּבְעִירָא, וְעִם כָּל דָּא אַחֲזֵי קוּדְשָׁא בְּרִיךְ הוּא לֵיהּ, כָּל מַה דְּאִירַע לֵיהּ, אִם הֲוָה מַטֶּה כְּלַפֵּי חֶסֶד דְּהוּא כְלַפֵּי זְכוּ, אוֹ אִם הֲוָה מַטֶּה בָּהּ כְּלַפֵּי חוֹבָא, דְּאִי קוּדְשָׁא בְּרִיךְ הוּא בָּעָא בְמִיתָתֵיהּ לָא הֲוָה אַחֲזֵי לֵיהּ תְּרֵין אוֹרְחִין דִּילֵיהּ, דְּאִינוּן מָוְת וְחַיִּים בְּיַד לָשׁוֹן.</p>\n<p>וְאַחֲזֵי לֵיהּ דְּלָא הֲוָה מְעָרֵב טוֹב בְּרָע, דְּאַפְרִישׁ לוֹן קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמַר (בראשית א ד) וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ, וְרָזָא דְמִלָּה וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם (שמות כו לג), וְהָכִי עָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּגוּפָא דְבַר נַשׁ טַרְפְּשָׁא, דְאַפְרִישׁ בֵּין דַּרְגִּין דְּאִילָנָא דְטוֹב, וּבֵין דַּרְגִּין דְּאִילָנָא דְרָע, וּמַנִּי לוֹן דְּלָא לְעָרְבָא טוֹב עִם רָע, כְּמָה דְאַתְּ אָמַר (בראשית ב יז) וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, קוּדְשָׁא בְּרִיךְ הוּא מַנִּי לֵיהּ לְאִסְתַּמְרָא מִנֵּיהּ, וּלְבָתַר אָמַר אִיהוּ (שם ג יב) הָאִשָּׁה אֲשֶׁר נָתַתָּ עִמָּדִי וְגוֹמֵר.</p>\n<p>אַדְהָכִי הָא סָבָא חַד אִזְדַּמַּן לֵיהּ, וְאָמַר רַבִּי רַבִּי, הָא חֲזֵינָא קְרָא דְּאָמַר בְּאוֹרַיְיתָא (במדבר יט יד) אָדָם כִּי יָמוּת בְּאֹהֶל, וְהָא אוֹרַיְיתָא קֳדָם דְּאִתְבְּרִי עָלְמָא הֲוַת, וַחֲזֵינָא דְעָלְמָא אַקְדִּים לְאָדָם, דְּכָל עָלְמָא וְצָרְכוֹי אִתְבְּרִיאוּ קֳדָם דְּאִתְבְּרִי אָדָם, אִי הָכִי מַאי תַּקַּנְתָּא אִית הָכָא, אָמַר לֵיהּ סָבָא וְהָא כְּתִיב דְּנִשְׁמָתִין דְּצַדִּיקַיָּיא אִתְבְּרִיאוּ קֳדָם דְּאִתְבְּרִי עָלְמָא, כְּמָה דְאַתְּ אָמַר (בראשית א א) בְּרֵאשִׁית בָּרָא אלהי\"ם וְלֵית רֵאשִׁית אֶלָּא נְשָׁמָה, דְאִתְּמַר בֵּיהּ (משלי כ כז) נֵר יהו\"ה נִשְׁמַת אָדָם, אִיהִי נִשְׁמָתָא דְאָדָם דִּלְעִילָא, אֶלָּא אִית אָדָם וְאִית אָדָם, אִית אָדָם דְּאִיהוּ אָדָם דְּנִשְׁמָתָא, וְאִית אָדָם דְּגוּפָא, דְּאִתְּמַר בֵּיהּ (תהלים קמד ד) אָדָם לַהֶבֶל דָּמָה, וַעֲלֵיהּ אִתְּמַר (במדבר יט יד) אָדָם כִּי יָמוּת בְּאֹהֶל, וַעֲלֵיהּ אִתְּמַר (ירמיה יז ה) אָרוּר הַגֶּבֶר אֲשֶׁר יִבְטַח</p>"],[9500011196,"<p>בָּאָדָם וְשָׂם בָּשָׂר זְרוֹעוֹ, וְדָא סמא\"ל אָדָם בְּלִיַּעַל אִישׁ אָוְן, וְאִית לֵיהּ תְּרֵין נוּקְבִין בִּישִׁין, וַעֲלַיְיהוּ אִתְּמַר (ויקרא כא יא) עַל כָּל נַפְשׁוֹת מֵת לֹא יָבֹא, לְאָבִיו וּלְאִמּוֹ לֹא יִטַּמָּא, וְלֵית אָבִיו אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, וְלֵית אִמּוֹ אֶלָּא שְׁכִינְתָּא, וְכִי לָא אִתְּמַר בְּקוּדְשָׁא בְּרִיךְ הוּא וּבִשְׁכִינְתֵּיהּ (ירמיה כג כט) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם יהו\"ה, מָה אֵשׁ אֵינוֹ מְקַבֵּל טֻמְאָה הָכִי אִיהוּ לָא מְקַבֵּל טֻמְאָה, אָמַר לֵיהּ וְהָא כְּתִיב (במדבר יט כ) אֶת מִקְדַּשׁ יהו\"ה טִמֵּא וְדָא שְׁכִינְתֵּיהּ, אָמַר לֵיהּ וַדַּאי דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ לָא מְקַבֵּל טוּמְאָה, אֲבָל כָּל מָאן דְּסָאִיב אֲתַר דְּאִיהִי שַׁרְיָא בֵּיהּ, אִתְחֲשִׁיב לֵיהּ כְּאִלּוּ עָבִיד לֵיהּ, וּבְגִין דָּא לְאָבִיו וּלְאִמּוֹ לֹא יִטַּמָּא, וְלֵית אָבִיו אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, וְלֵית אִמּוֹ אֶלָּא שְׁכִינְתָּא, וְדָא אִיהוּ רָזָא מָאן דְּאַעִיל מֵרְשׁוּת הָרַבִּים לִרְשׁוּת הַיָּחִיד, וּבְגִין דָּא אָמַר (ויקרא כב לב) וְלֹא תְחַלְּלוּ אֶת שֵׁם קָדְשִׁי, וְדָא אדנ\"י, דְּאִיהוּ רְשׁוּת הַיָּחִיד דְּאִיהוּ יהו\"ה יְחִידוֹ דְעָלְמָא, וְדָא אִיהוּ אָדָם. (ובגין דא לאביו ולאמו לא יטמא, ודא איהו רזא מאן דאעיל מרשות הרבים לרשות היחיד, ובגין דא אמר) (במדבר יט יד) אָדָם כִּי יָמוּת בְּאֹהֶל, דָּא אָדָם בְּלִיַּעַל, וּמִסִּטְרָא דָא בַּר נַשׁ רָשָׁע קָרוּי מֵת מֵעִיקָרָא מִקַּמֵּי דְאִתְבְּרִי עָלְמָא, אֲבָל לָא אִתְּמַר עַל אָדָם דְּאִיהוּ מִסִּטְרָא דְקוּדְשָׁא, וְכַמָּה טִפְּשִׁין אִינוּן בְּעָלְמָא דְאָמְרִין הָא קוּדְשָׁא בְּרִיךְ הוּא גָזַר עַל בַּר נַשׁ דְּיָמוּת, הֲדָא הוּא דִכְתִיב אָדָם כִּי יָמוּת, וְאֵיךְ אָמְרִין דְּלָא יְהֵא מִיתָה מִינֵיהּ, וַי לוֹן דְּטַב לוֹן דְּלָא אִתְבְּרִיאוּ בְעָלְמָא, דְאִלֵּין אִינוּן דְּשַׁוְיָן לוֹן, שַׁוְיָן לְאָדָם דְּאִתְקְרֵי יִשְׂרָאֵל וּלְאָדָם בְּלִיַּעַל, וְאָמְרִין כְּאָדָם טוֹב כַּחוֹטֵא כּוּלְהוֹן שָׁוִין, יִהְיוּ כְמוֹץ לִפְנֵי רוּחַ אִלֵּין חַיָּיבַיָּא דְאָמְרֵי הָכִי, וּמַלְאַךְ יהו\"ה דּוֹחֶה מִנַּיְיהוּ.</p>\n<p>דְּאִית אָדָם דְּאִיהוּ יִשְׂרָאֵל, וְאִית אָדָם דְּאִיהוּ מַלְאָךְ וְדָא מטטרו\"ן, וְאִית אָדָם בְּדִיּוֹקְנָא דְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ אֲצִילוּתֵיהּ, וְדָא יו\"ד ה\"א וא\"ו ה\"א, וְלֵית לֵיהּ בְּרִיאָה וִיצִירָה וַעֲשִׂיָּה אֶלָּא אֲצִילוּתָא, וּבַאֲתַר דָּא לֵית חֵטְא וְלָא מָוְת, הֲדָא הוּא דִכְתִיב (תהלים ה ה) לֹא יְגוּרְךָ רָע, וְעַל הַאי אָדָם בְּלִיַּעַל מַנִּי קוּדְשָׁא בְּרִיךְ הוּא דְלָא לְמֵיכַל מִנֵּיהּ, וּדְלָא לְעָרְבָא לֵיהּ עִם טוֹב, דְּהַאי אִיהוּ כְּמָאן דְּעָרֵיב כַּסְפָּא עִם עוֹפָרֶת, וְדָא גָרִים בִּלְבּוּלָא בְּפַמַּלְיָא דִלְעִילָא, וְעָרַב חֲשׁוֹכָא בִנְהוֹרָא מַה דְּאַפְרִישׁ קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמַר (בראשית א ד) וַיַּבְדֵּל אלהי\"ם בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ.</p>\n<p>וְלָא עוֹד אֶלָּא מָאן דְּאַעִיל זַרְעִיהּ בַּנִּדָּה אוֹ שִׁפְחָה אוֹ גוֹיָה אוֹ זוֹנָה, כְּאִלּוּ מְעָרֵב מַה דְּאַפְרִישׁ קוּדְשָׁא בְּרִיךְ הוּא, דִכְתִיב (שם ו) וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, דְּאִינוּן מֵי נִדָּה לְמֵי דַכְיָא, דְּדָא אָסוּר וְדָא מוּתָּר, וְדָא כָּשֵׁר וְדָא פָסוּל, דָּא טוּמְאָה וְדָא טַהֲרָה, אִלֵּין אִינוּן שִׁית סִדְרִין דְּאִתְיְהִיבַת (בהון משנה) (ס\"א למשה), לְאַפְרָשָׁא בֵּין טוֹב לָרָע, דְּעָרַב לוֹן אָדָם וְדָרִין דְּאָתוּ אַבַּתְרֵיהּ.</p>\n<p>בְּרֵאשִׁית בָּרָא אלהי\"ם, מַאי אלהי\"ם, לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמוֹר אֶת דֶּרֶךְ עִץ הַחַיִּים (בראשית ג כד), מַטֵּה הָאלהי\"ם וַדַּאי, וְדָא מטטרו\"ן, וְהָא אוּקִימְנָא לֵיהּ דְּאִתְהַפַּךְ מִדִּינָא לְרַחֲמֵי, וּבֵיהּ אִשְׁתַּנִּיּוּ (נ\"א אשתכחו) כָּל דִּיּוֹקְנִין דְּלָא דָמוּ דָא לְדָא, כַּד אִתְהַפַּךְ מִימִינָא לִשְׂמָאלָא אַחֲזֵי פַּרְצוּפָא דְשׁוֹר, וְכַד אִתְהַפַּךְ מִשְּׂמָאלָא לִימִינָא אַחֲזֵי פַּרְצוּפָא דְאַרְיֵה, וְכַד אִתְהַפַּךְ מִתַּרְוַיְיהוּ לְמַעֲרָב אַחְזִיר אַנְפּוֹי וְאִתְהַפַּךְ לְנֶשֶׁר (נ\"א לאד; ם), וְכַד אִתְהַפַּךְ מִתַּרְוַיְיהוּ לְמִזְרָח דְּאִיהוּ בְּאֶמְצָעִיתָא אִתְהַפַּךְ לְאָדָם (נ\"א לנשר), מִלְּמַטָּה לְנֶשֶׁר, לֵית דִּיּוֹקְנָא בְעָלְמָא דְּלָא אִשְׁתְּמוֹדָע בֵּיהּ.</p>\n<p>תְּרֵין עֲשַׂר מַזָּלוֹת אִתְחַזְיָין בֵּיהּ, וְכָל דִּיּוֹקְנִין דְּמַלְאָכַיָּיא וְדִיּוֹקְנִין דְּנִשְׁמָתִין וְדִיּוֹקְנִין דְּכָל מַה דְּאִתְבְּרִי בִּשְׁמַיָּא וּבְאַרְעָא, (לאו איהו דיוקנא דאדם שלים בכל תקונין, אלא אם הוא) (נ\"א כלא הוה) כְּלִיל בִּשְׁמַיָּא וְאַרְעָא וְשִׁמְשָׁא וְסִיהֲרָא וְכֹכְבַיָּא וּמַזָּלַיָּא וְכָרְסַיָּא וּמַלְאָכַיָּא וְגַן עִדֶן וְגֵיהִנָּם, מִסִּטְרָא דְתַרְוַיְיהוּ אִתְיְהִיב יֵצֶר הַטּוֹב וְיֵצֶר הָרָע, גַּן עִדֶן מָצָא אִשָּׁה מָצָא טוֹב (משלי יח כב), גֵּיהִנָּם וּמוֹצֶא אֲנִי מַר מִמָּוְת אֶת הָאִשָּׁה (קהלת ז כו), וְתַרְוַיְיהוּ בְּלִבָּא, לֵב חָכָם לִימִינוֹ, וְלֵב כְּסִיל לִשְׂמֹאלוֹ (שם י ב).</p>"],[9500011197,"<p>בְּרֵאשִׁית ב' תְּרֵין חָכְמָה וּתְבוּנָה (ובינה), תְּלִיתָאָה יִרְאַת יהו\"ה רֵאשִׁית דָּעַת (משלי א ז). וּבְהַאי דַּעַת אִתְּמַר (בראשית ד א) וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ, דְּלֵית זִוּוּג אֶלָּא בְדַעַת דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא. יִחוּדָא דְאַבָּא וְאִימָּא. הָכִי אִיהוּ לְתַתָּא צַדִּיק יִחוּדָא דְעַמּוּדָא דְאֶמְצָעִיתָא וּשְׁכִינְתָּא דִלְתַתָּא, וְגוּף וּבְרִית עֲלַיְיהוּ אִתְּמַר (שמואל א ב ג) כִּי אֵ\"ל דֵּעוֹת יהו\"ה וְגוֹמֵר, וְתַרְוַיְיהוּ עִדוּת, דְּלֵית עִדוּת פָּחוּת מִתְּרֵין.</p>\n<p>וְהַאי בֵּן אִיהוּ יִחוּד דְּאַבָּא וְאִימָּא, אִיהוּ עַמּוּד סָבִיל כֹּלָּא, כְּגַוְונָא דִשְׁמַיָּא וְאַרְעָא דְאִתְּמַר בְּהוֹן דְּעָלְמָא עַל חַד סַמְכָא קַיְימָא, כְּמָה דְאַתְּ אָמַר (משלי י כה) וְצַדִּיק יְסוֹד עוֹלָם, הָכִי אַבָּא וְאִימָּא סָמְכִין עַל עַמּוּדָא דְאֶמְצָעִיתָא, וְאִיהוּ יִחוּד בֵּין אֵם וּבַת כְּגַוְונָא דָא הו\"ה, וּבֵיהּ אִתְעֲבִידוּ ה\"ה אֶחָד אֶחָד י\"ג הָכָא וְי\"ג הָכָא, וְאִיהוּ ו' יִחוּד דִּתְרֵי אֲחָיוֹת, כְּגַוְונָא דָא וַיִּיצֶר יהו\"ה, דָּא רָזָא דְא' י' לְעִילָא י' לְתַתָּא ו' בְּאֶמְצָעִיתָא.</p>\n<p>יִחוּדָא דְתַרְוַיְיהוּ כַּלָּה וַחֲמוֹתָהּ, (ה' מן אלהי\"ם ו') (נ\"א ה\"י מן אלהי\"ם ו' מלא), כְּלָלָא דְתַרְוַיְיהוּ ה\"ה אִמָּא וּבְרַתָּא, ו' בֵּין תַּרְוַיְהוּ, לְעִילָא לֵית עִִרְוָה, וּבַאֲתַר דָּא אָמַר לֹא תִּדְמֶה לְיוֹצְרֶיךָ, לְתַתָּא בַּר מֵאַתְרֵיהּ אָמַר (ויקרא יח ו) לֹא תִקְרְבוּ לְגַלּוֹת, וְהָא אוּקִימְנָא לְעִיל. וְעוֹד אַשְׁכַּחְנָא רָזָא עִלָּאָה, עִִרְוָ\"ה עִ\"ר ו\"ה, כַּד ו' בֵּין עִר דְּאִיהוּ רַע אִתְעֲבִיד עוֹר, הֲדָא הוּא דִכְתִיב (בראשית ג כא) וַיַּעַשׂ יהו\"ה אלהי\"ם לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּישֵׁם, וַעֲלַיְיהוּ אִתְּמַר (ויקרא יט יד) וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, דְּהָא רַע מִן עִוֵּר, אִיהוּ עִִרְוָה דְאַפְרִישׁ בֵּין ו\"ה דְּאִינוּן אָח וְאָחוֹת, כַּד אִתְלַבַּשׁ אִילָנָא דְחַיֵּי בְּאִילָנָא דְטוֹב וָרָע, הֲדָא הוּא דִכְתִיב (בראשית ב ט) וְעִץ הַחַיִּים בְּתוֹךְ הַגָּן, וְעִץ הַדַּעַת טוֹב וָרָע, בְּזִמְנָא דְאִיהִי (ס\"א דהאי) עִר בֵּין בְּרָא וּבְרַתָּא לֹא תִקְרְבוּ לְגַלּוֹת עִִרְוָה, לֹא תִקְרְבוּ ו' לְה' דְּלָא אִתְגַּלְיָא רַע בֵּינַיְיהוּ דְאִיהוּ אַחֵר, דַּעֲלֵיהּ אִתְּמַר (משלי כה ט) וְסוֹד אַחֵר אַל תְּגַל, עִִרְיָ\"ה תֵעוֹר קַשְׁתֶּךָ (חבקוק ג ט), עִר יה, רַע בְּזִמְנָא דְאִיהוּ בֵּין י\"ה, הַהוּא רַע לָא תִקְרַב י' בְּה'.</p>\n<p>וְהַאי אִיהוּ קְלִיפָה דְעָרְלָה, עִ\"ר מִן עָרְלָה רָ\"ע, אָדָם בְּהַאי חָאב, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין אָדָם הָרִאשׁוֹן מוֹשֵׁךְ בְּעָרְלָתוֹ הֲוָה, וְדָא גָרִים עִִרְיָין בְּעָלְמָא, וּבְגִין דָּא עִִרְיָה תֵעוֹר קַשְׁתֶּךָ, תֵעוֹר אִיהוּ עִִרְוַת בְּהִפּוּךְ אַתְוָון, בְּאָן אֲתַר קַשְׁתֶּךְ דְּאִיהוּ קֶשֶׁת הַבְּרִית, דַּעֲלֵיהּ אִתְּמַר (בראשית לה טז) וַתֵּלֶד רָחֵל וַתְּקַשׁ בְּלִדְתָּהּ, תְּקַ\"שׁ אִיהוּ קֶשֶׁ\"ת, (ורזא דמלה בעצב תלדי בנים), (שם ג טז) וּמִתַּמָּן אָמְרָה חַנָּה (שמואל א א טו) אִשָּׁה קְשַׁ\"ת רוּחַ אָנֹכִי.</p>\n<p>וְדָא רָזָא אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן, וְאוּקְמוּהוּ חַבְרַיָּא מִלָּה דְאַקִּישׁ לִי, מוֹקֵשׁ כְּתִיב בֵּיהּ, דְּבֵיהּ הֲוָה מוֹקֵשׁ לְאָדָם קַדְמָאָה, כְּמָה דְאוּקְמוּהוּ אָדָם הָרִאשׁוֹן מוֹשֵׁךְ בְּעָרְלָתוֹ הֲוָה, וּמַה דְּנָטִיר לֵיהּ אִיהוּ בְּהֵקֵשׁ בְּשׁוּתָּפוֹ עִמִּי, בְדִיּוֹקְנָא דִילִי, עֲלָהּ אִתְּמַר (שם א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ, בְּגִין דְּמָאן דְּנָטִיר בְּרִית זָכָה לְמַלְכוּת, הֲרֵי אִיהוּ בְהֵקֵשׁ לִי בְּשׁוּתָּפוֹ עִמִּי, וְאִם לָא נָטִיר לֵיהּ אִתְחַזַּר קַ\"שׁ, קָשֶׁה לֵיהּ קָשֶׁה לְאָת ה', וְעַל הַאי קַשׁ אִתְּמַר (עובדיה א יח) וּבֵית עִשָׂו לְקַשׁ, וְאִיהוּ לְקַ\"שׁ בְּהִפּוּךְ אַתְוָון שֶׁקֶ\"ל, וְאִיהוּ שֶׁקֶל לַצַּדִּיקִים דְּנָטְרִין בְּרִית שֶׁקֶל הַקֹּדֶשׁ, וַוי לְמָאן דְּלָא נָטִיר לֵיהּ, וְזַכָּאָה אִיהוּ מָאן דְּנָטִיר לֵיהּ, וּמָאן דְּנָטִיר בְּרִית הַאי אִיהוּ עִד עֲלֵיהּ ע' מִן שְׁמַע ד' מִן אֶחָד, וְאִי לָא נָטִיר בְּרִית פָּרַח מִנֵּיהּ קוֹצָא מִן ד' מִן אֶחָד, וְאִשְׁתָּאַר אַחֵר (עד ער). (כאן חסר)</p>\n<p>וְהָאָדָם יָדַע וכו' (בראשית ד ד), קָם סָבָא פָּתַח וְאָמַר רַבִּי רַבִּי וְעַד הָכָא לָא הֲוָה יָדַע אָדָם לְאִנְתְּתֵיהּ, אֶלָּא בְּזִמְנָא דְחָאב אִסְתַּלַּק שְׁכִינְתָּא מֵאַתְרֵיהּ, וְהָכִי אוּקְמוּהוּ מָארֵי מַתְנִיתִין, דִּבְּזִמְנָא דְלֵית שְׁכִינְתָּא בְּאַתְרָהּ אָסוּר בְּתַשְׁמִישׁ הַמִּטָּה, בְּגִין דַּעֲלָהּ אִתְּמַר (שם מז לא) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל</p>"],[9500011198,"<p>רֹאשׁ הַמִּטָּה, וּמֵאָן אֲתַר אִסְתַּלְקַת מִימִינָא וּמִשְּׂמָאלָא דְתַמָּן הֲוָה, וְדָא הוּא רָזָא דְעִיבּוּר (ס\"א ויעבו\"ר) ע\"ב רי\"ו, חֶסֶד גְּבוּרָה, וְלָא לְמַגָּנָא אוּקְמוּהוּ מָארֵי מַתְנִיתִין, הַנּוֹתֵן מִטָּתוֹ בֵּין צָפוֹן לַדָּרוֹם הַוְיָין לֵיהּ בָּנִים זְכָרִים, וְאִיהוּ גָרִים דְּאִסְתַּלַּק הַהִיא מִטָּה מִתַּמָּן, הָכִי אִסְתַּלִּיק אִיהוּ מִתַּשְׁמִישׁ הַמִּטָּה, וּבָתַר דְּקַבִּיל עוֹנְשֵׁיהּ אִתְחַזַּר מִטָּה לְאַתְרָהָא, בְּהַהוּא זִמְנָא וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ.</p>\n<p>וְעוֹד וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ, אִית יְדִיעָה לְטַב וְאִית יְדִיעָה לְבִישׁ, כְּגוֹן (שם ג ז) וַיֵּדְעוּ כִּי עִרוּמִים הֵם, וּכְגוֹן וְאַתְּ עִרוֹם וְעִִרְיָה (יחזקאל טז ז), עִרוֹם מֵאוֹרַיְיתָא דְבִכְתָב, וְעִִרְיָה מֵאוֹרַיְיתָא דִבְעַל פֶּה.</p>\n<p>וְעוֹד וְהָאָדָם יָדַע, כְּגוֹן (אסתר ד א) וּמָרְדֳּכַי יָדַע אֶת כָּל אֲשֶׁר נַעֲשָׂה, הָכִי אָדָם יָדַע דְּגָרִים אַפְרָשׁוּתָא בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּבֵין שְׁכִינְתֵּיהּ, דְּאָדָם חָאב בְּמַחֲשָׁבָה, וְחַוָּה חָאבַת בְּמַעֲשֶׂה, בְּהַהוּא אֲתַר דְּאִתְּמַר בֵּיהּ יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה, בְּהַהוּא אֲתַר דְּאִתְנַטִּל נִשְׁמָתֵיהּ בְּאֹרַח אֲצִילוּת תַּמָּן חָאב, וְחַוָּה בְּמַעֲשֶׂה דִילֵיהּ, דְּאִיהִי כֹּחַ דִּילֵיהּ כ\"ח אַתְוָון דְּמַעֲשֵׂה בְּרֵאשִׁית, וְכֹלָּא חָכְמָ\"ה כֹּ\"חַ מָ\"ה.</p>\n<p>וְעוֹד וְהָאָדָם יָדַע, יָדַע חוֹבָא דִילֵיהּ בְּמַאי בְּקַיִן, כְּמָה דְאַתְּ אָמַר (בראשית ד א) וַתַּהַר וַתֵּלֶד אֶת קַיִן, בְּגִין דַּעֲלֵיהּ אִתְּמַר (ישעיה יד כט) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע, דְּאִיהוּ זוּהֲמָא דְאַטִּיל נָחָשׁ בְּחַוָּה, וַהֲוָה יָדַע זוּהֲמָא דִילֵיהּ דְּאִתְפַּשַּׁט עַד קֵנִי חוֹתֵן מֹשֶׁה, וְכַד חָמָא גִלְגוּלָא וּתְיוּבְתָּא דִילֵיהּ תַּמָּן, אָמַר (בראשית ד א) קָנִיתִי אִישׁ אֶת יהו\"ה, כְּעַן יְדַעִִנָא לֵיהּ דְּקָנִיתִי לֵיהּ בְּקֵנִי חוֹתֵן מֹשֶׁה, וְרַוַוחְנָא לֵיהּ תַּמָּן, וּבְגִין דָּא אִתְּמַר קָנִיתִי אִישׁ אֶת יהו\"ה, וְדָא אִיהוּ רָזָא (קהלת ח י) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וָבָאוּ וכו'.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, סָבָא סָבָא, וְאַמַּאי טָרַח קוּדְשָׁא בְּרִיךְ הוּא בְּהוֹן, לְאַיְיתָאָה לוֹן בְּגִלְגּוּלָא, אָמַר לֵיהּ בְּגִין יְקָרָא דְצַדִּיקַיָּא לְאַעֲבָרָא חוֹבָא מִבְּנַיְיהוּ, דְּעַד דְּקַיִן תָּב בִּתְיוּבְתָּא פְּגִימוּ דְאָדָם לָא אִשְׁתַּלִּים, וּבְגִין דָּא לִיקָרָא דִילֵיהּ טָרַח קוּדְשָׁא בְּרִיךְ הוּא בְּקַיִן, וְהָכִי בְכָל רַשִּׁיעַיָּיא דְאִינוּן בְּנֵי צַדִּיקַיָּא.</p>\n<p>אָמַר לֵיהּ מַאי אִיהוּ זוּהֲמָא דְאַטִּיל נָחָשׁ בְּחַוָּה, אָמַר לֵיהּ דָּא לִילִי\"ת טִפָּה סְרוּחָה אִיהוּ זוּהֲמָא, וְאִיהִי שְׂאוֹר שֶׁבְּעִיסָה דְאִתְּמַר עֲלָהּ מִי מְעַכֵּב שְׂאוֹר שֶׁבְּעִיסָה, וְאִיהוּ אִיבָּא דְסמא\"ל, דְּאִתְּמַר בֵּיהּ (בראשית ג ו) וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל, דָּא מָוְ\"ת דְּאִתְּמַר עֲלָה (משלי ה ה) רַגְלֶיהָ יוֹרְדוֹת מָוְת, וְאִיהִי טִפָּה בִּישָׁא זוּהֲמָא דְאֵל אַחֵר, סַם מָוְת זוּהֲמָא וְעָרְלָה דְאִילָנָא דְמוֹתָא, וּבְגִינָהּ אוּקְמוּהָ מָארֵי מַתְנִיתִין אָדָם מוֹשֵׁךְ בְּעָרְלָתוֹ הֲוָה.</p>\n<p>וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, פָּתַח וְאָמַר (תהלים קד כט) תּוֹסֵף רוּחָם יִגְוָעוּן וְאֶל עֲפָרָם יְשׁוּבוּן, הָכָא רָמִיז גִּלְגּוּלָא דְצַדִּיקַיָּא, וְאַחֲזֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא גִלְגּוּלָא דִילֵיהּ בְּכָל דָּרָא וְדָרָא, אֵיךְ הֲוָה אָזִיל מִצַּדִּיק לַצַּדִּיק, עַד שִׁתִּין רִבּוֹא, עַד דְּמָטֵי לְהַהוּא דְאִתְּמַר בֵּיהּ (בראשית ו ג) בְּשַׁגַּם הוּא בָשָׂר, בְּשַׁגַּם זֶה הֶבֶל, וְאוּקְמוּהָ קַדְמָאֵי בְּשַׁגַּם דָּא מֹשֶׁה, וּמִיָּד דְּחָמָא דַעֲתִידָה אוֹרַיְיתָא לְאִתְיַיהֲבָא עַל יְדֵיהּ, אוֹסֵיפַת בְּגִינֵיהּ כַּמָּה קָרְבָּנִין לְקוּדְשָׁא בְּרִיךְ הוּא, וְכַמָּה צְלוֹתִין וּבָעוּתִין, וְדָא אִיהוּ וַתּוֹסֶף לָלֶדֶת.</p>\n<p>וּבְגִין דָּא אִתְּמַר בֵּיהּ (קהלת א ד) דּוֹר הוֹלֵךְ וְדוֹר בָּא, וְלֵית דּוֹר פָּחוּת מִשִּׁשִּׁים רִבּוֹא, וּלְעִילָא דּוֹר הוֹלֵךְ דָּא ו', דְּסָלִיק לְשִׁתִּין רִבּוֹא בְּשִׁית סְפִירָן. (שם) וְהָאָרֶץ לְעוֹלָם עוֹמָדֶת דָּא שְׁכִינְתָּא, דְאִיהִי עוֹמָדֶת לֵיהּ, וְאִיהִי שַׁעִִתָּא דְקַיְימָא לֵיהּ, וּבְגִינָהּ אִתְּמַר לֵית מַזָּל יוֹמָא גָרִים אֶלָּא מַזָּל שַׁעִִתָּא גָרִים, וְלֵית לְכָל בַּר נַשׁ קַיְימָא שַׁעִִתָּא, דְּהָא אִית בַּר נַשׁ צַדִּיק דְּלָא קַיְימָא לֵיהּ שַׁעִִתָּא, דְּלָא קַיְימָא שַׁעִִתָּא אֶלָּא לְבַעִִלָהּ, וְהַאי שַׁעִִתָּא מִינָהּ בָּנֵי חַיֵּי וּמְזוֹנֵי לְבַר נַשׁ, וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין בָּנֵי חַיֵּי וּמְזוֹנֵי לַאו בִּזְכוּתָא תַלְיָא מִלְתָא אֶלָּא בְּמַזָּלָא תַלְיָא מִלְתָא, מַאי מַזָּלָא דִילָהּ בַּעִִלָהּ, וּלְבַעִִלָהּ לֵית מַזָּל, כְּמָה דְאוּקִימְנָא אֵין מַזָּל לְיִשְׂרָאֵל, וְאַף עַל גַּב דְּכֹלָּא תַּלְיָא בְּמַזָּלָא אֲפִילוּ סֵפֶר תּוֹרָה שֶׁבְּהֵיכָל, הֵיכָל שְׁכִינְתָּא תַּתָּאָה, סֵפֶר תּוֹרָה צַדִּיק.</p>\n<p>וּתְרֵיסַר מַזָּלוֹת אִינוּן וְאִינוּן ו\"ו (דאשתכח ו') (נ\"ל דאשתכחו מאת א' ודא רזא דוא\"ו, וא' תמן ו' עלאה דאיהו מזלא עלאה דסליק במחשבה)</p>"],[9500011199,"<p>דְּאִיהוּ א תַּמָּן, ו' דְּאֶמְצָעִיתָא דְאָת א, אִיהוּ מַזָּלָא דְכֹלָּא, דְסָלִיק בְּאָת י' עִלָּאָה דְאִיהִי בְּרֵישָׁא דְאָת א, וְכַד סָלִיק בְּמַחֲשָׁבָה אִתְּמַר יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה, דְאִיהִי י' דְּעַל רֵישָׁא דְא', וּבְגִין דָּא לֵית מַזָּל לְיִשְׂרָאֵל (דהא במחשבה סליק, וכל מזלא איהו ממנא על שעתא מתרין עשר מזלות), דְּאִיהוּ מַזָּלָא דְכֹלָּא, וְכָל מַזָּלוֹת מִנֵּיהּ תַּלְיָין דְּאִינוּן ו' ו', דִּי מְמַנָּן עַל תְּרֵיסַר שַׁעִִתֵּי, דְאִינוּן הֵ\"א הֵ\"א, זַכָּאָה אִיהוּ מָאן דְּקַיְימָא לֵיהּ שַׁעִִתָּא.</p>\n<p>דְּאִיהוּ גִלְגּוּל דְּכֻלְּהוּ דָא י' דְּאִיהוּ גַלְגַּל, וְעִם ו' אִתְעֲבִיד גִּלְגּוּל, דְּאִיהוּ בְּרָזָא דְס\"ו מִן יְסוֹד. דְּאִתְּמַר בֵּיהּ (בראשית מו כו) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה שִׁשִּׁים וָשֵׁשׁ, לְאַתְעָרוּתָא דְעַמּוּדָא דְאֶמְצָעִיתָא שִׁשִּׁים, לְאַתְעָרוּתָא דְצַדִּיק וָשֵׁשׁ, וְכֹלָּא אִתְרְמִיז בְּצַדִּיק דְּבֵיהּ גִּלְגּוּל, וְעוֹד יְסוֹד תַּמָּן יוּ\"ד, דְּאִתְגַּלְגַּל בֵּיהּ וְנָח בֵּיהּ מִכָּל גִּלְגּוּלִין דְּאִתְגַּלְגַּל, וּבְגִין דָּא (שם ב ב) וַיְכַל אלהי\"ם בַּיּוֹם הַשְּׁבִיעִי מְלַאכְתּוֹ אֲשֶׁר עָשָׂה, וְאוֹת ו' דְּגִלְגּוּל בֵּיהּ סָלִיק צַדִּיק לְשִׁתִּין רִבּוֹא, בְּצַדִּיק אִינוּן שִׁית, וּבְעַמּוּדָא דְאֶמְצָעִיתָא סָלִיק לְשִׁתִּין, וּבְכֶתֶר עִלָּאָה דְאִיהוּ א סָלִיק לְשִׁתִּין רִבּוֹא, וְדָא אִיהוּ דּוֹר הוֹלֵךְ וְדוֹר בָּא.</p>\n<p>אָמַר לֵיהּ רַבִּי שִׁמְעוֹן וְהָא סָבָא אָמַר דְּאִיהוּ גִלְגּוּל בַּיְסוֹד אִיהוּ, וְתַמָּן י' דְּמִתְגַּלְגַּל בֵּיהּ וְשַׁרְיָא עֲלֵיהּ וְנָח בֵּיהּ מֵהַהוּא טָרְחָא דְגִלְגּוּלָא דְטָרַח בְּשִׁית יוֹמֵי, דְּסָלְקִין לְשִׁית בְּאָת ו', וּלְשִׁתִּין בְּי' שִׁית זִמְנִין עִִשֶׂר, וּלְשִׁית אַלְפִין בְּאַלֶּף, וּלְשִׁתִּין רִבּוֹא בְכֶתֶר עִלָּאָה, וְדָא אִיהוּ דּוֹר הוֹלֵךְ וְדוֹר בָּא וְהָאָרֶץ לְעוֹלָם עוֹמָדֶת.</p>\n<p>וּבְכָל זִמְנָא דְאָתֵי וְאָזִיל שַׁעִִתָּא קַיְימָא לֵיהּ, הֲדָא הוּא דִכְתִיב וְהָאָרֶץ לְעוֹלָם עוֹמָדֶת, דִּלְהַאי בַּת זוּגֵיהּ קַיְימָא לֵיהּ בְּכָל אֲתַר וּבְכָל גִּלְגּוּלָא וּבְכָל שַׁעִִתָּא, אַף עַל גַּב דְּאָזִיל וְאָתֵי בְכַמָּה גִלְגּוּלִין, הַאי אִיהוּ צַדִּיק וְטוֹב לוֹ, וּלְמָאן דְּשַׁעִִתָּא דִילֵיהּ לָא קַיְימָא לֵיהּ אֶלָּא שַׁעִִתָּא אָחֳרָא דְלַאו בַּת זוּגֵיהּ קַיְימָא לֵיהּ, וְהַאי אִיהוּ צַדִּיק וְרַע לוֹ, כְּמָה דְאוּקְמוּהָ מָארֵי מַתְנִיתִין כָּל מִי שֶׁדּוֹחֵק אֶת הַשָּׁעָה הַשָּׁעָה דוֹחֲקָתוֹ.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, וְהָא ר' פְּדָת צַדִּיק גָּמוּר הֲוָה, וְאַמַּאי לָא נָפַל בְּשַׁעִִתָּא דִילֵיהּ דְּאִיהִי בַּת זוּגֵיהּ בֶּן גִּילוֹ, אָמַר לֵיהּ בְּרִי אִית גִּלְגּוּלָא דִמְחַיֵּיב לֵיהּ דְּנָפִיל בְּמַזָּלֵיהּ דְּאִיהוּ בֶּן גִּילוֹ, דְאִתְּמַר בֵּיהּ (דברים ח ט) אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם, דְּאִיהִי שַׁעִִתָּא דִמְזוֹנֵי וְשַׁעִִתָּא דְחַיֵּי וּבָנֵי, וְאִית גִּלְגּוּלָא דִמְחַיֵּיב לֵיהּ דְּלָא נָפִיל בְּשַׁעִִתָּא דִמְזוֹנֵי דְאִיהִי בַת גִּילוֹ, אַף עַל גַּב דְּעָבִיד כַּמָּה זַכְוָון בְּעָלְמָא, וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין בָּנֵי חַיֵּי וּמְזוֹנֵי לַאו בִּזְכוּתָא תַלְיָא מִלְתָא אֶלָּא בְמַזָּלָא תַלְיָא מִלְתָא, דְּגִלְגּוּלָא גָרִים לֵיהּ כְּאִלּוּ בְּמַזָּלָא תַלְיָא מִלְתָא.</p>\n<p>וּמַה דְּאָמַר אִי בָּעִית דְּאַחֲרִיב לְעָלְמָא וְהָדַר אִבְרֵיהּ וְאֶפְשַׁר דִּנְפַלְתְּ בְּשַׁעִִתָּא דִמְזוֹנֵי, הָכִי שְׁמַעִִנָא בְּוַדַּאי דְּכָל צַדִּיק וְצַדִּיק יֵשׁ לוֹ עוֹלָם בִּפְנֵי עַצְמוֹ, דָא גוּפָא דְבַר נַשׁ דְּאִתְקְרֵי עוֹלָם קָטָן, וּבְגִין כַּךְ אִתְּמַר אִי בָּעִית דְּאַחֲרִיב לְעָלְמָא, וְאַיְיתֵי לֵיהּ בְּגִלְגּוּלָא אָחֳרָא, וְאוּלַי דִּנְפַלְתְּ בְּשַׁעִִתָּא דִמְזוֹנֵי.</p>\n<p>אַדְהָכִי הָא סָבָא דְסָבִין עַתִּיקָא דְעַתִּיקִין קָא נָחִית לְגַבֵּיהּ, וְאָמַר עוֹלָם דְּכָל צַדִּיק דָּא שְׁכִינְתָּא, כַּד אִסְתַּלַּק מִינָהּ עַמּוּדָא דְאֶמְצָעִיתָא וְאִשְׁתְּאָרַת חֲרֵיבָה, וּבְגִינָהּ אִתְּמַר תִּבְעִי דְאַחֲרִיב עָלְמָא, דְּכָל סְפִירָה וּסְפִירָה אִתְקְרִיאַת גַּלְגַּל, וְעִם ו' אִיהוּ גִלְגּוּל, וְשִׁית סְפִירָן בְּאַתְוָון סָלְקִין לְשִׁתִּין רִבּוֹא, וְדָא אִיהוּ דּוֹר הוֹלֵךְ וְדוֹר בָּא, וְלֵית דּוֹר פָּחוּת מִשִּׁתִּין רִבּוֹא, וְהָאָרֶץ לְעוֹלָם עוֹמָדֶת דָּא שְׁכִינְתָּא.</p>\n<p>דְאִיהִי אִתְקְרִיאַת אוּלַי, וַעֲלָהּ אִתְּמַר כּוּלֵי הַאי וְאוּלַי דְּזָכֵי לְשַׁעִִתָּא דִמְזוֹנֵי, וַעֲלָהּ אִתְּמַר (דניאל ח ב) עַל אוּבַל אוּלָי, דִּכְבָר אִתְחַיַּיב קֳדָם דְּיֵיתֵי לְעָלְמָא דְאִיהִי שְׁכִינְתָּא תַּתָּאָה, וְהָא אִתְחַיַּיב בִּסְפִירָה דְאִיהִי לְעִילָא מִנֵּיהּ, עַד דְּאִתְתַּקַּן לְהַהוּא אֲתַר דְּאִתְנְטִיל בַּר נַשׁ נִשְׁמָתֵיהּ, לֵית לֵיהּ תַּקָּנָה בִּשְׁכִינְתָּא תַּתָּאָה, דְאִיהִי שַׁעִִתָּא דְכֻלְּהוּ, וּבְגִין דָּא שַׁעִִתָּא לָא קַיְימָא לֵיהּ, וְאִם תַּלְיָא בְּמַזָּלָא עִלָּאָה אֲפִילוּ דְיַעֲבִיד כַּמָּה זַכְוָון לַאו בִּזְכוּתָא תַלְיָא מִלְתָא, דְהָא מְחוּיָיב אִיהוּ מִלְּעִילָא, אָמַר רַבִּי שִׁמְעוֹן מֵהָכָא מַשְׁמַע גִּלְגּוּלָא דְתַלְיָא</p>"],[9500011200,"<p>בִּשְׁכִינְתָּא דְאִיהוּ בְּמִינֵיהּ, אֲבָל אִם אַחֶרֶת יִקַּח לוֹ (שמות כא ו), אִם הַהוּא רוּחָא יֵיתֵי בְּגוּפָא אָחֳרָא, דְהָא לַאו אִיהוּ מִינֵיהּ, מַה כְּתִיב בֵּיהּ קַיְימָא לֵיהּ שַׁעִִתָּא תַּמָּן וְאִיהִי בַּת זוּגֵיהּ, אָמַר, וַדַּאי קַיְימָא לֵיהּ שַׁעִִתָּא דְאִיהִי בַת זוּגֵיהּ דְּאִתְגַּלְגַּל עִמֵּיהּ, אִם לָא קַיְימָא בֵיהּ שְׁאֵרָהּ כְּסוּתָהּ וְעוֹנָתָהּ לֹא יִגְרָע, שְׁאֵרָהּ דָּא גִלְגּוּלָא קַדְמָאָה, שְׁאֵר בְּשָׂרוֹ, כְּסוּתָהּ כִּי הִיא כְסוּתֹה לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעוֹרוֹ (שם כב כו) דָא גִלְגּוּלָא תִנְיָינָא, וְעוֹנָתָהּ אָדָם יִחוּדָא דִילֵיהּ דְּאִיהוּ גִלְגּוּלָא תְּלִיתָאָה.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן סָבָא סָבָא פְּתַח מִלִּין יַתִּיר דְּהָא סְתִימִין מִלִּין דִּילָךְ, אָמַר לֵיהּ הַהוּא סָבָא, שְׁאֵרָהּ דָּא מְזוֹנָא מִסִּטְרָא דִימִינָא דְמִתַּמָּן כָּל מְזוֹנָא קָא אַתְיָא, הֲדָא הוּא דִכְתִיב (תהלים קמה טז) פּוֹתֵחַ אֶת יָדֶיךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן.</p>\n<p>כְּסוּתָהּ מִסִּטְרָא דִשְׂמָאלָא דְאִיהוּ כְּסוּת עִינַיִם, דְּמִתַּמָּן עִִרְיָין לִשְׂמָאלָא, בְּגִין דְּסִטְרָא שְׂמָאלָא תַמָּן פְּגִימוּ, הֲדָא הוּא דִכְתִיב (ירמיה א יד) מִצָּפוֹן תִּפָּתַח הָרָעָה, וּבְגִין דָּא אִתְּמַר בְּיִצְחָק (בראשית כז א) וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶיןָ עִינָיו מֵרְאוֹת, וְתַמָּן צָרִיךְ כִּסּוּיָיא, וּמֹשֶׁה בְּהַהוּא אִתְּמַר בֵּיהּ (שמות ג ו) וַיַּסְתֵּר מֹשֶׁה פָּנָיו כִּי יָרֵא מֵהַבִּיט אֶל הָאלהי\"ם, וּבְגִין דָּא צִיצִית וּתְפִילִּין אִינוּן כִּסּוּיָא דִילָהּ, הֲדָא הוּא דִכְתִיב כִּי הִיא כְסוּתֹה לְבַדָּהּ הִיא שִׂמְלָתוֹ לְעוֹרוֹ, (ובעור דתפילין, כסותה לבדה היא שמלתו לעורו), בְּעוֹר דִּתְּפִלִּין, כְּסֻתָהּ עַל אַרְבַּע כַּנְפוֹת כְּסוּתְךָ אֲשֶׁר תְּכַסֶּה בָּהּ (דברים כב יב).</p>\n<p>וְעוֹנָתָהּ מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא דְאִיהוּ יִשְׂרָאֵל שְׁמַע יִשְׂרָאֵל, לְתַמָּן יִחוּדָא דִילָהּ, הֲדָא הוּא דִכְתִיב (שמות כא יא) וְאִם שְׁלָשׁ אֵלֶּה לֹא יַעֲשֶׂה לָהּ וְיָצְאָה חִנָּם אֵין כָּסֶף, דְּהֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר (איוב לג כט).</p>\n<p>אַבָּא דְאִיהוּ חָכְמָה בְּאִלֵּין תְּלַת נָחִית בְּגִלְגּוּל, וְהָא כְּתִיב בְּאָדָם וְחַוָּה דְסָלְקִין בְּמִטָּה שְׁנַיִם וְיָרְדוּ שֶׁבַע, אָמַר, וַדַּאי הָכִי אִיהוּ דְּאִינוּן אָדָם וְחַוָּה, קַיִן וּתְאוּמָתוֹ, הֶבֶל וּתְרֵין תְּאוּמוֹתָיו, וְקַיִן בְּגִין דַּהֲווֹ לְהֶבֶל תְּרֵין תְּאוּמוֹת וְלֵיהּ לָא הֲוָה אֶלָּא חַד, קַנִּי לְהֶבֶל, וְדָא גָרִים לֵיהּ כִּי שֶׁבַע יִפּוֹל צַדִּיק וָקָם (משלי כד טז), דְּחָב בִּשְׁכִינְתָּא דְאִיהוּ בַּת שֶׁבַע, וּבְגִין דָּא נָפַל בְּשֶׁבַע, דְּאִתְּתָא גָרִים לָהּ מִיתָה, וְדָא יְרִידָה דִילֵיהּ דִּנְחִיתַת שְׁכִינְתָּא תַּתָּאָה מֵאַתְרָהָא.</p>\n<p>וּלְבָתַר דְּאִשְׁתַּרַשׁ בָּהּ (נ\"א דאשתמש בהאי) אִילָנָא, וְנָחִית תַּמָּן נְבִיעוּ לְמֶעֱבַד אִיבָּא דְאִיהוּ פִּרְיָה וְרִבְיָה, דָא גָרִים אָדָם דְּאִתְבְּרֵי בְּדִיּוֹקְנֵיהּ, דְּאִסְתַּלַּק נְבִיעוּ מִשְּׁכִינְתָּא תַּתָּאָה וּמִשֶּׁבַע דַּרְגִּין דִּילָהּ, לְבָתַר דִּנְחִיתוּ תַּמָּן, כֹּלָּא סָלִיק לְאַתְרֵיהּ, וְרָזָא אִיהוּ וְקָם.</p>\n<p>וּמַאי הֲוָה נְבִיעוּ דְאִסְתַּלַּק מִנֵּיהּ, ו' דְּאִסְתַּלַּק עַד אֵין סוֹף דְּאִיהוּ מַזָּלָא עִלָּאָה, דְנָחִית לֵיהּ ו' דְּאִיהוּ אַבָּא לְאַתְרֵיהּ, וּלְבָתַר סָלִיק אַבָּא כָּל בְּרֵיהּ לְאַתְרֵיהּ. (נ\"א דנחית לון דאיהו אבא לבריה, ולבתר סליק אבא מבריה לאתריה) (כל זה מיותר) (דאיהו שעתא דקיימא ליה זכאה איהו מאן דקיימא ליה ולא דחיקא ליה שעתא כמה דאוקמוה כל הדוחק את השעה שעה דוחקתו והא רבי פדת דדחיקא ליה שעתא אמר ליה קודשא בריך הוא אי בעית דאחריב עלמא ואפשר דנפלת בשעתא דמזוני אמר ליה בוצינא קדישא כולי האי אמאי אמר ליה דא רזא רברבא שמענא דבר נש דאתי בגלגולא ואתחייב למאריה קדם דייתי לעלמא אף על גב דיעביד כמה זכוון לאו בזכותיה תליא מלתא דהא מזליה גרים ליה ומה דאמר אי בעית דאחריב לעלמא ואפשר דנפלת בשעתא דמזוני בודאי הכי שמענא דכל צדיקא וצדיקא אית ליה עולם בפני עצמו ודא גופא דבר נש דאתקרי עולם קטן ובגין דא אמר אי בעית דאחרביה לעלמא ואייתי ליה בגופא אחרא ואפשר דנפלת בשעתא דמזוני אמר ליה והא כתיב (שמות כא י) אם אחרת יקח לו שארה כסותה ועונתה לא יגרע והן כל אלה יפעל א\"ל וכו' ואם שלש אלה לא יעשה לה ויצאה חנם אין כסף (שם). אמר ליה ודאי אתגלי הכא רזא עלאה כמה דאוקמוהו מארי מתניתין אשתו כגופו דמיא ואשתכח דאיהי חיים דיליה הדא הוא דכתיב (קהלת ט ט) ראה חיים עם אשה אשר אהבת עץ חיים היא למחזיקים בה (משלי ג יח),</p>"],[9500011201,"<p>ואיהי פרנסה דיליה הדא הוא דכתיב (דברים ח ט) ארץ אשר לא במסכנות תאכל בה לחם וכו' ומינה בני חיי ומזוני ע\"כ).</p>\n<p>וְלָקֳבֵל אִלֵּין גִּלְגּוּלִין שִׁנּוּי מָקוֹם וְשִׁנּוּי הַשֵּׁם וְשִׁנּוּי מַעֲשֶׂה, שִׁנּוּי מָקוֹם כְּגַוְונָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְאִתְּמַר בֵּיהּ (ישעיה כו כא) הִנֵּה יהו\"ה יוֹצֵא מִמְּקוֹמוֹ, וְכַד נָפִיק אִשְׁתַּנִּי מִדִּינָא לְרַחֲמֵי וּמֵרַחֲמֵי לְדִינָא, כְּמָה דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין לֹא כְשֶׁאֲנִי נִכְתָּב אֲנִי נִקְרָא, בָּעוֹלָם הַבָּא דְאִיהוּ אַתְרֵיהּ נִכְתָּב בְּיהו\"ה וְנִקְרָא בְּיהו\"ה, בָּעוֹלָם הַזֶּה נִכְתָּב בְּיהו\"ה וְנִקְרָא בְּאדנ\"י, דָּא שִׁנּוּי מָקוֹם לְבָר מֵאַתְרֵיהּ, דְּאִיהוּ עָלְמָא דְאָתֵי, עָלְמָא דְאָתֵי לֵית בֵּיהּ שִׁנּוּיָא, הֲדָא הוּא דִכְתִיב (מלאכי ג ו) אֲנִי יהו\"ה לֹא שָׁנִיתִי, נִכְתָּב בְּשֵׁם יהו\"ה וְנִקְרָא בְשֵׁם יהו\"ה, אִתְקְרֵי יהו\"ה רַחֲמֵי, לְבָר מֵאַתְרֵיהּ אִשְׁתַּנִּי וְאִתְקְרֵי אדנ\"י וְאִתְקְרֵי דִין, וְדָא רָזָא עוֹמֵד מִכִּסֵּא רַחֲמִים וְיוֹשֵׁב עַל כִּסֵּא דִין.</p>\n<p>שִׁנּוּי הַשֵּׁם דָּא מצפ\"ץ, דְּאִיהוּ בְּאַ\"תְּ בַּ\"שׁ יהו\"ה, שִׁנּוּי מַעֲשֶׂה דָא שַׁבָּת, דְּצָרִיךְ כָּל כִּלְאַחַר יָד, כֹּל דְּאִיהוּ צַדִּיק, אַחַר יָד דְּאִיהִי שְׁכִינְתָּא, דָא שִׁנּוּי מַעֲשֶׂה, וּבְזִמְנָא דְאִיהוּ כִּלְאַחַר יָד לֵית תַּמָּן סְגִידוּ, דְאִתְּמַר בֵּיהּ כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, תַּעֲלָא בְעִידָּנֵיהּ סָגִיד לֵיהּ, דִּבְזִמְנָא דְאִיהוּ כִלְאַחַר יָד אִתְעֲבִיד זָנָב, וְעִם כָּל דָּא דְאָמַר תַּעֲלָא בְעִדָּנֵיהּ סָגִיד לֵיהּ בְּאַתְרֵיהּ, אֲבָל חוּץ מֵאַתְרֵיהּ הֱוִי זָנָב לַאֲרָיוֹת וְאַל תְּהִי רֹאשׁ לַשּׁוּעָלִים</p>\n<p>דְּהָא צַדִּיק גָּמוּר אַף עַל גַּב דְּנָחִית מִדַּרְגֵּיהּ וְאִתְעֲבִיד זָנָב לַאֲרָיוֹת, עֲלֵיהּ אִתְּמַר (תהלים לז כה) לֹא רָאִיתִי צַדִּיק נֶעֱזָב, מַאי זָנָב דִּילֵיהּ הַהִיא קוֹצָא דְאָת ד' מִן אֶחָ\"ד דְּאִיהִי י' זְעִירָא שְׁכִינְתָּא תַּתָּאָה, עֲלֵיהּ אִתְּמַר (משלי כד טז) כִּי שֶׁבַע יִפּוֹל צַדִּיק וָקָם.</p>\n<p>תָּא חֲזִי גִלְגּוּל דְּאָת ו' אִיהוּ דְנָפִיק בְּשַׁעִִתֵּיהּ, דַּעֲלֵיהּ אִתְּמַר מַזָּל שָׁעָה גוֹרֵם, כְּמָה דְאוּקְמוּהָ אֵין מַזָּל יוֹם גּוֹרֵם אֶלָּא מַזָּל שָׁעָה גוֹרֵם, בְּאַבְרָהָם מַה כְּתִיב בֵּיהּ כַּד אַתְיָא בְגִלְגּוּלָא, (בראשית יט כז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר אֶל הַמָּקוֹם, וּבְגִין לְאַקְדָּמָא לָהּ יִצְחָק מַה כְּתִיב בֵּיהּ בְּגִלְגּוּלָא, (שם כד סג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב, נָפַק לְגַבָּהּ לְחַקְלָא, בְּגִין דְּאִתְּמַר בֵּיהּ (ירמיה ט ט) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים, חַד אַקְדִּים לְפַשְׁפְּשָׁא בָּהּ בְּצַפְרָא, וְתִנְיָנָא לְפַשְׁפְּשָׁא בָּהּ בְּרַמְשָׁא, יַעֲקֹב מַה כְּתִיב בֵּיהּ (בראשית כה יא) וַיִּפְגַּע בַּמָּקוֹם, פָּגַע בָּהּ, זַכָּאָה אִיהוּ מָאן דְּפָגַע כְּגוֹן יַעֲקֹב, דַּעֲלֵיהּ אִתְּמַר (שם) וַיָּלֶן שָׁם, וְהַהוּא לִינָה הוּא לְוָיָה, מִיָּד דְּאַעֲרַע בָּהּ (שם לב ב) וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אלהי\"ם, וְעִם כָּל דָּא דְפָגַע בָּהּ הֲוָה נָטִיר לָהּ, וְלָא אִתְאַחַד עִמָּהּ עַד דְּאָתָא בַּעִִלָהּ, וְדָא אִיהוּ (שם כח יא) וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ, דִּבְגִינֵיהּ (שם לב לב) וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ, דְּאִיהוּ מֹשֶׁה דְאָתָא בֵיהּ בְּגִלְגּוּלָא רוּחֵיהּ דְּמֹשֶׁה, וּבְגִין דָּא יַעֲקֹב וּמֹשֶׁה הֲווֹ קַיְימֵי בְּדַרְגָּא חֲדָא בְּעַמּוּדָא דְאֶמְצָעִיתָא, אֲבָל דָּא בְגוּפָא וְדָא בְנִשְׁמָתָא, וּבְגִין דָּא לֵית שַׁעִִתָּא קַיְימָא לְכָל בַּר נַשׁ דְּאִיהִי שְׁכִינְתָּא בְלָא בַּעִִלָהּ</p>\n<p>וּבְגִין דָּא כַּד דְּחִיקַת לֵיהּ שַׁעִִתָּא לְרַבִּי פְּדָת, וְאָמַר אִי בָּעִית דְּאַחְרְבֵיהּ לְעָלְמָא וְאֶפְשַׁר דִּנְפַלְתְּ בְּשַׁעִִתָּא דִמְזוֹנֵי, וְאוּלַי דִּנְפַלְתְּ מַאי וְאוּלַי, אֶלָּא וְאוּלַי אִי בָּעִי קוּדְשָׁא בְּרִיךְ הוּא דִנְפַלְתְּ בְּשַׁעִִתָּא דִמְזוֹנֵי, דְהָא אִתְּתֵיהּ עָבִיד, וְאוּלַי אִי בָּעִי בַּעִִלָהּ דַּהֲוִי קַיְימָא מַה דְּאִיהִי עֲבִידַת בְּלָא רְשׁוּתָא דְבַעִִלָהּ.</p>\n<p>וּכְגַוְונָא דָא לֵית שַׁעִִתָּא קַיְימָא דְאִיהִי שְׁכִינְתָּא לְהַהוּא בַר נַשׁ, אֶלָּא אִם יֵיתֵי בְגִלְגּוּלָא בְהַהוּא בַר נַשׁ דְּהַהִיא שַׁעִִתָּא, וְרָזָא דְמִלָּה (ויקרא טז ג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, וּבְלָא בַעִִלָהּ אִתְּמַר (שם ב) וְאַל יָבֹא בְכָל עִת אֶל הַקֹּדֶשׁ (במדבר א נא), וְהַזָּר הַקָּרֵב יוּמָת, וְלֵית מִיתָה אֶלָּא עֲנִיּוּתָא, וְהַאי זָר לַאו בְּזָר אָחֳרָא דְמוּם זָר, אֶלָּא זָר מִבַּעִִלָהּ.</p>\n<p>זַכָּאָה מָאן דְּאִיעֲרַע בְּשַׁעִִתָּא דְאִתְבְּרִי מִשִּׁית יְמֵי בְּרֵאשִׁית, דְּכָל נִשְׁמָתָא אִית לָהּ עִת וּזְמַן בְּגִלְגּוּלָא, כְּמָה דְאָמַר קֹהֶלֶת (קהלת ג א) לַכֹּל זְמָן וְעִת לְכָל חֵפֶץ תַּחַת הַשָּׁמָיִם, וְדָא שְׁכִינְתָּא תַּתָּאָה דְאִיהִי זְמַן וְעִדָּן לְכָל סְפִירָה וּסְפִירָה, וּלְכָל גִּלְגּוּלָא וְגִלְגּוּלָא, וְאִיהִי עִדָּן וְעִדָּנִין וּפְלַג עִידָּן, עִידָן דְּכָל עִדָּנִין שַׁפִּיר, מַאי וּפְלַג עִידָּן, אֶלָּא כְּגוֹן פְּלַג הַמִּנְחָה, בִּשְׂמָאלָא אִתְפַּלְגַּת לְדִינָא, וּבִימִינָא לְרַחֲמֵי, בְעַמּוּדָא דְאֶמְצָעִיתָא אִשְׁתַּלִּימַת, וְכַד אִתְפְּלִיגַת בִּימִינָא וּשְׂמָאלָא אִתְּמַר בָּהּ לְאֶסְתֵּר (אסתר ה ג) מַה בַּקָּשָׁתֵךְ עַד חֲצִי הַמַּלְכוּת וְתֵעָשׂ, וְאִיהוּ כ\"ח יהו\"ה, פַּלְגּוּ דִילָהּ יַד יָמִין, וּפַלְגּוּ דִילָהּ יַד שְׂמֹאל, וְלָקֳבֵל תַּרְוַיְיהוּ אִדְכַּר קֹהֶלֶת בָּהּ כ\"ח זִמְנִין עִת.</p>"],[9500011202,"<p>הֲדָא הוּא דִכְתִיב (קהלת ג ב) עִת לָלֶדֶת וְעִת לָמוּת עִת לָטַעַת וכו', וְאִינוּן י\"ד י\"ד, יַד יְמִינָא רַחֲמֵי, לָלֶדֶת לָטַעַת לִרְפּוֹא לִבְנוֹת לִשְׂחוֹק לִרְקוֹד כְּנוֹס אֲבָנִים לַחֲבוֹק לְבַקֵּשׁ לִשְׁמוֹר לִתְפּוֹר לְדַבֵּר לֶאֱהוֹב שָׁלוֹם. יַד שְׂמָאלָא דִינָא לְמִדַּן, לָמוּת לַעֲקוֹר לַהֲרוֹג לִפְרוֹץ לִבְכּוֹת סְפוֹד לְהַשְׁלִיךְ אֲבָנִים לִרְחוֹק לְאַבֵּד לְהַשְׁלִיךְ לִקְרוֹעַ לַחֲשׁוֹת לִשְׂנוֹא מִלְחָמָה, יַד יְמִינָא אִיהִי פְּשׁוּטָה לְקַבֵּל שָׁבִים, דִּכְתִיב (שמות יד ח) וּבְנֵי יִשְׂרָאֵל יוֹצְאִים בְּיָד רָמָה, (שם טו ו) יְמִינְךָ יהו\"ה נֶאְדָּרִי בַּכֹּחַ, יַד יְמִינָא רַחֲמֵי. יַד שְׂמָאלָא דִינָא, דִכְתִיב (שם ט ג) הִנֵּה יַד יהו\"ה הוֹיָה, (דברים ב טו) יַד יהו\"ה הָיְתָה בָּם לְהֻמָּם.</p>\n<p>וּבְגִין דָּא אִית עִת רָצוֹן וְאִתְּמַר בָּהּ (ויקרא טז ג) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, וְאִית עִת דְּדִינָא דְאִתְּמַר בָּהּ (שם ב) וְאַל יָבֹא בְכָל עִת אֶל הַקֹּדֶשׁ, וּבְגִין דָּא אִינוּן כ\"ח יוֹמֵי דְסִיהֲרָא, י\"ד יוֹמִין אִיהִי שְׁלֵימָתָא, וְי\"ד חֲסֵרָה, וּמָאן דְּאִתְיַילִּיד בְּיוֹמֵי שְׁלֵימוּתָא אִיהוּ שְׁלִים בַּבְּנִין בְּחַיֵּי וּבְעוּתְרָא בִּמְזוֹנֵי בְּחֶדְוָה בְּשַׁלְוָה בְּבִנְיָנָא, בְכָל י\"ד עִתּוֹת טָב. וּמָאן דְּאִתְיַילִּיד בְּזִמְנָא דְאִיהִי חֲסֵרָה, בְּכָל י\"ד יוֹמִין אִלֵּין אִיהוּ חָסֵר בְּכֻלְּהוּ, אִיהוּ עַנְיָא מִסְכֵּנָא בְּלָא מְזוֹנֵי וּבְלָא חַיֵּי. וּמָאן דְּאִתְיַילִּיד בְּאֶמְצָעִיתָא יְהֵא בֵינוּנִי.</p>\n<p>וְכָל דָּא מָאן גָּרִים דְּאִתְיַילִּיד בְּרֵישָׁא אוֹ בְסוֹפָא אוֹ בְּאֶמְצָעִיתָא, דָּא גִלְגּוּל דִּילֵיהּ דִּמְחַיֵּב לֵיהּ, (ומאן גרם דא דאתייליד תמן בגין דמזליה גרים דאתחייב מלעילא) קֳדָם דְּאַתְיָיא לְעָלְמָא, וּבְגִין דָּא אָמַר לְרַבִּי פְּדָת דְּאִי בָעִי דְאַחֲרִיב לְעָלְמָא וכו', (ומאן דאתייליד בחסרונא דסיהרא בכל י\"ד יומין איהו חסר דמזליה גרים ולהאי בר נש קשין לו מזונותיו כקריעת ים סוף), (נ\"א אפשר דנפלת בשעתא דמזונא, דלהאי בר נש דאתייליד בי\"ד שמאלא קשין מזונותיו כקריעת ים סוף, דמזונא דנשמתא אורייתא, מזונא דגופא נהמא, בין בהאי ובין בהאי קשין מזונותיו), בְּגִין דְּאִינוּן מִסִּטְרָא דְּדִינָא דְאִתְבְּרֵי בְדִינָא דְאִיהוּ אדנ\"י, וּמָאן דְּאִתְבְּרִי בְּרַחֲמֵי דְאִיהוּ יהו\"ה, לַאו אִינוּן קָשִׁין מְזוֹנוֹתָיו, וּמְזוֹנָא דְנִשְׁמָתָא אוֹרַיְיתָא, מְזוֹנָא דְגוּפָא נַהֲמָא מֵחֲמֵשֶׁת הַמִּינִין.</p>\n<p>וּמָאן דְּאִיהוּ מִסִּטְרָא דְאָדָם דְּאִיהוּ יו\"ד ה\"א וא\"ו ה\"א, אִתְּמַר בֵּיהּ (בראשית א כו) וְיִרְדּוּ בִדְגַת הַיָּם וכו', בְּכֹלָּא שַׁלִּיט כְּמָה דְאִתְבְּרִי בִּשְׁמַיָּא וּבְאַרְעָא וּבְיַמָּא, וַעֲלֵיהּ אִתְּמַר (קהלת ג טו) מַה שֶּׁהָיָה כְּבָר הוּא, מַה שֶּׁהָיָה קֳדָם דְּיֵיתֵי לְהַאי עָלְמָא, כְּמָה דְאַתְּ אָמַר (שם א ט) אֵין כָּל חָדָשׁ תַּחַת הַשָּׁמֶשׁ, כְּבָר הוּא מְחוּיָיב לְמֶהֱוִי בְּהַאי עָלְמָא, כְּמָה דְאַתְּ אָמַר (ירמיה א ה) בְּטֶרֶם אֶצָּרְךָ בַבֶּטֶן יְדַעִִתִּיךָ, וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה (קהלת ג טו), וַאֲשֶׁר אִיהוּ לְמֶיהֱוִי בְּהַאי עָלְמָא, כְּבָר הוּא מְחוּיָיב לְמֶיהֱוִי קֳדָם דְּיֵיתֵי לְעָלְמָא הָכָא בְגִלְגּוּלָא.</p>\n<p>וְהָאלהי\"ם יְבַקֵּשׁ אֶת נִרְדָּף (שם), זֶה הֶבֶל דְּאִיהוּ נִרְדָף מִקַּיִן, וְקָם קַיִן וְקָטַל לֵיהּ, הֲדָא הוּא דִכְתִיב (בראשית ד ח) וַיָּקָם קַיִן אֶל הֶבֶל אָחִיו וַיַּהַרְגֵהוּ, וַיָּקָם וַדַּאי, דַּהֲוָה הֶבֶל עֲלֵיהּ, וְקָם קַיִן וַיַּהַרְגֵהוּ, קַיִן אִתְקְרֵי עַל שֵׁם דְּקַנִּי עַל אֲחוּהָ, בְּגִין דְּחָזָא יְקָרֵיהּ וְתוּקְפֵיהּ לְעִילָא, דְּקָרְבָּנֵיהּ אִסְתַּלַּק לַאֲתַר דְּעַתִּיק יוֹמִין, דְּאִתְּמַר בֵּיהּ (דניאל ז ט) וְעַתִּיק יוֹמִין יְתִיב וכו', וְקָרְבָּנֵיהּ הֲוָה מִבְּכוֹרוֹת צֹאנוֹ, וְאִתְקַבַּל לֵיהּ בְּרַעֲוָא.</p>\n<p>אָמַר לֵיהּ, אִם כֵּן דְּקָרְבָּנָא דִילֵיהּ אִתְקַבַּל, אַמַּאי אִתְיַיהִיב חֵילָא לְקַיִן לְמִקְטְלֵיהּ, (בגין דא יש הבל אשר נעשה על הארץ וגומר (קהלת ח יד) אמאי), אָמַר לֵיהּ הָכָא וַדַּאי רָזָא עִלָּאָה, דְּאִיהוּ הֲוָה דַרְגָּא דְעִץ הַדַּעַת טוֹב וָרָע דְּחָאב בֵּיהּ, וּבַמֶּה דְחָאב בֵּיהּ קַבִּיל עָנְשֵׁיהּ בְּהַאי עָלְמָא, וּבְהַהוּא קָרְבָּנָא דְאִתְקַבִּיל מִנֵּיהּ אִשְׁתֵּזִיב מֵעָנְשָׁא דְהַהוּא עָלְמָא, דִתְרֵי עָנְשֵׁי הֲוָה מְחוּיָיב חַד לְעִילָא וְחַד לְתַתָּא, הֲדָא הוּא דִכְתִיב (בראשית ב יז) כִּי בְּיוֹם אֲכָלְךָ מִמֶּנּוּ מוֹת תָּמוּת.</p>"],[9500011203,"<p>אָמַר לֵיהּ, וְהָא אָדָם הֲוָה דְחָאב בְּהַאי אִילָנָא, אָמַר לֵיהּ עוֹבָדָא דַאֲבוּהָ הֲוָה לֵיהּ וּמֵת, אָמַר לֵיהּ כִּי בְיוֹם אֲכָלְךָ מִמֶּנּוּ כְּתִיב, אָמַר לֵיהּ בְּהַהוּא יוֹם הִצִּיץ וּמֵת.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן בְּגִין דָּא כְּתִיב (קהלת ח יד) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים שֶׁמַּגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים וְגוֹמֵר, וְהָכָא אִתְרְמִיז צַדִּיק וְרַע לוֹ רָשָׁע וְטוֹב לוֹ, צַדִּיק וְרַע לוֹ הָכָא אִתְרְמִיז, יֵשׁ צַדִּיקִים שֶׁמַּגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, וְדָא רָזָא דְצַדִּיק דְּאַעִִרַע לֵיהּ כְּמַעֲשֵׂה הָרְשָׁעִים, לַאו דְּאִיהוּ רָשָׁע וְלַאו בֶּן רָשָׁע אֶלָּא כְּמַעֲשֵׂה הָרְשָׁעִים דְּחָב בְּעוֹבָדָא דְחַיָּיבַיָּא, דְאִינוּן סמא\"ל וְנָחָשׁ, אִירַע לֵיהּ עוֹבָדָא דִלְהוֹן, וְהַאי אִיהוּ רָזָא פּוֹקֵד עֲוֹן אָבוֹת עַל בָּנִים (שמות כ ה), בְּגִין דְּמַעֲשֵׂה אֲבוֹתֵיהֶם בִּידֵיהֶם, דָּא גְרִים לְהֶבֶל מִיתָה, וּמֵת בְּלָא בֵן, וּבְגִין דָּא אָזִיל בְּגִלְגּוּלָא, שִׁי\"ן דְּמֹשֶׁה אִיהוּ שֵׁ\"ת מִתַּמָּן רָוַוח שִׁי\"ן (ס\"א ש\"ת), הֲדָא הוּא דִכְתִיב (בראשית ד כה) כִּי שָׁת לִי אלהי\"ם זֶרַע אַחֵר תַּחַת הֶבֶל כִּי הֲרָגוֹ קָיִן, תַּחַת הֶבֶל וַדַּאי, דְּהֶבֶל רָכִיב עֲלֵיהּ, וְאִתְעֲבִיד שֵׁת הַרְכָּבָה לֵיהּ, וְאִיהִי סִיּוּמָא דְאַלְפָא בֵּיתָא, וּבְגִין דָּא תַּחַת הֶבֶל.</p>\n<p>הֶבֶל הַלֵּב, וַעֲלֵיהּ אִתְּמַר הַלֵּב רוֹאֶה, וְאִיהוּ ה' מִמֹּשֶׁה, וְהַלֵּב אִיהוּ לִשְׂמָאלָא דְאִיהוּ אלהי\"ם, הַלֵּב מֵבִין, וְאִיהוּ סָתִיר בִּנְיָינָא וְנָפְלַת בְּגִינֵיהּ, וּבְגִין דָּא וַיַּסְתֵּר מֹשֶׁה פָּנָיו כִּי יָרֵא מֵהַבִּיט אֶל הָאלהי\"ם (שמות ג ו), בְּגִין דְּתַמָּן הַוָּה דְחָב בֵּאלֹהִי\"ם, דְּאִיהוּ אלהי\"ם דְּעוֹבָדָא דִבְּרֵאשִׁית, וְדָא אִיהוּ דְחָב בְּמַעֲשֶׂה, לַבַּת אֵשׁ בְּרַתָּא דְמַלְכָּא דְחָב בֵּיהּ, וְאִתְבַּיַּישׁ כַּסִּי לֵיהּ בְּדִילֵיהּ (ס\"א בחיליה) בְּשֵׁת, וּמַה דַהֲוָה שֵׁת אִתְחַבֵּר עִמֵּיהּ ב' וְאִתְעֲבִיד בֹּשֶׁת, וְדָא אִיהוּ יְרָ\"א בֹּשֶׁ\"ת, וְעוֹד שֵׁת בְּאַ\"תְּ בַּ\"שׁ אִינוּן אָב, שֵׁ\"ת לְבָתַר דְּזָכָה בְּאָת יוּ\"ד, בְּרֵא שִׁית, וְאִיהִי יוּ\"ד דְּאִתְּמַר בֵּיהּ (משלי ח כה) יהו\"ה קָנָנִי רֵאשִׁית דַּרְכּוֹ, דְּאִיהִי עֲשָׂרָה דוֹרוֹת, וְתָב לָהּ לְאַתְרָהּ, אִתְקְרִי בְּרֵאשִׁית, וּמִתַּמָּן זָכָה לְאוֹרַיְיתָא דְאִתְיְיהִיבַת עַל יְדֵיהּ.</p>\n<p>וְהַאי י' אִיהִי מִיַּעֲקֹב וְי' מִיִּשְׂרָאֵל, י' מֵאדנ\"י י' מִיהו\"ה, שִׁי\"ן מִמֹּשֶׁה אִיהִי מִשֵּׁת תַּמָּן רָוַוח לָהּ, וְכַד אָזַל לְשֵׁם רָוַוח תַּמָּן תְּרֵין אַתְוָון שֵׁ\"ם, וְכַד אָזַל עֲשָׂרָה דוֹרוֹת עַד אַבְרָהָם תַּמָּן רָוַוח ה' דִּילֵיהּ, וְאִתְקְרִי מֹשֶׁ\"ה, וְרָזָא דְמִלָּה מוֹלִיךְ לִימִין מֹשֶׁה זְרוֹעַ תִּפְאַרְתּוֹ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם לַעֲשׂוֹת לוֹ שֵׁם עוֹלָם (ישעיה סג יב), וּבָהּ אַפִּיק לִבְנוֹי מִגָּלוּתָא, וּבָהּ מָחָא לְמִצְרָאֵי, הֲדָא הוּא דִכְתִיב (שמות ט ג) הִנֵּה יַד יהו\"ה הוֹיָה, ה' חָמֵשׁ אֶצְבָּעִין, וּבָהּ בָּקַע יַמָּא, וְדָא אִיהוּ בּוֹקֵעַ מַיִם מִפְּנֵיהֶם, וּבָהּ עָתִיד לְמֶהֱוִי בוֹקֵעַ יַמָּא דְאוֹרַיְיתָא מִימִינָא, הַהוּא זִמְנָא מַה דַּהֲוָה לִשְׂמָאלָא בְּלִבָּא הֲוָה הֶבֶל דְּאִיהוּ הַלֵּב, הֶבֶל אִסְתַּלַּק לִימִינָא, וּמִתַּמָּן סָלִיק לְמוֹחָא דְּאִיהוּ חָכְמָה, דְּהָא לִבָּא אִיהוּ אִימָּא עִלָּאָה, עֲלָהּ אִתְּמַר הַלֵּב מֵבִין, וּלְבָתַר נָחִית עַל אַרְעָא לְנַחְתָא אוֹרַיְיתָא עַל אַרְעָא.</p>\n<p>וּבְגִין דָּא יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ אֲשֶׁר יֵשׁ צַדִּיקִים אֲשֶׁר מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, דָּא אָדָם וְהֶבֶל, דְּדָא חָב בְּמַחֲשָׁבָה וּבְעוֹבָדָא, וְדָא חָאב בְּמַחֲשָׁבָה וּבְעוֹבָדָא, בְּמַחֲשָׁבָה אִיהִי י', עֲלֵיהּ אִתְּמַר (במדבר יד כב) וַיְנַסּוּ אוֹתִי זֶה עִִשֶׂר פְּעָמִים, וּבְגִין דָּא כַּד אָתָא אָדָם בְּגִלְגּוּל בְּאַבְרָהָם, אִתְנַסִּי בֵּיהּ בְּעִִשֶׂר נִסְיוֹנִין, וּבְגִין דְּחָאב בְּמַעֲשֶׂה כַּד אִתְגַּלְגַּל בְּיִצְחָק נִתְנַסָּה בְּמַעֲשֶׂה, בְּאַבְרָהָם נִתְנַסָּה בְּמַחֲשָׁבָה, וּבְיִצְחָק בְּמַעֲשֶׂה, יַעֲקֹב כְּלִיל תַּרְוַיְיהוּ, מִסִּטְרָא דְיִצְחָק קָרָא לֵיהּ יַעֲקֹב, מִסִּטְרָא דְאַבְרָהָם דְּתַמָּן מַחֲשָׁבָה קְרָא לֵיהּ יִשְׂרָאֵל, דְּאַבָּא אִתְגַּלְגַּל בְּאַבְרָהָם דְּאִיהוּ לִימִינָא, וְאִמָּא בְיִצְחָק דְּאִיהוּ לִשְׂמָאלָא, יַעֲקֹב בְּגִין דְּאִיהוּ כְּלִיל תַּרְוַיְהוּ אַבָּא וְאִמָּא, אִתְּמַר בֵּיהּ יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה בְּכֶתֶר עִִלְיוֹן דְּאִיהוּ מַחֲשָׁבָה סְתִימָא, וְכַד אָתָא אָדָם אִצְטַרַף בְּאַבְרָהָם, וְאִתְפַּשְׁטוּ שָׁרְשׁוֹי בְּאַרְעָא, וְרָזָא דְמִלָּה (משלי יז) מַצְרֵף לַכֶּסֶף וְכוּר לַזָּהָב (משלי יז ג), מַצְרֵף לַכֶּסֶף דָּא אַבְרָהָם, וְכוּר לַזָּהָב</p>"],[9500011204,"<p>דָּא יִצְחָק, וּבוֹחֵן לִבּוֹת יהו\"ה (שם) דָּא יַעֲקֹב, לֵית סְפִירָה דְלָא אִתְגַּלְגַּל אָדָם עִלָּאָה, דְאִיהוּ יו\"ד ה\"א וא\"ו ה\"א, כֹּ\"חַ מָ\"ה חָכְמָה וַדַּאי, בְּגִין לְצָרְפָא וּלְלַבְּנָא לְאָדָם דְּבָרָא בְדִיּוֹקְנֵיהּ לְתַתָּא, וְאָצִיל בֵּיהּ אֲצִילוּתֵיהּ, וְכָל טָרְחָא דִלְעִילָא לָא הֲוָה בְּאָדָם אֶלָּא בְגִין אֲצִילוּת דְּאָדָם דִּלְעִילָא, דְּדָא בְּדָא תַּלְיָא.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר אִם כֵּן מַאי וְיָשׁוּב לִימֵי עֲלוּמָיו (איוב לג כה) (ובגין דא ישראל עלה במחשבה, אמר ליה מנלן דאברהם תמן במחשבה, אמר ליה לאו למגנא תקינו מארי מתניתין הרוצה להחכים ידרים דאיהי חכמה ואיהי מחשבה, באברהם אתלבן אדם, וביצחק אצטריף, ורזא דמלה מצרף לכסף וכור לזהב, מצרף לכסף דא אברהם, וכור לזהב דא יצחק, ובוחן לבות יהו\"ה דא יעקב, והן כל אלה יפעל א\"ל פעמים שלש עם גבר (שם כט), אמר ליה אם כן מאי וישוב לימי עלומיו).</p>\n<p>אָמַר לֵיהּ לְאִילָנָא דַהֲוָה קַשִּׁישׁ יוֹמִין וְאִתְיַיבְּשׁוּ עַנְפִין דִּילֵיהּ, קַצִּיצוּ לֵיהּ וְאַצְמַח בְּשָׁרְשׁוֹי, דְּקָמוּ מִנֵּיהּ עַנְפִין חַדְתִּין כְּקַדְמֵיתָא, כְּגַוְונָא דַהֲוָה בְּעוּלֵמוֹי, וְדָא אִיהוּ וְיָשׁוּב לִימֵי עֲלוּמָיו, וְדָא הֲוָה חֶלְמָא דְחָזָא נְבוּכַדְנֶצַּר בְּחֶלְמֵיהּ, אִילָנָא רְבָא וּתְקִיף (דניאל ד ט), וּבַסּוֹף חֶלְמֵיהּ הֲוָה אָמַר (שם יא) גֹּדּוּ אִילָנָא וְקַצִּיצוּ עַנְפוֹהִי, וּלְבָתַר אָמַר (שם יב) בְּרַם עִקַּר שָׁרְשׁוֹהִי בְּאַרְעָא שְׁבוּקוּ, וְלֵית אִילָן הָכָא אֶלָּא אָדָם עִלָּאָה, דְאִתְּמַר בֵּיהּ (דברים כ יט) כִּי הָאָדָם עִץ הַשָּׂדֶה, וְהַאי אִילָנָא קוּדְשָׁא בְּרִיךְ הוּא אַנְטַע לֵיהּ בְּכַמָּה דָרִין וְלָא אַצְלַח. עַד דְּנָטַע לֵיהּ בְּאַרְעָא דְיִשְׂרָאֵל, וְאַרְכִּיב לֵיהּ בִּתְלַת אֲבָהָן וְאַצְלַח תַּמָּן, וּבְגִין דָּא הֶן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר, מִיָּד דְּאַצְלַח תַּמָּן וַאֲחִיד תַּמָּן, אִתְפַּשְׁטוּ שָׁרְשׁוֹי עַל אַרְעָא דְאִיהִי שְׁכִינְתָּא, וְאִסְתַּלְקוּ עַנְפּוֹי בְּכָל רְקִיעִין, וּבְכָל מַרְכְבִין דְּנִשְׁמָתִין וּמַלְאָכַיָּא וְחֵיוָון וּשְׂרָפִים וְאוֹפַנִּים, עַד דְּאִתְחַזַּר כְּקַדְמֵיתָא (ס\"א עד אין סוף), וְהָא אוּקְמוּהָ עֵץ הַחַיִּים מַהֲלֵךְ ת\"ק שָׁנָה, (דניאל ד ט) רְבָא אִילָנָא וּתְקִיף וְרוּמֵיהּ יִמְטֵי לִשְׁמַיָּא, וַחֲזוֹתֵיהּ לְסוֹף כָּל אַרְעָא, תְּחוֹתוֹהִי תַּטְלֵל כָּל חֵיוַת בָּרָא, וּבְעַנְפוֹי יְדוּרוֹן צִפֲּרֵי שְׁמַיָּא, דְאִינוּן נִשְׁמָתִין קַדִּישִׁין, וּמִנֵּיהּ יִתְּזִן כָּל בִּשְׂרָא.</p>\n<p>וְאַרְכִּיב לֵיהּ עַד אֶלֶף דּוֹר, כְּגַוְונָא דִשְׁכִינְתָּא דְאִיהִי סְלִיקַת לְאֶלֶף דּוֹר בַּעֲשַׂר סְפִירָן, דִּבְהוֹן סְלִיקָא עֲשַׂר זִמְנִין מְאָה, עַד דִּסְלִיקַת בְּהוֹן לְאֶלֶף דּוֹר, וּמִיָּד דְּאַצְלַח אִילָנָא בְאַרְעָא נָחִית אִילָנָא מִלְּעִילָא, שָׁרְשׁוֹי בְּאַרְעָא דְאִיהִי שְׁכִינְתָּא, וְאִתְרַבִּיאוּ תַּמָּן עַנְפּוֹי עַד אֵין סוֹף, וְאִתְפַּשְׁטוּ בָּהּ שָׁרְשׁוֹי עַד אֵין תַּכְלִית, בְּהַהוּא זִמְנָא אִתְרַבִּי אִילָנָא כְּמִלְּקַדְמִין, הֲדָא הוּא דִכְתִיב רְבָא אִילָנָא וּתְקִיף וְרוּמֵיהּ מָטֵי לִשְׁמַיָּא, וַחֲזוֹתֵיהּ לְסוֹף כָּל אַרְעָא, וּמִנֵּיהּ יִתְּזִן כָּל בִּשְׂרָא, כָּל בְּנֵי אָדָם דִּלְתַתָּא, בְּהַהוּא זִמְנָא אִתְרַבִּי אִילָנָא כְּמִלְּקַדְמִין, הֲדָא הוּא דִכְתִיב רְבָא אִילָנָא וּתְקִיף וכו', חֵיוַת בָּרָא אִלֵּין חַיּוֹת הַקֹּדֶשׁ, צִפֲּרֵי שְׁמַיָּא אִלֵּין נִשְׁמָתִין, וּמִנֵּיהּ יִתְּזִן כָּל בִּשְׂרָא לְתַתָּא. דִּבְזִמְנָא דְחָב אָדָם וַהֲוָה מְקַצֵּץ בַּנְּטִיעוֹת, כַּבְיָכוֹל כְּאִלּוּ אַעִִקַר חֵיוָן וּמַלְאָכִים וּשְׂרָפִים וְאוֹפַנִּים מֵאַתְרֵיהוֹן, וְלָא הֲוָה מָאן דִּמְקַבֵּל צְלוֹתִין, דְּאִתְּמַר בְּהוֹן (קהלת י כ) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל, וּבַעַל הַכְּנָפַיִם יַגִּיד דָּבָר, מַאי יַגִּיד דָּבָר, בִּצְלוֹתִין וְזַכְוָון דְּיִשְׂרָאֵל.</p>\n<p>אָמַר לֵיהּ רַבִּי אֶלְעָזָר, בְּוַדַּאי עִלָּאִין וְתַתָּאִין הֲווֹ תַּלְיָין בְּאָדָם קַדְמָאָה, וְלַאו לְמַגָּנָא אוּקְמוּהָ מָארֵי מַתְנִיתִין, לְעוֹלָם יִרְאֶה הָאָדָם עַל עַצְמוֹ כְּאִלּוּ כָּל הָעוֹלָם תָּלוּי עָלָיו, אֲבָל בַּר נַשׁ דְּטָרַח עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְגִלְגּוּלָא וְלָא אַצְלַח בְּאַתְרֵיהּ, אַעִִקַר לֵיהּ מֵאַתְרֵיהּ וְשַׁוִּי לֵיהּ בַּאֲתַר אָחֳרָא, וְשַׁנִּי לֵיהּ אֲתַר, וְרָזָא דְמִלָּה</p>"],[9500011205,"<p>וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת (ויקרא יד מה), וְדָא שִׁנּוּי מָקוֹם, (כאן חסר והוא בתיקוני ז\"ח) אִם אַצְלַח מוּטָב, וְאִם לָא אַצְלַח אַעִִקַר לֵיהּ מִתַּמָּן וְאַרְכִּיב לֵיהּ בַּאֲתַר אָחֳרָא, וְשַׁנִּי שְׁמֵיהּ וְדָא שִׁנּוּי הַשֵּׁם, אִם אַצְלַח מוּטָב וְאִי לָא אַצְלַח אַעִִקַר לֵיהּ מִתַּמָּן, וְדָא וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עִצָיו (שם מח ז), וְנָטַע לֵיהּ בַּאֲתַר אָחֳרָא, וְשַׁנִּי עוֹבָדוֹי מִכָּל מַה דַּהֲוָה בְּקַדְמֵיתָא, וּמִכָּל צִיּוּרִין דִּילֵיהּ, מְשַׁנֶּה פָנָיו וַתְּשַׁלְּחֵהוּ (איוב יד כ).</p>\n<p>הֵן כָּל אֵלֶּה יִפְעַל אֵ\"ל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר (שם לג כט), קַרְקַע דְּנָטַע לֵיהּ תַּמָּן וְאַצְלַח וּמִתְפַּשֵּׁט עַנְפּוֹי וְשָׁרְשׁוֹי עַד אֶלֶף דּוֹר דָּא שְׁכִינְתָּא, וְדָא שִׁנּוּי מַעֲשֶׂה, וְעַד כַּמָּה זִמְנִין עַד אֶלֶף, כְּמָה דְאַתְּ אָמַר (תהלים קה ח) דָּבָר צִוָּה לְאֶלֶף דּוֹר, וַעֲלֵיהּ אִתְּמַר (שיר ח יב) הָאֶלֶף לְךָ שְׁלֹמֹה, וְאִינוּן אֶלֶף עָלְמִין, דְּנָטַע לֵיהּ עַד דְּאַצְלַח וְאַרְכִּיב לֵיהּ תַּמָּן, וְרָזָא דְמִלָּה וְעֹשֶׂה חֶסֶד לַאֲלָפִים (שמות כ ו), לְמָאן לְאֹהֲבָיו, וּלְשֹׁמְרֵי מִצְוֹתָיו לְאֶלֶף דּוֹר (דברים ז ט).</p>\n<p>אָמַר לֵיהּ, וּלְרַשִּׁיעַיָּא מַאי, דְּהָא כְּתִיב (קהלת א י) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וָבָאוּ וכו', מַה תֵּימָא בְּהוֹן, אָמַר לֵיהּ שְׁמַעִִנָא בְהוֹן רָזָא יִפּוֹל מִצִּדְּךָ אֶלֶף וְגוֹמֵר (תהלים צא ז), הָכִי אָמְרוּ לִי בִרְמִיזָא, אָמַר לֵיהּ אִי הָכִי מַאי אֲשֶׁר קוּמְטוּ בְלֹא עִת וְגוֹמֵר (איוב כב טז), אָמַר לֵיהּ אִלֵּין תְּשַׁע מֵאָה וְשִׁבְעִים וְאַרְבָּעָה דָרִין דְּאִתְקַמְטוּ וְאִסְתַּלְקוּ קֳדָם זִמְנַיְיהוּ, וְדָא אִיהוּ אֲשֶׁר קוּמְטוּ בְלֹא עִת, דְּאִסְתַּלְקוּ קֳדָם זִמְנַיְיהוּ, וְזָרִיק לוֹן קוּדְשָׁא בְּרִיךְ הוּא עַל כָּל דָּרָא וְדָרָא, דָא אִיהוּ נָהָר יוּצַק יְסוֹדָם (שם), וְדָא הוּא רָזָא, דְאֵין בֶּן דָּוִד בָּא עַד שֶׁיִּכְלוּ כָּל הַנְּשָׁמוֹת שֶׁבַּגּוּף, וּכְדֵין חַדְתִּין עֲתִידִין לְמֵיתֵי, אַדְהָכִי אִסְתַּלַּק סָבָא, אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּא, חַבְרַיָּיא, וַדַּאי הַאי סָבָא דְסָבִין אָדָם עִלָּאָה, זַכָּאָה דָרָא דְהַאי רָזָא אִתְגַּלְיָיא בֵּיהּ.</p>\n<p>(נוסח אחר וזה לשונו והוא מכתב יד)</p>\n<p>עוּבְדָא הֲוָה, דְחַד בַּר נַשׁ חִגֵּר בְּלָא רַגְלִין, אַשְׁכַּח לִתְרֵין חַכִּימִין דְּלָא הַוִי בְּכָל דָּרָא חַכִּימִין כַּוָּותַיְיהוּ, אַעֲרַע בְּהוּ הַהוּא חִגֵּר, אָמַר לוֹן שְׁלָמָא עֲלַיְיכוּ רַבָּנָן, (שמענא עלייכו דאתון חכימי דרא), אָנָה אַתּוּן אָזְלִין, אָמְרוּ לֵיהּ לְדוּךְ פְּלַן, וְעֶרֶב שַׁבָּת הֲוָה, אָמַר לוֹן אַף עַל גַּב דְּאַתּוּן רְכִיבִין בִּבְעִירִין דִּרָהֲטֵי סַגִּי וַאֲנָא חִגֵּר בְּלָא רַגְלִין, אִי אַתּוּן בְּעִיתוּ אֲנָא אֲקַדֵּם לְכוּ לְתַקָּנָא לְכוּ שַׁבַּתָּא, תְּוַוהוּ אָמְרוּ לֵיהּ וְהַלֹא אַתְּ חִגֵּר וְאֵיךְ אַתְּ יָכִיל לְאַקְדָּמָא לִבְעִירָן דִּרָהֲטֵי טוּבָא, אָמַר לוֹן שְׁמָא דְמ\"ב אַתְוָון וְדָלִיג לוֹן ת\"ק פַּרְסֵי בְּרִגְעָא חֲדָא.</p>\n<p>אַשְׁכְּחוּ גַרְמַיְיהוּ לְפוּם מְעַרְתָּא חֲדָא, וּפְתוֹרָא לִשְׂמָאלָא, בְּכָל מַעֲדַנֵּי עָלְמָא עֲלָהָא, וּמְנַרְתָּא לְדָרוֹם בְּשִׁבְעָה נֵרִין עֲלָהָא, וּמִטָה דְכַסְפָּא וְדַהֲבָא וְאַבְנִין יַקִּירִין לְמַעֲרָב בֵּין צָפוֹן לְדָרוֹם, וְכָרְסַיָּיא לְמִזְרָח, וּתְלַת מְאָה תַלְמִידִין עַל הַהוּא פְתוֹרָא, בָּתַר דְאָכְלוּ כֻלְּהוּ וְאִינוּן חַכִּימֵי עִמְּהוֹן, קָם הַהוּא חִגֵּר וּפָשַׁט גַּרְמֵיהּ מֵהַהוּא גוּפָא בְּלָא רַגְלִין, וְאִתְלַבֵּשׁ בְּגוּפָא דְאַנְפּוֹי זְהִירִין כְּזוֹהֲרָא דְאִתְּמַר בֵּיהּ (דניאל יב ג) וְהַמַּשְׂכִּילִים יַזְהִירוּ וכו', וְאַנְפֵּי תַלְמִידוֹי נְהִירִין כְּכֹכָבִים לְעוֹלָם וָעֶד, וַהֲווֹ פָּתְחִין סִפְרָא דְקֹהֶלֶת, וְקָרְיָין בֵּיהּ (קהלת א ב) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת כו', וַהֲווֹ חָזְרִין כַּמָּה זִמְנִין, אָמְרוּ לֵיהּ אִינוּן חַכִּימֵי דָרָא וְכִי שְׁלֹמֹה לָא עָבַד קְרָא אָחֳרָא בְּקֹהֶלֶת, עָל לְהוּ הַהוּא דְאִתְחֲזֵי חִגֵּר בְּאָרְחָא, לְשִׁבְעָה הֵיכָלִין מִכַּסְפָּא וְדַהֲבָא וְאַבְנִין יַקִּירִין, וּבְהֵיכָלָא שִׁבְעָה כָּרְסַיָּין דְּאַרְבַּע חֵיוָון, וְיוֹנָה תַמָּן דְּכַסְפָּא וַעֲטָרָה דְּדַהֲבָא עַל רֵישָׁה, וְכָתוּב בָּהּ כָּל מָאן דְּלָא יָדַע בְּאִלֵּין הֲבָלִים עֲלֵיהּ כְּתִיב (במדבר א נא) וְהַזָּר הַקָּרֵב יוּמָת, אִינוּן חַכִּימֵי דָרָא מִיָּד דְּחָזוּ הָכִי דַהֲוָה כְתִיב בְּהַהִיא עֲטָרָה חָזְרוּ לַאֲחוֹרָא. אָמַר לוֹן הַהוּא דְאִתְחֲזֵי עֲלַיְיהוּ כְּחִגֵּר, וְכִי עֲלַיְיכוּ אִתְּמַר דְּאַתּוּן חַכִּימֵי דָרָא, לֵית אַתּוּן אֶלָּא טִפְּשֵׁי דָרָא, וְלָא חֲזֵיתוּן בְּכָל לְמוֹדַיְיכוּ כִּי בִי חָשַׁק (תהלים צא יד) עַד אוֹרֶךְ יָמִים אַשְׂבִּיעֵהוּ לְעָלְמָא דְכֹלָּא אֲרִיךְ, אִלֵּין הֲבָלִים דְּקֹהֶלֶת אִינוּן בְּרָזָא דְשֶׁבַע שְׁמָהָן, דִּבְהוּ מ\"ב אַתְוָון, לָקֳבֵל שִׁבְעָה יוֹמֵי בְרֵאשִׁית דְּאִית בְּהוּ עֲשַׂר אֲמִירָן וְל\"ב אלהי\"ם וְאִינוּן מ\"ב, וַעֲלַיְיהוּ לֵב דְּאִתְּמַר בְּהוּ אלהי\"ם הָאלהי\"ם, וְהַיְינוּ (קהלת ה ז) וּגְבוֹהִים עֲלֵיהֶם, אִלֵּין שֶׁבַע תֵּיבִין אבגית\"ץ, עֲלַיְיהוּ אִתְּמַר (ישעיה ו ב) שְׂרָפִים וְגוֹמֵר. וְהַאי שְׁמָא אִיהוּ סְגוּלְתָּא דִילֵיהּ לְכַסָּאָה דְנִשְׁמָתָא כַּד סְלִיקַת לְעֵילָא בְּכָל לֵילְיָא, לְאִסְהַדָּא עַל עוֹבְדִין טָבִין דְּבַר נַשׁ, מִמַּלְאֲכֵי חַבָּלָה וּמִכָּל מַזִּיקִין וְרוּחִין וְלִילִין וְשֵׁדִין, וּבְהוֹן פָּרְחַת לְעֵילָא, בִּתְרֵין אַתְוָון מִכָּל שֵׁם תְּכַסֶּה אַנְפָּהָא מִנְּהוֹן, וּבִתְרֵין אַתְוָון תְּכַסֶּה רַגְלָהָא, וּבִתְרֵין אַתְוָון פָּרְחַת לְעֵילָא, וְאוּף הָכִי לְרוּחָא, וְאוּף הָכִי לְנַפְשָׁא, וְאִית שֵׁם בֵּן מ\"ב בְּצוּרַת חוֹתָמָא דְשַׁעֲוָה נִכְתַּב, וְאִית שֵׁם מ\"ב בְּצִיּוּר דִּיּוֹקְנָא דְמַלְכָּא, חָקִיק עַל חוֹתָמָא, וְאִית שֵׁם מ\"ב דְּאִיהוּ דִיּוֹקְנֵיהּ מַמָּשׁ, שֵׁם מ\"ב דְּאִיהוּ דִיּוֹקְנֵיהּ אִיהוּ יהו\"ה, יו\"ד ה\"א וא\"ו ה\"א, יו\"ד וא\"ו דל\"ת, ה\"א אל\"ף, וא\"ו אל\"ף וא\"ו, ה\"א אל\"ף, שֵׁם מ\"ב דְּאִיהוּ חוֹתָמָא, אִיהוּ אהי\"ה אֲשֶׁר אהי\"ה, צִיּוּר מ\"ב בְּשַׁעֲוָה דָא אבגית\"ץ.</p>\n<p>וְרַשִּׁיעַיָּא נִשְׁמָתְהוֹן דְּשֵׁדִין וּמִמַּזִּיקִין וְלָא פוֹעֲלִין בְּהוֹן אֶלָּא כִישׁוּף וְעוֹבְדֵי שֵׁדִין כַּוָּתַיְיהוּ, בְּגִין דְּרַשִּׁיעַיָּא כָּל שְׁמָהָן וְכָל הֲוַיָּי\"ן דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל מַלְאָכִים שֹׂנְאִין לוֹן, וּבְגִין כַּךְ לָא מוֹעִיל לָא קָמִיעַ וְלָא שְׁמָהָן קַדִּישִׁין וְלָא מַלְאָכַיָּא, דְלָא תָּפִיס אֶלָּא מִין בְּמִינוֹ, וּבְגִין דָּא (דברים כב ט) לֹא תִזְרַע כַּרְמְךָ כִּלְאָיִם, דְּאִתְּמַר בְּהוֹן (ישעיה ה ז) כִּי כֶרֶם יהו\"ה צְבָאוֹ\"ת וְגוֹמֵר, צְבָאוֹ\"ת נְקוּדָה דִילֵיהּ יְהָוֹ\"ה, עֲלֵיהּ אִתְּמַר (דברים י טו) רַק בַּאֲבוֹתֶיךָ חָשַׁ\"ק, חוֹלֵ\"ם שְׁבָ\"א קָמֵ\"ץ, וְאִינוּן זְרַע אַבְרָהָם יִצְחָק וְיַעֲקֹב, דַּרְגָּא דִלְהוֹן חֶסֶד כַּהֲנָא רַבָּא, גְבוּרָה לֵוִי, יִשְׂרָאֵל עַמּוּדָא דְאֶמְצָעִיתָא, בְּגִין דְּחוֹלֵ\"ם כֶּתֶר עַל תִּפְאֶרֶת, קָמֵץ חָכְמָה עַל חֶסֶד, וּבֵיהּ הָרוֹצֶה לְהַחְכִּים יַדְרִים, וּבְחָכְמָה אַשְׁרֵי הַמְחַכֶּה לִתְחִיַּית הַמֵּתִים, חָכְמָה מְחַכֶּ\"ה קָמוּ כֻלְּהוּ וְאִשְׁתַּטְחוּ קַמֵּיהּ וכו'.</p>\n<p>פָּתַח כְּמִלְּקַדְמִין וְאָמַר, (קהלת ח יד) יֵשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ וכו', תָּא חֲזִי שְׁמַענָא דְעוּבְדָא הֲוָה בְּחַד בַּר נַשׁ מֵאִינוּן בַּעֲלֵי קַבִּין, דַּהֲוָה אָזִיל בְּאָרְחָא, אַעִִרַע בִּתְּרֵין חַכִּימִין מָארֵי דְּדָרָא מָארֵי דְחָכְמָתָא דְאוֹרַיְיתָא, אָמַר לוֹן שְׁלָמָא עֲלַיְיכוּ רַבָּנָן, שְׁמַעִִנָא עֲלַיְיכוּ דְאַתּוּן חַכִּימֵי דָרָא, לְאָן אֲתַר אֲזֵילְתּוּן, אָמְרוּ לֵיהּ לְדוּךְ פְּלַן וְעִִרֶב שַׁבָּת הֲוָה, אָמַר לוֹן אֲנָא אֲזֵילְנָא תַמָּן (איזיל) וְאַתְקֵין לְכוּ אֲתַר בֵּי מוֹתְבַיְכוּ, אִי אַתּוּן בְּעִיתוּן, אָמְרוּ לֵיהּ וְהָא אֲנַן בְּסוּסְוָון וְאַנְתְּ בְּלָא רַגְלִין, אֵיךְ יִתָּכֵן לְמֶהֱוֵי הַאי, אָמַר לוֹן אַף עַל גַּב דְּאַתּוּן רְכִיבִין בִּבְעִירֵי דִרְהִיטֵי סַגִּי, וַאֲנָא חִגֵּר בְּלָא רַגְלִין, אִי אַתּוּן בְּעִיתוּ אֲנָא אֲקַדֵּם לְתַקָּנָא לְכוּ שַׁבַּתָּא, תְּוָוהוּ, אַדְהָכִי אַחְזַרוּ רֵישַׁיְיהוּ לְגַבֵּיהּ וְחָמוּ לֵיהּ</p>"],[9500011206,"<p>דַּהֲוָה רְהִיט כְּשַׁרְבִיטָא דְכֹכָבָא, עָבַד לוֹן קְפִיצָה וְאַשְׁכְּחוּ גַרְמַיְיהוּ לְפוּם מְעַרְתָּא כְּהֶרֶף עַיִן (ס\"א, אמר לון שמא דמ\"ב אתוון, דליג לון חמש מאה פרסי ברגעא חדא, אשכחו כו').</p>\n<p>אָמַר לוֹן רַבָּנָן עוּלוּ, עָאלוּ אַבַּתְרֵיהּ מְעַרְתָּא גוֹ מְעַרְתָּא, עַד דְּעָאלוּ לְחַד פַּרְדֵּסָא וַהֲוָה תַּמָּן הַהוּא בַּעַל קַבִּין מִתְפַּשֵּׁט מֵהַהוּא גוּפָא, וַהֲוָה מִתְלַבֵּשׁ בְּגוּפָא אָחֳרָא דְּאַנְפּוֹי הֲווֹ נַהֲרִין כְּשִׁמְשָׁא, וַהֲוָה יָתִיב עַל כָּרְסַיָּיא דְמַלְכוּתָא, וּתְלַת מְאָה תַלְמִידוֹי תְּחוֹת כָּרְסַיָּיא לְרַגְלוֹי, וַהֲווֹ קָרָאן (קהלת א ב) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת, וַהֲווֹ קָרָאן הַאי קְרָא זִמְנִין בְּלָא חוּשְׁבָּנָא, אָמְרוּ לוֹן אִינוּן חַכִּימִין מָארֵי דְּדָרָא, מַאי הַאי, וְכִי לֵית קְרָא אָחֳרָא בְּסֵפֶר קֹהֶלֶת, מִיָּד קָם הַהוּא מָארֵי קַבִּין דַּהֲוָה יָתִיב עַל כָּרְסַיָּיא, וַאֲחִיד בִּידֵיהוֹן, וְאַעִיל לוֹן לְשִׁבְעָה הֵיכָלִין, וּבְכָל הֵיכָלָא וְהֵיכָלָא הֲוָה כְּתִיב הֲבֵל הֲבָלִים, וּבְהֵיכָלָא שְׁבִיעָאָה הֲוָה נִשְׁרָא וַעֲטָרָה בְּפוּמָהָא, וּדְמוּת יוֹנָה בְּהַהִיא עֲטָרָה, וַהֲוָה כְּתִיב בַּעֲטָרָה כָּל מָאן דְּלָא יָדַע בְּאִלֵּין הֲבָלִים וּבְרָזָא דִלְהוֹן, עֲלֵיהּ אִתְּמַר (במדבר א נא) וְהַזָּר הַקָּרֵב יוּמָת, מִיָּד אִתְחַזְרוּ אִינוּן לַאֲחוֹרָא, אָמַר לוֹן הַהוּא בַּעַל קַבִּין אַתּוּן חַכִּימִין מָארֵי דְּדָרָא, דַאֲזָלִית אַבַּתְרַיְיכוּ עַד כְּעַן לְמִנְדַּע יָת חָכְמָתַיְיכוּ, וּבְוַדַּאי לַאו אַתּוּן חַכִּימִין, דְּוַדַּאי בְּהַאי קְרָא עֲבִידְנָא כָּל בִּנְיָנָא דָא, וּבֵיהּ הֲוִינָא טָס עָלְמָא בְטִיסָה חֲדָא, וּבְזִמְנָא בִתְּרֵין, וּבְזִמְנָא בִתְּלַת, וּבְזִמְנָא בְאַרְבַּע, וּבְזִמְנָא בְחַמְשָׁא, וּבְזִמְנָא בְשִׁית, וּבְזִמְנָא בְשֶׁבַע, וַאֲנַן בְּהַאי אַרְעָא כֻלְּהוּ אַזְלֵינַן בַּעֲלֵי קַבִּין, וְהַאי קְרָא יְרִיתְנָא מֵאַבָּא, וְאַבָּא מֵאֲבוֹי, עַד דָּרָא כֻלְּהוּ, יְהַב לוֹן מָמוֹנָא סַגִּיא וְשַׁוִּי לוֹן בְּאַתְרַיְיהוּ כְּהֶרֶף עַיִן.</p>\n<p>וּבְגִין דָּא יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, אָמְרוּ לֵיהּ חַבְרַיָּיא רַבִּי אֵימָא לָן שׁוּם רְמִיזָא בְּהַאי קְרָא, דְלָא אִתְכַּסְיָּא חָכְמָתָא דָא מִן חַבְרַיָּיא, אָמַר לוֹן רַבָּנָן בְּוַדַּאי רָזָא עִלָּאָה אִית תַּמָּן, אֲבָל אֵימָא לְכוּ בִרְמִיזָא, שֶׁבַע הֲבָלִים אִינוּן, וְזַכָּאָה מָאן דְּלָא נָטִיל לְאַגְרָיְיהוּ בְּהַאי עָלְמָא, וְאִינוּן דִּכְלִילָן בְּבַת שֶׁבַע, וְאִינוּן בְּהַאי קְרָא, הֲבֵל</p>"],[9500011207,"<p>חַד, הֲבָלִים תְּרֵין הָא תְּלַת, הֲבֵל הֲבָלִים תְּלַת הֲרֵי שִׁית, הַכֹּל הָבֶל הָא שֶׁבַע, וּלְקִבְלַיְיהוּ שֶׁבַע שְׁמָהָן אבגית\"ץ וכו', אֵלּוּ שֶׁבַע הֲבָלִים אִינוּן כְּפוּלִים, לָקֳבֵל שֶׁבַע שְׁרַגִּין דִּמְנַרְתָּא, כְּפוּלִים, דְּאִתְּמַר בְּהוֹן (זכריה ד ב) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת, (ואינון) שֶׁבַע הֲוַיּוֹת, דְאִתְּמַר בְּהוֹן בַּאֲמִירָה יְהִי אוֹר, וַהֲוִי מִיָּד, וּלְבוּשִׁין דְּאִינוּן שֶׁבַע הֲוַיּוֹת אִינוּן שֶׁבַע שְׁמָהָן אבגית\"ץ וְחַבְרוֹי, הֶבֶל אִיהוּ לַהַב, הֲבָלִים לֶהָבִים, וַעֲלַיְיהוּ אִתְּמַר (תהלים כט ז) קוֹל יהו\"ה חוֹצֵב לַהֲבוֹת אֵשׁ, וּמָאן דְּיָדַע בְּאִלֵּין הֲבָלִים, כַּד אַפִּיק לוֹן מִפּוּמוֹי וּמִלִּבֵּיהּ יָדַע לְכַוְונָא בִשְׁכִינְתָּא עִלָּאָה, דְכָל הֲבָלִים מִינָה תַּלְיָין, וּמִתְלַבְּשָׁן בִּשְׁכִינְתָּא תַּתָּאָה, דִכְלִיל שֶׁבַע שְׁמָהָן אבגית\"ץ וְחַבְרוֹי, דְּאִינוּן אַתְוָון דִּבְּהוֹן אִתְבְּרִיאוּ שְׁמַיָּא וְאַרְעָא, דְּאִלֵּין תַּלְיָין בַּאֲמִירָה וְאִלֵּין בַּעֲשִׂיָּה, בְּרָזָא דְאוֹמֵר וְעוֹשֶׂה מִיָּד, וְאִלֵּין שֶׁבַע הֲבָלִים אִינוּן כְּפוּלִים, לָקֳבֵל שֶׁבַע שְׁרַגִּין דִּמְנַרְתָּא, כְּפוּלִים, דְּאִתְּמַר בְּהוּ (זכריה ד ב) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת לַנֵּרוֹת וְגוֹ', (אלין באמירה ואלין בעשיה, ואינון י\"ה יו\"ד ה\"א, ו\"ה וא\"ו ה\"א אלין אינון שבעה ושבעה מוצקות).</p>\n<p>זַכָּאָה עַמָּא דְיָדְעִין לְסַלְקָא צְלוֹתִין בַּאֲמִירָה וְעוֹבָדָא, וַעֲלֵיהּ אִתְּמַר (ישעיה נא טז) וָאָשִׂים דְּבָרַי בְּפִיךָ וכו', וְהָא אוּקְמוּה אַל תִּקְרֵי עַמִּי, אֶלָּא עִמִּי בְּשׁוּתָּפוּ, כְּמָה דְאִתְּמַר בֵּיהּ (תהלים לג ו) בִּדְבַר יהו\"ה שָׁמַיִם נַעֲשׂוּ כו', הָכִי אַנְתְּ בְּשׁוּתָּפוּ עִמִּי, דִּבְמִלּוּלָךְ אִתְעֲבִידוּ שְׁמַיָּא וְאַרְעָא.</p>\n<p>וְעוֹד הֲבֵל ה' לב, ה' אִתְפַּלֵּג לְד\"וּ פַּרְצוּפִין, דּ\"וּ, ד' אַרְבַּע רַגְלִין דְּכָרְסַיָּיא, ו', (מלכים א י יט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, זַכָּאָה אִיהוּ מָאן דְּיָרִית נִשְׁמָתָא מִכָּרְסַיָּיא יַקִּירָא, כְּלִילָא מֵעֲשַׂר תִּקּוּנִין אִלֵּין, וְעָבִיד לָהּ כָּרְסַיָּיא לַיהו\"ה, דִּשְׁמָא דְיהו\"ה דְּאִיהוּ בְאֹרַח אֲצִילוּת, לְתַקְנָא לֵיהּ כּוּרְסַיָּיא בַּר נַשׁ לְנִשְׁמָתֵיהּ, דְּהָכִי אוּקְמוּהוּ קַדְמָאִין, כָּל הַנְּשָׁמוֹת גְּזוּרוֹת מִכִּסֵּא הַכָּבוֹד, וְתַמָּן שַׁרְיָא שְׁכִינְתָּא עִלָּאָה, וְלֵית ה' בְּלָא י', ובג\"ד (שמות יז טז) כִּי יָד עַל כֵּס י\"ה.</p>\n<p>ו' שַׁרְיָא בְּמטטרו\"ן, וְדָא אִיהוּ רוּחַ הַשִּׂכְלִי דְּאִיהוּ אֲצִּילוּת, ה' שַׁרְיָא בְּאוֹפַן, וְדָא נֶפֶשׁ הַשִּׂכְלִית בְּאֹרַח אֲצִּילוּתָא, דְּאִית נְשָׁמָה וְרוּחַ וְנֶפֶשׁ שִׂכְלִית וְלָא בְאֹרַח אֲצִּילוּת, אֶלָּא אִתְּמַר בְּהוֹן גְּזוּרוֹת, וְאִינוּן כִּסֵּא וּמַלְאַךְ וְאוֹפָן, זַכָּאִין אִינוּן יִשְׂרָאֵל דְּסָלְקִין הֲבָלִים דִּצְּלוֹתִין בְּהוֹן, לְגַבֵּי אַתְוָון דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתָּא עִלָּאָה וְתַתָּאָה, ובג\"ד (קהלת ח יד) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, וְיֵשׁ הֶבֶל דְּרַשִּׁיעַיָּא, דְאִינוּן הֲבָלִים דְּשִׁקְרָא, וְנָטְלִין לוֹן מַלְאֲכֵי חַבָּלָה, וְנָטְעִין בְּהוֹן רְקִיעִין וְאַרְעִין דְּשִׁקְרָא, וַעֲלַיְיהוּ אִתְּמַר (ירמיה י טו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתּוּעִים, (כאן חסר), קָמוּ כֻלְּהוּ וְאִשְׁתַּטְחוּ קַמֵּיהּ, וְאָמְרוּ אִלּוּ לָא אַתֵינָא לְעָלְמָא, אֶלָּא לְמִשְׁמַע דָּא דַי.</p>\n<p>(זכריה ד׳:ב׳) לַנֵּרוֹת אֲשֶׁר עַל רֹאשָׁהּ, וְאִינוּן י\"ה יו\"ד ה\"א, ו\"ה וא\"ו ה\"א, וְאִינוּן שֶׁבַע כְּפוּלוֹת בג\"ד כפר\"ת</p>"],[9500011208,"<p>לְבוּשִׁין לוֹן, וְכֻלְּהוּ סָלְקִין מִלִּבָּא לְפוּמָא, שֶׁבַע הֲבָלִים סָלְקִין, שֶׁבַע נָחֲתִין לְאַשְׁקָאָה לוֹן, וּבְגִין דָּא (זכריה ד׳:ב׳) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת, תְּלַת אִינוּן גְּנִיזִין לְעִילָא, דִּלְבוּשִׁין דִּלְהוֹן אֶמֶ\"שׁ, דְּאִינוּן אֵשׁ מַיִם רוּחַ, הָא אִינוּן עֲשַׂר דְּסָלְקִין מִל\"ב נְתִיבוֹת, וְאִינוּן לְקִבְלַיְיהוּ עֲשַׂר אֲמִירָן, וְל\"ב אלהי\"ם דִּבְּרֵאשִׁית, הָא מ\"ב, מִלִּבָּא נָפִיק אֶשָּׁא, מִכַּנְפֵי רֵיאָה רוּחָא, מִמּוֹחָא מַיָּא, וְרוּחָא אֲחִיד בְּמַיָּא וְאֶשָּׁא וְאִתְעֲבִיד קוֹל, כַּד אֲחִיד בְּמַיָּא אִתְּמַר בֵּיהּ (תהלים כט ג) קוֹל יהו\"ה עַל הַמָּיִם, כַּד אֲחִיד בְּאֶשָּׁא אִתְּמַר בֵּיהּ (שם) קוֹל יהו\"ה חֹצֵב לַהֲבוֹת אֵשׁ, כַּד אֲחִיד בְּרוּחָא אִיהוּ (מ\"א יט יא) רוּחַ חָזָק מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, וַעֲלֵיהּ אִתְּמַר קוֹל יהו\"ה שׁוֹבֵר אֲרָזִים.</p>\n<p>וּתְלַת נְקוּדִין אִינוּן לָקֳבֵל אֱמֶ\"שׁ, וְאִינוּן חָשַׁ\"ק, הֲדָא הוּא דִכְתִיב (דברים י טו) רַק בַּאֲבֹתֶיךָ חָשַׁק יהו\"ה, וְאִינוּן חֹלֵ\"ם שְׁבָ\"א קָמֵ\"ץ, קָמֵ\"ץ לִימִינָא קוֹל יהו\"ה עַל הַמָּיִם, וְכַד רוּחָא אֲחִיד בֵּיהּ דְּאִיהוּ חֹלֵ\"ם, אִתְּמַר בֵּיהּ (בראשית א ב) וְרוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, שְׁבָ\"א אִיהוּ בָּאֵשׁ, וְכַד אֲחִיד בֵּיהּ רוּחַ, אִיהוּ רוּחַ חָזָק מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים, מִסִּטְרָא דִגְבוּרָה דְאִיהוּ תַּקִּיף, כַּד אֲחִיד בֵּיהּ רוּחָא דְאִיהוּ חֹלֵ\"ם בֵּין קָמֵ\"ץ שְׁבָ\"א דְאִינוּן מַיָּא וְאֶשָּׁא, דְּאִינוּן תְּרֵין דְּרוֹעִין, דְּאִית בְּהוֹן יַד יָמִין יַד שְׂמֹאל דְּאִינוּן כ\"ח פִּרְקִין, אִתְּמַר בְּהוּ קוֹל יהו\"ה בַּכֹּחַ, כַּד הַאי רוּחָא אֲחִיד בְּעַמּוּדָא דְאֶמְצָעִיתָא, אִתְּמַר בֵּיהּ קוֹל יהו\"ה בֶּהָדָר, כַּד אֲחִיד בִּתְרֵין שׁוֹקִין דְּאִינוּן צֵרִ\"י, אִתְּמַר בְּהוֹן קוֹל יהו\"ה יְחוֹלֵל אַיָּלוֹת, דְּאִינוּן תְּרֵי עוּזְלֵי דְאַיָּילָתָא, תְּרֵין אַחִים אִישׁ בְּאָחִיהוּ יְדוּבָּקוּ.</p>\n<p>וְהָכָא רָזָא דְיִבּוּם, דְּאִם יִפּוֹל אָחִיו הָא תִּנְיָינָא דְיוֹקִים לֵיהּ, וְרָזָא דְמִלָּה (איכה א יג) נְתָנַנִי שׁוֹמֵמָה כָּל הַיּוֹם דָּוָ\"ה, וְדָא הוֹ\"ד, דְּאִתְּמַר בֵּיהּ (בראשית לב לג) כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב, בְּכַף דִּילֵיהּ, שְׁכִינְתָּא דָוָה אִיהִי בְגָלוּתָא, בְּגִין דְּפָרַח מִנֵּיהּ יֶרֶךְ דְּאִיהוּ ו' מִן ה', וְאִשְׁתְּאָרַת אִיהִי ד' דִּילָהּ (דלה), קוֹל יהו\"ה יָחִיל מִדְבָּר דָּא חִירֵ\"ק וְדָא צַדִּיק, כַּד רוּחַ אֲחִיד בֵּיהּ אִיהוּ יָחִיל מִדְבָּר, שֶׁבַע קָלִין לָקֳבֵל שֶׁבַע שְׁמָהָן אבגית\"ץ כו'.</p>\n<p>רוּחַ סָלִיק בְּאַוִּיר דְּאִיהוּ כֶּתֶר עִלָּאָה אַוִּיר קַדְמוֹן, אֵשׁ סָלִיק לְגַבֵּי ה' דְּאִיהוּ אִימָּא וְאִתְעֲבִיד אִשָּׁה, מַיִם סָלִיק לְגַבֵּי י' וְאִתְעֲבִיד יַמִּים, וְדָא חָכְמָה, וְהָכִי נָחֲתִין לְגַבֵּי נֶצַח וְהוֹד יְסוֹד, מַלְכוּת מָאנָא דְכֻלְּהוּ, וְאִיהִי עָפָר כְּלִילָא מִכֻּלְּהוּ, וְאִיהִי כְלָלָא דְכָל אַתְוָון דְּאִינוּן מָאנָא לִנְקוּדִין, וְעַל אִלֵּין שֶׁבַע קָלִין אִתְּמַר (שמות כ יח) וְכָל הָעָם רֹאִים אֶת הַקּוֹלֹת, וְעַל תְּלַת גְּנִיזִין אָמַר (דברים ד יב) קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים, בַּת קוֹל דְּכֻלְּהוּ שְׁכִינְתָּא תַּתָּאָה.</p>\n<p>תָּא חֲזִי תְּלַת נְקוּדִין אִינוּן, חִירֵק חֹלֵם שֻׁרֵק, חֹלֵם, קוֹצָא דְי' לְעִילָא אִיהוּ חֹלֵם, קוֹצָא דְאָת י' לְתַתָּא אִיהִי חִירֵק, גוֹ אֶמְצָעִיתָא אִיהוּ שׁוּרֵק, כַּד אִינוּן תְּלַת כַּחֲדָא, אִינוּן סֶגוֹלְתָּא וְאִינוּן שַׁלְשֶׁלֶת וְאִינוּן שֻׁרֵ\"ק וְאִינוּן סֶגוֹ\"ל,</p>\n<p>כֶּתֶר עַל חָכְמָה וּבִינָה אִיהוּ סֶגוֹלְתָּ\"א חֹלֵ\"ם עַל צֵרִ\"י, סֶגוֹ\"ל אִיהוּ נְקוּדָה תְּחוֹת צֵרִ\"י, חֶסֶד גְּבוּרָה, תִּפְאֶרֶת לְתַתָּא, נֶצַח הוֹד, יְסוֹד בְּאֶמְצָעִיתָא אִיהוּ שֻׁרֵק, וְהָכִי כַד תִּפְאֶרֶת בְּאֶמְצָעִיתָא אִיהוּ שַׁלְשֶׁלֶת, שְׁבָ\"א אִיהוּ תְּרֵין נְקוּדִין, כַּד אִתְגַּבַּר מַיָּא עַל אֶשָּׁא אוֹ אֶשָּׁא עַל מַיָּא, אוֹ כַּד אִינוּן יְסוֹד עַל מַלְכוּת, כָּל סְפִירָה דָא עַל גַּבֵּי דָא בְּכָל אֲתַר אִיהוּ שְׁבָ\"א, וְרָזָא דְמִלָּה, אֶת הַמָּאוֹר הַגָּדוֹל וְאֶת הַמָּאוֹר הַקָּטֹן, כַּד אִינוּן שָׁוִין הֲווּ צֵרִ\"י, אֶת שְׁנֵי הַמְּאוֹרוֹת הַגְּדוֹלִים, וְכָל נְקוּדִין אִינוּן דִּבּוּר וְאַתְוָון הֲבֵל הֲבָלִים, דְּתַלְיָין מִן ה\"ה, וְאִינוּן אַתְוָון רַבְרְבָן, וְאַתְוָון זְעִירָן, (נקודין מי' בת קול ודאי, קלין אינון מן ו', ואינון אתוון ונקודין), וְטַעֲמֵי כְלִילָן בְּהוּ, (נ\"א נקודין מתלבשין במיא בימינא, דאתמר הרוצה להחכים ידרים), אַתְוָון מִן ה' ה', נְקוּדִין מִן י', טַעֲמֵי מִן ו', נְקוּדִין</p>"],[9500011209,"<p>מִתְלַבְּשָׁן בְּמַיָּא בִימִינָא, דְאִתְּמַר בֵּיהּ הָרוֹצֶה לְהַחְכִּים יַדְרִים, אַתְוָון מִתְלַבְּשִׁין בְּאֶשָּׁא בִּשְׂמָאלָא, וַעֲלַיְיהוּ אִתְּמַר קוֹל יהו\"ה חֹצֵב לַהֲבוֹת אֵשׁ דְּאִינוּן הֲבָלִים, טַעֲמֵי מִתְלַבְּשָׁן בְּאַוִּירָא בְאֶמְצָעִיתָא, וְטַעֲמֵי אִינוּן מִסִּטְרָא דְכֶתֶר, וּנְקוּדִין מִסִּטְרָא דְחָכְמָה, וְאַתְוָון מִסִּטְרָא דְבִינָה, (דבגינה) וּמִתְלַבְּשִׁין בְּמַיָּא אֶשָּׁא וְרוּחָא, דְּאִינוּן חֶסֶד גְּבוּרָה תִּפְאֶרֶת, וְהָכִי מִתְלַבְּשִׁין בְּנֶצַח הוֹד יְסוֹד, מַלְכוּת מָאנָא דְכֻלְּהוּ, כְלִילָא מִכֻּלְּהוּ.</p>\n<p>אִיהִי פֶּה דְמִינָהּ הֲבָלִים נָפְקִין וְקָלִין וְדִבּוּרִין, כֻּלְּהוּ אִתְכְּלִילָן בָּהּ, וְאִיהִי לֵב דְּכֻלְּהוּ בָהּ אִתְכְּלִילָן, וּמִינָהּ נָפְקִין דְּפִיקוּ דְרוּחָא לְכָל עַרְקִין דִּדְרוֹעָא, כַּד רוּחָא דָפִיק בְּמַיָּא דְאִיהוּ לִימִינָא, אִתְּמַר בֵּיהּ (שיר ה ב) קוֹל דּוֹדִי דוֹפֵק פִּתְחִי לִי אֲחוֹתִי, לְהַהִיא דְאִתְּמַר בָּהּ (משלי ז ד) אֱמוֹר לַחָכְמָה אֲחוֹתִי אָתְּ, וְכַד דָּפִיק לִשְׂמָאלָא דְאִיהִי אֶשָּׁא, אִתְּמַר בָּהּ רַעִִיָתִי, דְּבֵיהּ אִתּוֹקַד בְּכַמָּה רְשָׁפִי\"ם דְּאִינוּן שְׂרָפִי\"ם, דְּאִתְּמַר בְּהוֹן (שיר ח ו) רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ שַׁלְהֶבֶת יָ\"הּ.</p>\n<p>מִסִּטְרָא דְעַמּוּדָא דְאֶמְצָעִיתָא יוֹנָתִי תַמָּתִי, בְּגִין דְּאִיהִי דַרְגָּא דְיַעֲקֹב דְּאִתְּמַר בֵּיהּ (בראשית כה כז) וְיַעֲקֹב אִישׁ תָּם, וּדְפִיקוּ דִילֵיהּ תַּמָּן בְּמִשְׁקָל, לָא סָלִיק וְלָא נָחִית, דִּי בְמַיָּא נָחִית לְגַבֵּי צַדִּיק נְבִיעוּ לְגַבֵּיהּ בַּאֲרִיכוּ, וְסָלִיק בֵּיהּ בַּאֲרִיכוּ דִתְּקִיעָה, בְּאֶשָּׁא אִיהוּ דְפִיקוּ בִשְׁבָרִים בִּתְּבִירוּ, וּבְעַמּוּדָא דְאֶמְצָעִיתָא נָחִית (נ\"א אחיד) בְּתַרְוַיְיהוּ שַׁלְשֶׁלֶ\"ת, בֵּינוּנִי וְדָא תְרוּעָה, קוֹל דְּמָמָה דַקָּה לְגַבֵּי שְׁכִינְתָּא תַּתָּאָה, תַמָּתִי, תַּם הַהוּא דְפִיקוּ בְּגִין דְּהֵבִיאוּ לָהּ בַּחֲשַׁאי.</p>\n<p>וְכַד שְׁכִינְתָּא אִיהִי בְגָלוּתָא אִתְּמַר בָּהּ (שיר ה ב) אֲנִי יְשֵׁנָה וְלִבִּי עִר, כַּד אִיהִי יְשֵׁנָה לֵית בָּהּ דְּפִיקוּ, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא דְאִיהוּ קוֹל דְּפִיקוּ דִילָהּ אִתְרַחַק מִינָהּ, הֲדָא הוּא דִכְתִיב (תהלים לט ג) נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁתִי מִטּוֹב, לָמָּה נֶאֱלַמְתִּי, מִי\"ה דְּאִיהוּ דוּמִיָּה דְאִתְרַמִּיז בֵּאלֹהִי\"ם, דְּאִיהוּ ל\"ב אלהי\"ם דְּמַעֲשֵׂה בְרֵאשִׁית, דְּדָפִיק רוּחָא דְקוּדְשָׁא דְאִתְּמַר בֵּיהּ (בראשית א ב) וְרוּחַ אלהי\"ם, בְּגִין דְּהֶחשֵׁתִי מִטּוֹב דְּאִיהוּ קוֹל, בְּהַהוּא זִמְנָא אִשְׁתְּאָרַת בַּת יְחִידָה בְלָא קוֹל, וּבְגִין דָּא לֵית בַּת קוֹל בְּגָלוּתָא, וּבְגִין דְּלֵית בַּת קוֹל בְּגָלוּתָא הֵבִיאוּ לָהּ בַּחֲשַׁאי, וּבְגִין דָּא צְלוֹתָא אִיהִי בַחֲשַׁאי, אַף עַל גַּב דְּרָזִין סַגִּיאִין אִית הָכָא, שַׁבְעִין אַנְפִּין אִית לְאוֹרַיְיתָא.</p>\n<p>וּבְהַהוּא זִמְנָא לֵית לָהּ דְּפִיקוּ דְאִיהוּ כְגַוְונָא דִנְקוּדֵי דִמְנַקְּדִין בִּדְפִיקוּ דְאֶצְבְּעָאן דְּאִינוּן עֲשַׂר, דִּבְהוֹן מְנַקְּדִין בִּדְפִיקוּ דְרוּחָא, וְאִינוּן מְנַקְּדִין בְּנִימִין דְּכִנּוֹר דְּדָוִד, דְּפִיקוּ אִיהוּ כְּגַוְונָא דְקָלָא דְסָלִיק בְּנִגּוּנָא, לָקֳבֵל עֲשָׂרָה דְפִיקִין דְּאִסְתַּכַּל אַסְיָא בִדְפִיקוּ, עָבַד דָּוִד עֲשָׂרָה מִינֵי נִגּוּנִים בַּתִּלִּים, אַרְבָּעָה אִינוּן (שיר ה ב) אֲחוֹתִי רַעִִיָתִי יוֹנָתִי תַמָּתִי לָקֳבֵל יהו\"ה, עֲשָׂרָה דְפִיקִין לָקֳבֵל יוד הא ואו הא, דְּפִיקוּ נָפִיק מֵאֻדְנָא שְׂמָאלָא דְלִבָּא, וְדָא הוּא רוּחַ צְפוֹנִי דַהֲוָה מְנַשֵּׁב בְּכִנּוֹר דְּדָוִד דַּהֲוָה מְנַגֵּן מֵאֵלָיו, וְכָל עַרְקִין וּוָרִידֵי גוּפָא דְאִינוּן דָּפְקִין, מִלִּבָּא אִינוּן (נ\"א הוה) דָּפְקִין, וְרָזָא דְמִלָּה (יחזקאל א יב) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ.</p>\n<p>כָּבֵד הוּא סמא\"ל הוּא עִשָׂו, דְּלֵית בֵּיהּ רוּחָא דְקוּדְשָׁא, לָא דָפְקִין עַרְקִין דִּילֵיהּ, וּבְגִין דָּא לָא שַׁרְיָא שְׁכִינְתָּא בְּאוּמִין דְּעָלְמָא, וּבְגָלוּתָא דְאִסְתַּלַּק רוּח דְקוּדְשָׁא, דְאִתְּמַר בֵּיהּ (ישעיה יא ב) וְנָחָה עָלָיו רוּחַ יהו\"ה וגו', לֵית דְּפִיקוּ בְלִבָּא דְאִיהִי שְׁכִינְתָּא, וּבְגִין דָּא אִתְּמַר בָּהּ (שיר ה ב) אֲנִי יְשֵׁנָה וְלִבִּי עִר, וְלֵית בַּת קוֹל בְּפוּמָא (דהוה סלקא), (נ\"א דבה סליק) קָלָא בְרוּחָא בַּתְּקִיעָה בַּאֲרִיכוּ, וּבַשְּׁבָרִים בִּתְּבִירוּ, וּבַתְּרוּעָה שַׁלְשֶׁלֶ\"ת קָלָא בֵּינוּנִית לָא בַאֲרִיכוּ וְלָא בִקְצִירוּ, בַּת קוֹל אִיהִי קוֹל דְּמָמָה דַקָּה זְעִירָא, קָלָא נְמוּכָה בַחֲשַׁאי, דְּהָא קוֹל בְּאִשָּׁה עִִרְוָה. וְכַד יֵיתֵי מְשִׁיחָא נָחִית רוּחָא דְקוּדְשָׁא עֲלֵיהּ, וּמִיָּד אִיהִי אָמְרַת קוֹל דּוֹדִי דוֹפֵק, דְּפִיקוּ סָלִיק וְנָחִית, סָלִיק ה' עִלָּאָה</p>"],[9500011210,"<p>לְגַבֵּי י', וְנָחִית ה' תַּתָּאָה לְגַבֵּי ו', דְּאִיהוּ קָרְבָּן לַיהו\"ה, קָרְבָּן עוֹלֶה וְיוֹרֵד.</p>\n<p>וְרָזָא דְמִלָּה (משלי ג יט) יהו\"ה בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, בְּאַבָּא דְאִיהוּ י' יָסַד בְּרַתָּא דְאִיהִי ה' זְעִירָא, דַּעֲלָהּ אִתְּמַר (בראשית לז יא) וְאָבִיו שָׁמַר אֶת הַדָּבָר, בְּאִימָּא דְאִיהִי ה' עִלָּאָה כּוֹנֵן שָׁמַיִם דְּאִיהוּ ו', וְאִיהוּ בֶן י\"ה, וְכַד יְהוֹן מִתְקָרְבִין אַתְוָון אָב עִם אֵם בֵּן עִם בַּת כָּל חַד בְּבַת זוּגֵיהּ, ה' עִלָּאָה (סליק) לְגַבֵּי י', ה' (תתאה) נָחִית לְגַבֵּי ו', הַאי אִיהוּ קָרְבָּן עוֹלֶה וְיוֹרֵד, בְּהַהוּא זִמְנָא (יחזקאל לז ז) וַתִּקְרְבוּ עֲצָמוֹת עִִצֶם אֶל עַצְמוֹ, וְרָזָא דְמִלָּה (בראשית ב כג) עִִצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי, עִִצֶם מֵעֲצָמַי דָא י' עִם ה', וּבָשָׂר מִבְּשָׂרִי דָא ו' עִם ה', (שם כד) וְעַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְגוֹמֵר.</p>\n<p>וּבְגִין דָּא כַּד סָלִיק ה' לְגַבֵּי י' אִתְּמַר בָּהּ (ויקרא ו ב) זֹאת תּוֹרַת הָעוֹלָה הִיא הָעוֹלָה, דְּהִיא (דהוה) סְלִיקַת לְגַבֵּי אַבָּא, וְכַד נְחִיתַת לְגַבֵּי בְּרָא אִתְּמַר בָּהּ (שם ה) וְאֵשׁ הַמִּזְבֵּחַ תּוּקַד בּוֹ, אִתּוֹקַד בֵּיהּ בְּשַׁלְהוֹבִין דִּרְחִימוּ, וְהָכִי כַד נָחִית ו' לְגַבֵּי ה' דִילֵיהּ, וְי' סָלִיק לְגַבֵּי ה' דִילֵיהּ, בְּהַהוּא זִמְנָא (בראשית כח יב) וְהִנֵּה מַלְאֲכֵי אלהי\"ם עוֹלִים וְיוֹרְדִים בּוֹ, כָּל אִלֵּין דְּפִיקִין דִּשְׁאָר עַרְקִין, וְהָכִי אוּקְמוּהוּ סָלְקִין תְּרֵין וְנָחֲתִין תְּרֵין, סָלְקִין תְּרֵי י\"ה דָּא לְגַבֵּי דָא, וְנָחֲתִין תְּרֵי ו\"ה דָּא לְגַבֵּי דָא.</p>\n<p>וְעוֹד סָלְקִין תְּרֵי רוּחָא וְאֶשָּׁא, דְאִינוּן קָלִין וְסָלְקִין בִּדְפִיקוּ, וְנָחֲתִין תְּרֵי מַיָּא וְעַפְרָא, דְאִינוּן כְּבֵדִין בִּדְפִיקוּ, וְאִינוּן מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל רְפָאֵ\"ל, מִיכָאֵ\"ל מַיָּא, גַּבְרִיאֵ\"ל אֶשָּׁא, נוּרִיאֵ\"ל רוּחָא, רְפָאֵ\"ל עַפְרָא, י' בְּרֵישָׁא, ה\"ה בִּידַיִן, ו' בְּגוּפָא, ה\"ה הֲבַל סָלִיק הֲבַל נָחִית, הֲבַל סָלִיק דָּא ה' עִלָּאָה דְסָלִיק לְגַבֵּי י' דְּאִיהוּ עֲשַׂר אֲמִירָן, וּבְמַאי סָלִיק בְּקָלָא דְאִיהוּ ו',</p>\n<p>וַהֲבַל נָחִית דָּא ה' תַּתָּאָה דְנָחִית לְגַבֵּיהּ וְאִתְעֲבִידַת דִּבּוּר, קְרִיבוּ דְכָל הֲבָלִים וְקָלָא וְדִבּוּרָא אִיהוּ פֶ\"ה, דְאִיהוּ בְּחוּשְׁבַּן מִילָ\"ה, כְּלִיל כֹּלָּא, אִיהוּ קְרִיבוּ דְאדנ\"י בְּעַמּוּדָא דְאֶמְצָעִיתָא קָרְבָּן לַיהו\"ה, וְדָא שְׁכִינְתָּא תַּתָּאָה, וְאִיהִי (ואיהו) יִחוּדָא דְאַתְוָון יהו\"ה בַּצַּדִּיק, דְּאִיהוּ אוֹת בְּרִית, וְזַכָּאָה אִיהוּ מָאן דְּקָרִיב אַתְוָון אִלֵּין בִּצְלוֹתִין, דְּאִיהִי קָרְבָּנָא דְקוּדְשָׁא בְּרִיךְ הוּא שְׁכִינְתָּא דִילֵיהּ בְּפִימוֹי, זַכָּאָה אִיהוּ מָאן דִּמְיַחֵד לוֹן בִּקְרִיאַת שְׁמַע וּבִצְלוֹתֵיהּ, דִּקְרִיבוּ דִלְהוֹן וַדַּאי בְּעַמּוּדָא דְאֶמְצָעִיתָא, יִחוּדָא דִלְהוֹן בַּצַּדִּיק, וּמָאן אִיהוּ דִמְיַחֵד כֹּלָּא וּמְקָרֵב כֹּלָּא עִלַּת הָעִלּוֹת.</p>\n<p>אַדְהָכִי הָא סָבָא קָא אִזְדַּמַּן לֵיהּ דַּהֲוָה נָהִיר עָלְמִין רַבִּי פִּנְחָס בֶּן יָאִיר שְׁמֵיהּ, וְאָמַר רַבִּי רַבִּי, וַדַּאי קְרִיבוּ דְאַרְבַּע אַתְוָון וְיִחוּדָא דִלְהוֹן בְּעַמּוּדָא דְאֶמְצָעִיתָא, וּקְרִיבוּ וְיִחוּדָא דִלְהוֹן הָכִי הוּא בַּצַּדִּיק, וּבִתְּרֵין דַּרְגִּין מְיַחֲדִין לוֹן יִשְׂרָאֵל, בִּקְרִיאַת שְׁמַע דְּעַרְבִית וְשַׁחֲרִית, וּמְקָרְבִין לוֹן בִּצְלוֹתָא דְשַׁחֲרִית וְעַרְבִית, וְדָא קָרְבָּן עוֹלֶה וְיוֹרֵד, ה' עוֹלֶה בְּעַמּוּדָא דְאֶמְצָעִיתָא, ו' יוֹרֵד בַּצַּדִּיק, אַף עַל גַּב דְּכֹלָּא קְשׁוֹט, עוֹלֶה וְיוֹרֵד ה' בְּאָת י', ה' בְּאָת ו', מִיָּד דְּאָמַר מִלִּין אִלֵּין פָּרַח.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּא, זַכָּאָה חוּלְקָנָא דְעִלָּאִין וְתַתָּאִין אִינוּן בְּאַסְכָּמוּתָא לְסַיֵּיעַ לָן, הַאי אִיהוּ דְאוּקְמוּהוּ מָארֵי מַתְנִיתִין דְּבַר נַשׁ דְּאִשְׁתַּדַּל בְּפוּלְחָנָא דְמָארֵיהּ דְּכָל בִּרְיָין דְּעָלְמָא אִינוּן בְּסַיְעַתָּא דִילֵיהּ, כְּמָה דְאוּקְמוּהָ כָּל הָעוֹלָם כֻּלּוֹ לֹא נִבְרָא אֶלָּא לְצַוּוֹת לָזֶה, וַאֲפִילוּ שְׂרָפִים וְחַיּוֹת וְאוֹפַנִּים לָא אִתְבְּרִיאוּ אֶלָּא לְסַיַּיעִִתֵּיהּ, וְכַד בַּר נַשׁ אַפִּיק הֲבָלִים וְדִבּוּרִים בִּצְלוֹתֵיהּ, כַּמָּה עוֹפִין פָּתְחִין גַּדְפַיְיהוּ וּפִימַיְיהוּ לְקַבְּלָא לוֹן, הֲדָא הוּא דִכְתִיב (קהלת י׳:כ׳) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגֵּיד דָּבָר, וְנָטִיל קוּדְשָׁא בְּרִיךְ הוּא אִלֵּין מִלִּין וּבָנֵי בְּהוֹן עָלְמִין, דְּאִתְּמַר בְּהוֹן (ישעיה סו כב) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה אֲשֶׁר אֲנִי עֹשֶׂה, וְרָזָא דְמִלָּה (שם נא טז) וָאָשִׂים דְּבָרַי בְּפִיךָ וּבְצֵל יָדִי כִּסִּיתִיךָ, לִנְטֹעַ שָׁמַיִם וְלִיסֹד אָרֶץ וְלֵאמֹר לְצִיּוֹן עַמִּי אָתָּה.</p>"],[9500011211,"<p>אַל תִּקְרֵי עַמִּי אֶלָּא עִמִּי בְּשׁוּתָּפוּ.</p>\n<p>אַדְהָכִי הָא סָבָא קָא נָחִית פָּתַח וְאָמַר (שיר ה ב) אֲנִי יְשֵׁנָה וְלִבִּי עִר, אֲנִי יְשֵׁנָה מֵרְחִימָאי דְּאִתְרַחַק מִנִּי, וְלִבִּי עִר כַּד אַתְיָא לְגַבָּי, לְכַלָּה דַהֲוַת נְשׂוּאָה לְחָתָן, וְאִתְרַחַק מִינָהּ, נָפְלַת בְּבֵי מַרְעָא, וְאִתְכַּנְשׁוּ כָל אַסְיָין לְגַבָּהּ, וְלָא הֲווֹ יָכְלִין לְמִנְדַּע מַרְעָא דִילָהּ, אַסְיָא קַרְטְנָא הֲוָה תַמָּן דַּהֲוָה אִשְׁתְּמוֹדָע בִּדְפִיקוּ, בַּעֲשָׂרָה מִינֵי דְפִיקִין דְּבָעִי לְאִסְתַּכְּלָא בְּהוֹן אַסְיָא, לָקֳבֵל עֲשַׂר אֶצְבְּעָאן, וְלָא הֲווֹ אִשְׁתְּמוֹדְעָאן בְּמַרְעָא דִילָהּ אֶלָּא הוּא, דְכַמָּה מַשְׁקִין וְרֵיחִין טָבִין מִתַּפּוּחִין, דְּאִתְּמַר בְּהוֹן (שם ז ט) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים, וְכַמָּה מַשְׁקִין מֵעֲסִיס רִמּוֹנִים הֲווֹ מַשְׁקִין לָהּ אַסְיָין אָחֳרָנִין, וְלָא הֲווֹ מְהַנְּיָין לָהּ, עַד דְּאָתָא (דהאי) אַסְיָא קַרְטְנָא אִסְתַּכַּל בִּדְפִיקוּ דִילָהּ, וְאִיהִי אִשְׁתְּמוֹדְעָא בְאַסְיָא, וְאָמְרַת (שם ה ב) קוֹל דּוֹדִי דוֹפֵק, וְאִיהוּ אָמַר פִּתְחִי לִי, פִּתְחִי לְאָת י' דְּאִיהִי עֲשָׂרָה מִינֵי דְפִיקוּ, קוֹל דּוֹדִי דוֹפֵק דָּא ו' דָּפִיק לְתַרְעָא, בְּשִׁית (דפיקין) פִּרְקִין דִּדְרוֹעִין, וְרָזָא דְמִלָּה (שם יד) יָדָיו גְּלִילֵי זָהָב מְמוּלָּאִים בַּתַּרְשִׁישׁ, בִּתְרֵ\"י שֵׁ\"שׁ, בִּתְרֵין דְּרוֹעִין שִׁית פִּרְקִין, וְכֻלְּהוּ רְמִיזִין בְּמִלַּת בְּרֵאשִׁית דְּאִיהוּ בָּרָ\"א שִׁי\"ת.</p>\n<p>וַעֲלַיְהוּ אִתְּמַר פִּתְחִי לִי בְּאָת ב', (תהלים קיח יט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק, (שם כד ז) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם וְיָבֹא מֶלֶךְ הַכָּבוֹד, וּבְגִין דָּא פִּתְחִי לִי בְּאָת ב', (שם קיח כ) זֶה הַשַּׁעַר לַיהו\"ה, וְדָא אָת ב' מִן בְּרֵאשִׁית, אֲחוֹתִי בְּאָת א' מִן בְּרֵאשִׁית, רַעִִיָתִי בְּאָת ר' מִן בְּרֵאשִׁית, יוֹנָתִי בְּאָת י' מִבְּרֵאשִׁית, תַמָּתִי בְּאָת ת' מִן בְּרֵאשִׁית, שֶׁרֹאשִׁי בְּאָת ש' מִן בְּרֵאשִׁית, (נמלא טל, רזא דמלה יהו\"ה אח\"ד דסליק לחשבן ט\"ל), דָּבָר אַחֵר נִמְלָא טָ\"ל בֵּאלֹהִי\"ם, וּבֵיהּ אִיהִי מְלֵיאָ\"ה, בְּאָן אֲתַר בְּיוֹמָא שְׁבִיעָאָה דְּאִיהוּ שְׁתִיתָאָה, וְעַל רֵישֵׁיהּ י' עֲטָרָה כְלִילָא מֵעֲשָׂרָה, י' אִיהִי טִפָּה דְאִתְמַשְׁכַת מִן מוֹחָא לְגַבֵּי ה' אֲפִיקֵי מָיִם, ו' רוּחָא דְנָפִיק מֵאֹזֶן שְׂמָאלָא, רוּחַ צְפוֹנִית דַהֲוָה נָפִיק מֵאֹזֶן שְׂמָאלָא דְלִבָּא, וַהֲוָה מְנַשֵּׁב בְּכִנּוֹר דְּדָוִד וַהֲוָה מְנַגֵּן מֵאֵלָיו, וַעֲלֵיהּ אִתְּמַר קוֹל דּוֹדִי דוֹפֵק, דִּבְקַדְמֵיתָא אָמְרַת ה' זְעִירָא אֲנִי יְשֵׁנָה מִן י\"ה, עַד דְּאִתְעַר ו' לְגַבִּי דְאִיהוּ רוּחַ, וּמִיָּד קוֹל דּוֹדִי דוֹפֵק בְּשִׁית אַתְוָון מִן בְּרֵאשִׁית, דְּאִינוּן לָקֳבֵל שִׁית תֵּיבִין דְּיִחוּדָא, וְאִינוּן לָקֳבֵל שִׁית יוֹמֵי בְּרֵאשִׁית.</p>\n<p>וְעוֹד פִּתְחִי לִי בְּיוֹמָא קַדְמָאָה דְאִיהִי יְמִינָא, דַעֲלֵיהּ אִתְּמַר (שם קמה טז) פּוֹתֵחַ אֶת יָדֶיךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן, יָדֶיךָ יוּדֶיךָ, דָּא י' דְּאִיהוּ לִימִינָא, אֲחוֹתִי בְּיוֹמָא תִּנְיָינָא דְתַמָּן ה', יוֹנָתִי בְּיוֹמָא תְּלִיתָאָה דְתַמָּן ו', שֶׁרֹאשִׁי נִמְלָא טָל בְּיוֹמָא רְבִיעָאָה (נ\"א תליתאה), דְּאִיהוּ כְּלָלָא דְיו\"ד ה\"א וא\"ו דְּאִיהוּ חוּשְׁבַּן טָ\"ל, וְדָא אִיהוּ גוּפָא וּבְרִית דְּחַשְׁבֵינָן חַד בְּחֻשְׁבָּן, דְּאִיהוּ וָא\"ו דְּסָלִיק אֶחָ\"ד, ו' עִלָּאָה עַמּוּדָא דְאֶמְצָעִיתָא, ו' תַּתָּאָה צַדִּיק, א' אַחֲזֵי עַל תַּרְוַיְיהוּ דְאִינוּן חָד.</p>\n<p>קֶּוֵצּוֹתָיו אִלֵּין שִׁית קְצָווֹת דְּאִינוּן ה\"א, שִׁית פִּרְקִין דִּכְלִילָן בִּתְרֵין שׁוֹקִין, דְּאִינוּן יוֹם חֲמִישִׁי וְיוֹם שִׁשִּׁי, דְעַלֵייהוּ אִתְּמַר (שיר ח טו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, רְסִיסֵי לָיְלָה דָּא שְׁכִינְתָּא תַּתָּאָה כְּלִילָא מִיו\"ד ה\"א וא\"ו ה\"א, וְאַמַּאי אִתְקְרִיאַת לַיְלָה, דְּאִיהִי לֵיל שַׁבָּת לֵיל שִׁמּוּרִים, דְּאִיהִי וַדַּאי לַיהו\"ה, בְּהוֹצִיאוֹ אוֹתָם מֵאֶרֶץ מִצְרָיִם. וְעוֹד אֲנִי יְשֵׁנָה בְּמִשְׁנָה, וְלִבִּי עִר בְּאוֹרַיְיתָא, דְאִתְּמַר בָּהּ (שם ב יג) הַתְּאֵנָה חָנְטָה פַגֶּיהָ, דְּאִינוּן תַּלְמִידֵי חֲכָמִים בְּל\"ב נְתִיבוֹת פְּלִיאוֹת חָכְמָה, בְּל\"ב אלהי\"ם דְּעוֹבָדָא</p>"],[9500011212,"<p>דִבְּרֵאשִׁית, בְּל\"ב דְּאִיהוּ ב' מִן בְּרֵאשִׁית ל' מִן לְעִינֵי כָּל יִשְׂרָאֵל, (שיר ב יג) וְהַגְּפָנִים סְמָדַר נָתְנוּ רֵיחַ אִלֵּין בַּעֲלֵי מִצְוֹת, קוּמִי לָךְ רַעִִיָתִי יָפָתִי וּלְכִי לָךְ קוּמִי לָךְ בְּאוֹרַיְיתָא דְבִכְתָב, יָפָתִי וּלְכִי לָךְ בַּהֲלָכָה אוֹרַיְיתָא דִבְעַל פֶּה, וְעוֹד אֲנִי יְשֵׁנָה בִתְלַת מֵאָה וְשִׁתִּין וְחָמֵשׁ פִּקּוּדִין דְּלָא תַעֲשֶׂה, כְּחוּשְׁבַּן אַתְוָון יְשֵׁנָ\"ה, וְלִבִּי עִר בְּרַמַ\"ח פִּקּוּדִין דַּעֲשֵׂה כְּחֻשְׁבַּן וְלִבִּ\"י וְר' מֵעִר, רֶמֶז דְּאִתְיְיהִיבוּ מִימִינָא וּמִשְּׂמָאלָא, מַאי ע' מִן עִר דְּאִיהוּ בְתוֹסֶפֶת, דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִתְּמַר בֵּיהּ (דברים לג כח) עִין יַעֲקֹב, דְּאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא דִכְלִיל פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה. דְאִתְיְהִיבוּ מִימִינָא וּמִשְּׂמָאלָא בֵיהּ כְּלִילָן.</p>\n<p>וְעוֹד קוֹל דּוֹדִי דוֹפֵק דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דְּאִיהוּ תוֹרָ\"ה כְּלִיל תרי\"א, דְאִתְיַהִיב מִתְּרֵין דְּרוֹעִין דְּתַמָּן אַבָּא וְאִימָּא דְאִינוּן י\"ה, וּבְהוֹן אִשְׁתַּלִּים תּוֹרָ\"ה דְאִיהוּ ו' כְּלִיל תַּרְיַ\"ג, ה' תַּתָּאָה אוֹרַיְיתָא דִבְעַל פֶּה כְּלִילָא מִכֻּלְּהוּ אַתְוָון, וּבָהּ אִשְׁתַּלִּים יהו\"ה.</p>\n<p>וְעוֹד אֲנִי יְשֵׁנָה, שְׁנִיָּה וַדַּאי לַחָכְמָה דְאִיהִי י', כַּד אִתְרַחַק מִינִי רְחִימָאי דְאִיהוּ ו', וְרָזָא דְמִלָּא (משלי ג יט) יהו\"ה בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, בְּחָכְמָה דְאִיהוּ אַבָּא י', יָסַד בְּרַתָּא דְאִיהִי אָרֶץ, ה' זְעִירָא הָאָרֶץ וַדַּאי, כּוֹנֵן שָׁמַיִם דָּא ו', בִּתְבוּנָה דָּא אִימָּא עִלָּאָה, דְּבִינָה אִתְקְרִיאַת לְעִילָא כַּד אִיהִי עִם בַּעִִלָהּ, תְּבוּנָה אִתְקְרִיאַת לְתַתָּא כַּד אִיהִי עִם ו', דְּאִיהוּ בֶּן, ו', וְת' דְּאִיהוּ תִּפְאֶרֶת, אִשְׁתְּאָרַת אִיהִי ה' עִמֵּיהּ, וּבְהַהוּא זִמְנָא דְאָת י' אִיהוּ עִם אִימָּא, וְאִיהוּ מְרַחַק מִינָהּ, אִתְּמַר בָּהּ אֲנִי יְשֵׁנָה (ואיהי שניה לה).</p>\n<p>וְעוֹד יְשֵׁנָה בְגָלוּתָא, דְלָא דָפִיק בָּהּ, וּבְהַהוּא זִמְנָא דְיֵיתֵי בַעִִלָהּ, קוֹל דּוֹדִי דוֹפֵק דְּאִיהוּ ו' רְחִימוּ דִילָהּ, רוּחַ צְפוֹנִית נָפִיק לְגַבָּהּ דְּנַשִּׁיב בְּכִנּוֹר דָּוִד, וְרוּחַ דְּרוֹמִית מִסִּטְרָא דִימִינָא, וְרוּחַ אלהי\"ם מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, דְּאִינוּן מָיִם מִסִּטְרָא דְחֶסֶד דְּתַמָּן חָכְמָה.</p>\n<p>וּבְזִמְנָא דְיֵיתֵי פּוּרְקָנָא, דְפִיקוּ סָלִיק וְנָחִית כְּגַוְונָא דְקָרְבָּן עוֹלֶה וְיוֹרֵד, סָלִיק ה' עִלָּאָה לְגַבֵּי י', וְנָחִית ה' תַּתָּאָה לְגַבֵּי ו', וּמַה דַּהֲוָה יהה\"ו, אִתְחַזַּר יהו\"ה, אַבָּא עִם אִימָּא, בְּרָא עִם בְּרַתָּא, וּבְגִין דָּא אָמַר נְבִיאָה (ירמיה ט כב) כֹּה אָמַר יהו\"ה אַל יִתְהַלֵּל חָכָם בְּחָכְמָתוֹ, דְּאִיהוּ לִימִינָא בְזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא מְרַחֲקָא מִשְּׁכִינְתֵּיהּ, וְאַל יִתְהַלֵּל הַגִּבּוֹר בִּגְבוּרָתוֹ, דְּתַמָּן גְּבוּרָה בַּצָּפוֹן וְתַמָּן עוּתְרָא, הֲדָא הוּא דִכְתִיב (איוב לז כב) מִצָּפוֹן זָהָב יֶאֱתֶה, וּבְגִין דָּא וְאַל יִתְהַלֵּל עָשִׁיר בְּעָשְׁרוֹ, (תמן לצפון שנאמר מצפון זהב יאתה), בְּזִמְנָא דְאָת ו' מְרַחֲקָא מֵה' דִּילֵיהּ, כִּי אִם בְּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל הַשְׂכֵּל וְיָדוֹעַ אוֹתִי כִּי אֲנִי יהו\"ה וְגוֹמֵר, כַּד יְהֵא יהו\"ה כִּדְקָא יָאוּת כָּל אוֹת בַּחֲבֵרְתָּהּ, הֲדָא הוּא דִכְתִיב (בראשית ב כג) עִִצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי לְזֹאת יִקָּרֵא אִשָּׁה כִּי מֵאִישׁ לֻקֳחָה זֹּאת. עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ, דָּא חָכְמָה אָבִיו, וּבִינָה אִמָּא, הֲדָא הוּא דִכְתִיב (משלי ב ג) כִּי אִם לַבִּינָה תִקְרָא, וְדָבַק בְּאִשְׁתּוֹ דָּא ו' בֵּן, וּלְבָתַר דְּאִתְדַּבַּק בְּאִתְּתֵיהּ דְּאִיהוּ ה' וְהָיוּ לְבָשָׂר אֶחָד, וְדָא אִיהוּ קָרְבָּן עוֹלֶה וְיוֹרֵד, קָרְבָּן קְרִיבוּ דְאַתְוָון דְּמִתְקָרְבִין י' עִם ה' ו' עִם ה', וּבְגִין דָּא קָרְבָּן לַיהו\"ה, דְּאִתְקְרִיבַת אִתְּתָא לְבַעִִלָהּ, הֲדָא הוּא דִכְתִיב (ויקרא א ב) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַיהו\"ה, מַאי אָדָם דָּא יו\"ד ה\"א וא\"ו ה\"א, דְּאִיהוּ קְרִיבוּ דְאַתְוָון, וּמָאן קָרִיב</p>"],[9500011213,"<p>לְגַבֵּי אַתְוָון, דָּא עִלַּת עַל כָּל הָעִלּוֹת. בְּהַהוּא זִמְנָא דְפִיקוּ נָחִית וְסָלִיק מֵאַרְבַּע דְּפִיקִין לְעִִשֶׂר, דְּפִיקוּ בְאַרְבַּע אַתְוָון, סָלִיק בְּאֶשָּׁא וְרוּחָא, וְנָחִית בְּמַיָּא וְעַפְרָא, וְרָזָא דְמִלָּה (בראשית כח יב) וְהִנֵּה מַלְאֲכֵי אלהי\"ם עוֹלִים וְיוֹרְדִים בּוֹ, עוֹלִים תְּרֵי וְיוֹרְדִים תְּרֵי, וְאִינוּן מַיִם קָמֵ\"ץ, שְׁבָ\"א אֵשׁ, חֹלֵ\"ם רוּחַ, שׁוּרֵ\"ק עָפָר מָאנָא דְכֻלְּהוּ, בְּגִין דְּקָמֵ\"ץ דְּאִיהוּ מַיִם י', בֵּיהּ סָלִיק ה' דְּאִיהִי לִשְׂמָאלָא דְאִיהִי שְׁבָ\"א אֵשׁ, וְאַמַּאי סָלִיק ה' בְּקָמֵץ, בְּגִין דְּתַמָּן י' דְּאִיהִי חָכְמָה, כְּמָה דְאוּקְמוּהוּ הָרוֹצֶה לְהַחְכִּים יַדְרִים, וִיהוֹן י\"ה בִּימִינָא, ה' אִיהִי עִם אַבָּא, וְאִיהִי אֶרֶץ, נָחִית לִשְׂמָאלָא דְתַמָּן רוּחָא דְאִיהוּ חֹלֵ\"ם, דְּאִיהוּ רוּחַ דְּנַשִּׁיב בְּאֹזֶן שְׂמָאלָא דְלִבָּא, וִיהוֹן ו\"ה בִּשְׂמָאלָא לָקֳבֵל לִבָּא, בְּהַהוּא זִמְנָא (יחזקאל א כ) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ.</p>\n<p>כָּל נְבִיאַיָּא מִתְנַהֲגִין אַבַּתְרֵיהּ, כְּעַרְקִין דְּלִבָּא דְמִתְנַהֲגִין כֻּלְּהוּ בָּתַר רוּחָא דְלִבָּא, וּמַאי נִיהוּ שָׁמָּ\"ה דָּא מֹשֶׁ\"ה, דְאִתְּמַר בֵּיהּ (קהלת א ו) הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן וְגוֹמֵר, וּלְבָתַר דְּסָלְקִין תְּרֵין וְנָחֲתִין תְּרֵין, סָלְקִין (ארבע) דְּפִיקִין לַעֲשָׂרָה, כְּגַוְונָא דָא יוד הא ואו הא, בְּאָת י' סָלִיק ה', וּבְאָת ו' ה' תִּנְיָינָא, בְּא' סָלִיק י', דְּאִיהוּ בַעֲשַׂר אֶצְבְּעָאן דִּידַיִן וּבַעֲשַׂר אֶצְבְּעָאן דְּרַגְלִין, כָּל אַתְוָון סָלְקִין בְּוָא\"ו דְּאִיהוּ אֶחָ\"ד, כְּחֻשְׁבַּן אֶרֶ\"ץ, דְּאִיהִי שְׁכִינְתָּא, סְלִיקַת לִנְקוּדֵי לְחוּשְׁבַּן זְעִיר דַּחֲנוֹךְ, קָמֵץ י\"ד, פַּתָח כ', צֵרִי י\"ב, שְׁבָא ו', סֶגוֹל ח\"י, חֹלֵם ט\"ו, חִרֵק י\"א, חִירֵק בְּי' י\"ב, שֻׁרֵק ו', שׁוּרֵק עִם ו' י\"ב, (נ\"א מאי ניהו שורק איהו ארץ), לְחֻשְׁבַּן זְעִיר דַּחֲנוֹךְ, וְהַאי אִיהוּ חֻשְׁבַּן לְכָל נְקוּדִין לְחֻשְׁבַּן זְעִיר.</p>\n<p>אָמַר לֵיהּ וְהָא אַתְוָון דְיהוָֹ\"ה דְּאִינוּן קָרְבָּן עוֹלֶה וְיוֹרֵד, מָאן סָלִיק בְּקַדְמֵיתָא וּמָאן נָחִית, ו' נָחִית בְּקַדְמֵיתָא לְגַבֵּי ה', וּלְבָתַר סָלִיק י' לְגַבֵּי ה' עִלָּאָה, דְהָכִי אוּקְמוּהָ מָארֵי מַתְנִיתִין, לֹא אָבֹא בִירוּשָׁלַיִם שֶׁל מַעִִלָה וכו', לָא יֵיעוּל י' בְּה' עִלָּאָה דְאִיהִי יְרוּשָׁלֵם דִּלְעִילָא, עַד דְּיֵעוּל ו' בְּה' דְאִיהִי יְרוּשָׁלֵם דִּלְתַתָּא</p>\n<p>אַדְהָכִי הָא סָבָא דְסָבִין קָא נָחִית, וְאָמַר רַבִּי רַבִּי, הָא כַּלָּה אִיהִי בְּבֵי מַרְעָא מֵרְחִימָהָא, צָרִיךְ לְאַתְעָרָא בִדְפִיקוּ דִילָהּ יַתִּיר, דְּהָא קוֹל דּוֹדִי דּוֹפֵק, קוֹל רְחִימָהָא, דָּפִיק לְגַבָּהּ בִּתְּקִיפוּ סַגִּי לְאַרְבַּע סִטְרִין, הֲדָא הוּא דִכְתִיב כֹּה (יחזקאל לז ט) אָמַר יהו\"ה מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, מִסִּטְרָא דְאַוִּיר קַדְמָאָה דְאִיהוּ קַדְמוֹן עַל כֹּלָּא, דְפִיקוּ דְרוּחָא אִיהוּ לַח, מִסִּטְרָא דְחָכְמָה אִיהוּ קַר, מִסִּטְרָא דְאִימָּא אִיהוּ בְחַמִּימוּ סַגִּי, בְּגִין דְּאַוִּיר קַדְמָאָה נָטִיל בְּעַמּוּדָא דְאֶמְצָעִיתָא וְנָטִיל בַּצַּדִּיק, וְחָכְמָה דְאִיהוּ קַר נָטִיל בַּחֶסֶד וְנֶצַח, וְאִימָּא דְאִיהִי חַמִּימָא נְטִילַת בִּגְבוּרָה וָהוֹד, וּמִסִּטְרָא דִשְׁכִינְתָּא תַּתָּאָה אִיהִי יָבֵשׁ, דְּאִיהִי אֶרֶץ, דְּאִתְּמַר בָּהּ (בראשית א י) וַיִּקְרָא אלהי\"ם לַיַּבָּשָׁה אֶרֶץ, וְהָא אִינוּן אַרְבַּע וְסָלְקִין לַעֲשַׂר, כְּגַוְונָא דְאַרְבַּע אַתְוָון דְּאִינוּן יהו\"ה, דְּסָלְקִין לַעֲשַׂר יוד הא ואו הא.</p>\n<p>וּלְתַתָּא מִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוֹרִיאֵ\"ל רְפָאֵ\"ל, אִינוּן לְבוּשִׁין לְאַרְבַּע רוּחִין, דְּאִתְּמַר בְּהוּ (ישעיה יא ב) רוּחַ יהו\"ה, רוּחַ חָכְמָה וּבִינָה, רוּחַ עִצָה וּגְבוּרָה, רוּחַ דַּעַת וְיִרְאַת יהו\"ה, רוּחַ יהו\"ה דָּא אַוִּיר קַדְמָאָה, רוּחַ חָכְמָה וּבִינָה תְּרֵין סְפִירָן אַבַּתְרֵיהּ, רוּחַ עִצָה וּגְבוּרָה יְמִינָא וּשְׂמָאלָא, רוּחַ דַּעַת וְיִרְאַת יהו\"ה דָּא עַמּוּדָא דְאֶמְצָעִיתָא וּמַלְכוּת.</p>\n<p>וַהֲרִיחוֹ בְּיִרְאַת יהו\"ה דָּא רֵיחַ נִיחֹחַ, וּמַאי נִיהוּ רֵיחַ נִיחֹחַ דָּא צַדִּיק דְּבֵיהּ נְיָיחָא, דְנֹחַ אִישׁ צַדִּיק, אִשֶּׁה לַיהוָֹה דָּא נֶצַח וָהוֹד, עֲלַיְיהוּ אִתְּמַר (במדבר כח ב) אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי, אִשֵּׁי יהו\"ה אִתְקְרִיאוּ, עֲלַיְיהוּ אִתְּמַר (שיר ב ה) סַמְּכוּנִי בָּאֲשִׁישׁוֹת, (ישעיה כד טו) עַל כֵּן בָּאוּרִים כַּבְּדוּ יהו\"ה, (שיר ז ט) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים, (משלי כה יא) תַּפּוּחֵי זָהָב בְּמַשְׂכִּיּוֹת כָּסֶף, וְאִינוּן תְּרֵי אוֹפַנֵּי הַמֶּרְכָּבָה, דִּתְלַת דַּרְגִּין אִינוּן, שְׂרָפִים וְחַיּוֹת וְאוֹפַנֵּי קֹדֶשׁ, שְׂרָפִים תְּרֵין דְּרוֹעִין יְמִינָא וּשְׂמָאלָא, חַיּוֹת גּוּפָא וּבְרִית, אוֹפַנִּים תְּרֵין</p>"],[9500011214,"<p>שׁוֹקִין, מֶרְכָּבָה דְכֻלְּהוּ שְׁכִינָה, בְּגִין דְּאִינוּן שִׁית תִּיקוּנִין מִסִּטְרָא דְאָת ו', דְּאִיהוּ רוּחָא קַדִּישָׁא (נ\"א דקודשא ברוך הוא). דְּדָפִיק וּמְנַשֵּׁיב בְּכֻלְּהוּ.</p>\n<p>מַלְכוּת מֶרְכָּבָה דִילָהּ כְּלִילָא מֵאַרְבַּע רוּחִין, וְדָא אִיהוּ רָזָא דוּ פַרְצוּפִין, דְּאִינוּן עֲשָׂרָה דְפִיקִין, דְּאִינוּן ה' דְנָפִיק מִלִּבָּא, דְאִיהוּ הֲבַל ה' ל\"ב, ד' אַרְבַּע מַחֲנוֹת, ד' חַיּוֹת לַכִּסֵּא, ו' שִׁית דַּרְגִּין, דְּאִינוּן שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, דְּמִתַּמָּן כָּל נִשְׁמָתִין בְּאֹרַח אֲצִילוּת, וְלַאו אִיהוּ הַאי כָּרְסַיָּיא בְּאֹרַח בְּרִיאָה, אֶלָּא בְאֹרַח אֲצִילוּת, דִּשְׁכִינְתָּא עִלָּאָה אִיהִי כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן (ירמיה יז יב) דְּאִיהוּ מַלְכוּת</p>\n<p>וּבְהוֹן יהה\"ו ההי\"ו (ס\"א ההו\"י) אִתְלַבַּשׁ בְּשִׁית סְפִירָן, דְּאִינוּן שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, י' אִתְלַבַּשׁ בְּחָכְמָה וְסָלִיק לַעֲשָׂרָה, דְאִינוּן עִִשֶׂר גַּלְגַּלִּים דְּכָרְסַיָּיא, א לְעִילָא דְמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעִִלָה, וְדָא אַוִּיר קַדְמוֹן, ה' זְעִירָא אִיהִי לִימִינָא, וְחָכְמָה לִימִינָא נָטִיר לָהּ, וּבְהַאי אֲתַר יהו\"ה בְּחָכְמָה יָסַד אָרֶץ, (משלי ג יט) ה' לִשְׂמָאלָא אֵשׁ עַל לִבָּא, ו' רוּחָא דְנָשִׁיב לְגַבָּהּ, וּבָעִי רַחֲמֵי מִינָהּ דְּלָא אוֹקִידַת עָלְמָא, בְּגִין דְּגָרְמֵי לָהּ דְּאִתְרַחֲקָא מִבַּעִִלָהּ, וּמַאֲרִיךְ רוּגְזָהָא.</p>\n<p>וּלְזִמְנִין דְּיֵיתֵי פּוּרְקָנָא, אִתְּמַר לְגַבֵּי ו' דְּאִיהוּ דַרְגָּא דְמֹשֶׁה, מוֹלִיךְ לִימִין מֹשֶׁה (ישעיה סג יב), לְסַמְכָא ה' דִּילֵיהּ בִּימִינָא, וְדָא אִיהוּ חַי יהו\"ה שִׁכְבִי עַד הַבֹּקֶר, בֹּקֶר דְּאַבְרָהָם, י' אָזִיל לִשְׂמָאלָא וְזַקִּיף לְה' דִּילֵיהּ, וְדָא אִיהוּ קָרְבָּן עוֹלֶה וְיוֹרֵד, וְרָזָא דְמִלָּה, יַעֲקֹב בְּהַאי אֲתַר שִׂכֵּל אֶת יָדָיו, וּלְחַכִּימָא בִרְמִיזָא.</p>\n<p>אִתְחַזַּר י\"ה לִשְׂמָאלָא, דְּאִינוּן שָׁמוֹר, ו\"ה לִימִינָא דְאִינוּן זָכוֹר, וְדָא אִיהוּ זֶה שְּׁמִי וְזֶה זִכְרִי (שמות ג טו) י\"ה עִם שְׁמִ\"י שְׁסָ\"ה לִשְׂמָאלָא, ו\"ה עִם זִכְרִ\"י רְמַ\"ח לִימִינָא, בַּפֶּסַח יְהוֹן ו\"ה לִימִינָא, בְּרֹאשׁ הַשָּׁנָה י\"ה לִשְׂמָאלָא, שָׁבוּעוֹת אֲחִיד בְּתַרְוַיְיהוּ וְדָא עַמּוּדָא דְאֶמְצָעִיתָא, הֲדָא הוּא דִכְתִיב (בראשית כט כז) מַלֵּא שְׁבוּעַ זֹאת וְנִתְּנָה לְךָ גַּם אֶת זֹאת, בֵּיהּ אִשְׁתַּלִּים יהו\"ה, וְעִם כָּל דָּא לָא יְהֵא שָׁלֵם אֶלָּא בְּבַת זוּגֵיהּ דְּאִיהִי אדנ\"י, וּבְאָן אֲתַר בְּסוּכָּה, דְאִיהוּ כ\"ו ה\"ס דְּאִיהִי יאהדונה\"י, וְרָזָא דְמִלָּה וַיָּבֹא יַעֲקֹב שָׁלֵם (שם לג יח) בְּיהוָֹ\"ה, מִיָּד וַיִּבֶן לוֹ בָּיִת דָּא סוּכָּה, כְּמָה דְאַתְּ אָמַר (שם יז) וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת.</p>\n<p>בְּהַהוּא זִמְנָא, מַה דַּהֲוָה אֲנִי יְשֵׁנָה בְגָלוּתָא, דְאִסְתַּלַּק דְּפִיקוּ דִילָהּ שְׁלִימוּ דִילָהּ, בְּהַהוּא זִמְנָא אִתְּמַר בִּשְׁכִינְתָּא וְלִבִּי עִר, לְאִתְעֲרוּתָא דְפוּרְקָנָא, וּבְהַהוּא זִמְנָא נַשִּׁיב רוּחָא דְקוּדְשָׁא בָהּ, דִּבְזִמְנָא דְרוּחָא דְקוּדְשָׁא לָא נַשִּׁיב רוּחַ סְעָרָה נַשִּׁיב, בְּאוּדְנָא שְׂמָאלָא דְלִבָּא, וְיָכִיל לְמִטְעִי עָלְמָא</p>\n<p>וְהַאי אִיהוּ דְאִתְּמַר בֵּיהּ (יחזקאל א ד) וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, דְּסָעִיר גּוּפֵיהּ דְּבַר נַשׁ, דְּאִתְּמַר בֵּיהּ (ירמיה א יד) מִצָּפוֹן תִּפָּתַח הָרָעָה, וּבְהַהוּא זִמְנָא שָׁלְטִין בְּעָלְמָא כָּל רוּחִין וְשֵׁדִין וּמַזִּיקִין בִּישִׁין דִּמְחַבְּלִין עָלְמָא דְאִינוּן מַלְאֲכֵי חַבָּלָה, וְדָא דְפִיקוּ דְמַרְעָא דְסָלִיק בְּאֶשָּׁא דְגֵיהִנָּם דְאִיהִי מָרָה, וּמְחַמֵּם לְגוּפֵיהּ דְּבַר נַשׁ, וּבֵיהּ וַיְמָרַרוּ אֶת חַיֵּיהֶם, (שמות א יד) דְּאֵבָרִין דְּאִינוּן יִשְׂרָאֵל, בַּעֲבוֹדָה קָשָׁה דָּא כָּבֵד, דְּאִיהוּ כָּבֵד עַל עַרְקִין (דמרה) דִדְמָא, בְּחֹמֶר וּבִלְבֵנִים דָּא לֵיחָא חִוְורָא, דְאִיהִי כְּבֵדָה עַל בַּר נַשׁ, וּמִינָהּ יֵתוּן לֵיהּ כַּמָּה מַרְעִין בִּישִׁין, דְּאִינוּן מַיִּם הַזֵּדוֹנִים דְּמִתְגַּבְּרִין עַל אֵבָרִין דִּילֵיהּ.</p>\n<p>וּבְכָל עֲבוֹדָה בַּשָּׂדֶה דָּא דְפִיקוּ דִדְמָא, דְאִתְּמַר בֵּיהּ (בראשית כה כז) אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה, וּמַאי נִיהוּ דְפִיקוּ דִדְמָא רוּחַ סְעָרָה, דְאִתְגַּבַּר בֵּיהּ דְּמָא דְעַרְקִין דְּכָבֵד, דְּאִיהוּ עִשָׂו הוּא אֱדוֹם (שם לו א), דְּעַרְקִין דִּילֵיהּ כִּי רַגְלֵיהֶם לָרַע יָרוּצוּ וִימַהֲרוּ לִשְׁפּוֹךְ דָּם (משלי א טז), אֲשֶׁר עָבְדוּ בָהֶם בְּפָרֶךְ (שמות א יד), דְּפִיקוּ בְמָרָה אוּכְמָא, דְאִיהוּ יָבֵשׁ בְּרֵיקַנְיָא, וּבְגִין דָּא אִתְּמַר בֵּיהּ בְּפָרֶךְ.</p>\n<p>וְכַד אִתְעֲבַר רוּחַ סְעָרָה, כְּמָה דְאַתְּ אָמַר (זכריה יג ב) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר מִן הָאָרֶץ, אִתְעַר דְּפִיקוּ בְהַהוּא רוּחָא, עֲלֵיהּ אִתְּמַר (תהלים לג ו) בִּדְבַר יהו\"ה שָׁמַיִם נַעֲשׂוּ וּבְרוּחַ פִּיו כָּל צְבָאָם, בְּהַהוּא זִמְנָא הֲבָלִים דִּצְלוֹתִין סָלְקִין בֵּיהּ בְּרוּחָא דְקוּדְשָׁא לְגַבֵּי עִילָא, וְיִתְעָרוּ לְגַבַּיְיהוּ הֲבָלִים עִלָּאִין, דְּאִתְּמַר בְּהוּ</p>"],[9500011215,"<p>(דברים ח ג) כִּי לֹא עַל הַלֶּחֶם לְבַדּוֹ יִחְיֶה הָאָדָם כו', דְאִיהוּ הֲבַל דְּלִבָּא דִשְׁכִינְתָּא קַדִּישָׁא, לַהַב הַמִּזְבֵּחַ, וּמִיָּד דִּסְלִיקַת בַּהֲבָלִים דְּפוּמַיְיהוּ דְיִשְׂרָאֵל בִּצְלוֹתִין, קוּדְשָׁא בְּרִיךְ הוּא שָׁאִיל בְּגִינָהּ מִי זֹאת עוֹלָה מִן הַמִּדְבָּר (שיר ג ו) מִי בְּזֹאת עוֹלָה וַדַּאי</p>\n<p>וּבְגִין דָּא אִית הֲבַל וְאִית הֲבַל, אִית הָבֶל דְּאִתְּמַר בֵּיהּ (בראשית ד ב) וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, וְאִית הֶבֶל דִּצְלוֹתִין וּפוּלְחָנִין טָבִין, וְאִית הֲבַל דְּמִלִּין בְּטֵלִין מִלִּין רֵיקָנִין, דְּאִתְּמַר בְּהוֹן (ירמיה י טו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעִִתּוּעִים בְּעִת פְּקוּדָּתָם יֹאבֵדוּ, מַאי בְּעִת פְּקוּדָּתָם, אֶלָּא בְזִמְנָא דְאָתֵי פּוּרְקָנָא וּפְקוּדָה לְיִשְׂרָאֵל, יֹאבֵדוּ מֵעָלְמָא, הֶבֶל תַּעִִתּוּעִים דְּתוֹעִים לִבְנֵי נָשָׁא, וְרוּחָא דְקוּדְשָׁא שַׁלִּיט בְּעָלְמָא, דְאִיהוּ דְפִיקוּ דְאִתְּמַר בֵּיהּ (שיר ה ב) קוֹל דּוֹדִי דוֹפֵק, דְּפִיקוּ דְסָלִיק בְּגַלְגַלֵּי יַמָּא, דִּסְפִינָה דְאִיהִי לִבָּא, וְכָל גַּלַּיָּיא עֲלַיְהוּ אִתְּמַר, (יחזקאל א ב) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ, וּבְהוֹן הַחַיּוֹת רָצוֹא וָשׁוֹב, רָצוֹא תְּרֵין וָשׁוֹב תְּרֵין, וְאִינוּן יהו\"ה, דְּאִתְּמַר בְּהוֹן (שם לז ט) כֹּה אָמַר יהו\"ה מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ.</p>\n<p>שְׁכִינְתָּא עֲלָהּ אִתְּמַר (ירמיה ה כב) אֲשֶׁר שַׂמְתִּי חוֹל גְּבוּל לַיָּם, וְאִיהוּ תְּחוּמָא דְכֻלְּהוּ, כְּגַוְונָא דִתְּחוּם שַׁבָּת, וְכַד רָצִין גַּלִּין בְּאַרְבַּע רוּחִין, מִיָּד דְּחַזְיָין שְׁכִינְתָּא דְאִיהוּ חוֹל לֵב (נ\"א לים), דְּאִיהִי חוֹל דְּאַסְחַר לְיַמָּא, אִתְּמַר בְּהוֹן וָשׁוֹב, חָזְרָאן לְאַתְרַיְיהוּ, וְאִלֵּין אַרְבַּע רוּחִין כַּד נָפְקֵי מִן לִבָּא, תְּנוּעָה דִלְהוֹן אִיהוּ לְאַרְבַּע סִטְרִין דִּסְפִינָה, תְּרֵין בִּתְרֵין כַּנְפֵי רֵיאָה, וּתְרֵין בִּתְרֵי בָּתֵּי לִבָּא, וּתְנוּעָה דִדְפִיקוּ דְרוּחָא עָבִיד תְּנוּעָתֵיהּ, וְדָפִיק בִּנְקוּדָה אַחַת אוֹ תְּרֵין אוֹ תְּלַת, וְאִתְחַזַּר לְאַתְרֵיהּ, וּבְנִקּוּדִין דְּדָפִיק אִשְׁתְּמוֹדָע דְּפִיקוּ, לְזִמְנִין דָּפִיק זִמְנָא חֲדָא וְאִתְחַזַּר לְאַתְרֵיהּ, וּדְפִיקוּ דָא אִשְׁתְּמוֹדָע בִּנְקוּדִין דְּאוֹרַיְיתָא, בְּהַהוּא זִמְנָא דְּדָפִיק בִּנְקוּדָה חֲדָא לְתַתָּא אִיהִי חִירֵ\"ק, וְאִם הִיא לְעִילָא אִיהִי חֹלֵ\"ם, כַּד אִיהִי בְּאֶמְצָעִיתָא אִיהוּ שׁוּרֵ\"ק, אִם הִיא לְעִילָא אַחֲזֵי דְאִתְגַּבַּר אֶשָּׁא דְאִיהוּ חַם וְיָבֵשׁ וְאִיהוּ קַל, דַּעֲלֵיהּ אִתְּמַר (ויקרא ו ב) זֹאת תּוֹרַת הָעוֹלָה, וְאִם הוּא דָפִיק נְקוּדָה לְתַתָּא אִיהוּ חִרֵ\"ק, וְנָחִית בְּמַיָּא דְאִיהוּ קַר וְלַח וְאִיהוּ כָּבֵד, וְאִי דָפִיק נְקוּדָה בְאֶמְצָעִיתָא שֻׁרֵ\"ק דְּנַשִּׁיב (נ\"א דנחית) בְּרוּחָא עַל מַיָּא, וַאֲחִיד בְּתַרְוַיְיהוּ וְאִיהוּ חַם וְלַח.</p>\n<p>וְהַאי אִיהוּ דְנָקִיד זִמְנָא חֲדָא לְעִילָא וְאִסְתַּלַּק דְּפִיקוּ, אוֹ דָפִיק זִמְנָא חֲדָא לְתַתָּא וְאִסְתַּלַּק דְּפִיקוּ, אוֹ דָפִיק זִמְנָא חֲדָא בְּאֶמְצָעִיתָא וְאִסְתַּלַּק דְּפִיקוּ, וְאִם דָּפִיק תְּרֵי זִמְנֵי דָא בָתַר דָּא וְאִסְתַּלַּק דְּפִיקוּ, הָא אִינוּן צֵרִ\"י דִדְפִיקוּ דִלְהוֹן שָׁוִין, אֲבָל דָּפִיק נְקוּדָה חֲדָא לְעִילָא וּנְקוּדָה חֲדָא לְתַתָּא דָּא בָתַר דָּא אִינוּן שְׁבָ\"א, וּתְרֵין נְקוּדִין, אִינוּן אֵשׁ וּמַיִם, לְזִמְנִין דָּא סָלִיק וְדָא נָחִית, כְּגוֹן אֶת הַמָּאוֹר הַגָּדוֹל (לממשלת היום) וְאֶת הַמָּאוֹר הַקָּטֹן (לממשלת הלילה), (בראשית א טז) וּלְזִמְנִין אִינוּן שָׁוִין וְאִינוּן שָׁמַיִם אֵשׁ וּמַיִם, וּלְזִמְנִין דָּפִיק תְּלַת דְּפִיקִין חַד לְעִילָא וּבַתְרֵיהּ תִּנְיָינָא בְּאֶמְצָעִיתָא וּבַתְרֵיהּ תְּלִיתָאָה לְתַתָּא, הָא תְּלַת יְסוֹדִין יִתְעָרוּן בֵּיהּ דְּאִינוּן אֵשׁ וּמַיִם וְרוּחַ בְּאֶמְצָעִיתָא וְדָא שֻׁרֵ\"ק, וְאִם דָּפִיק תְּרֵין דְּפִיקִין שָׁוִין דָּא בָתַר דָּא וּנְקוּדָה בָתַר תְּרֵין לְתַתָּא הָא אִינוּן סֶגוֹ\"ל, דְּאִינוּן מַיִם וְאֵשׁ רוּחַ לְתַתָּא, וּלְזִמְנִין דְּפִיקוּ בְּפוּתְיָא בַאֲרִיכוּ דָא פַּתָ\"ח, וּלְזִמְנִין דָּפִיק בַּאֲרִיכוּ וְנָקִיד נְקוּדָה אַבַּתְרֵיהּ דָּא קָמֵ\"ץ, בַּאֲרִיכוּ אַחֲזֵי רַחֲמֵי.</p>\n<p>אִם זָכוּ דְפִיקוּ דָפִיק בְּאִלֵּין נְקוּדִין תֵּשַׁע, שְׁכִינְתָּא מָאנָא לְכֻלְּהוּ עֲשִׁירִית לוֹן, בְּגִין דְּבָהּ כְּלִילָן כָּל אַתְוָון, וְאַתְוָון אִינוּן לְגַבֵּי נְקוּדִין כְּגוּפָא לְגַבֵּי רוּחָא, וּבֵין כָּל דְּפִיקוּ וּדְפִיקוּ (י' שעוריה דאיהו שעור קומה), ו' שִׁעוּרֵיהּ דְּאִיהוּ שִׁיעוּר קוֹמָה.</p>"],[9500011216,"<p>וְכַד נְקוּדִין דָּפְקִין בֵּיהּ, אִינוּן דָּפְקִין כֻּלְּהוּ דְפִיקִין בִּנְיָיחָא בְּרַחֲמֵי, וְכַד לֵית תַּמָּן ו' דָּפְקִין בִּמְהִירוּ, וְאִינוּן דִּינִין דְּפִיקִין דְּדוֹחֲקָא בָּתַר דּוֹחֲקָא, וְאִנּוּן (ירמיה ל ז) עִת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּה יִוָּשֵׁעַ.</p>\n<p>וּמָאנָא דִנְקוּדִין אִיהוּ נֶפֶשׁ, נִשְׁמָתָא אִיהִי כֶתֶר עַל כֻּלְּהוּ, וּמִינָה כִּתְרִין, דְּאִינוּן טַעֲמֵי תְּנוּעָה דִנְקוּדִין וְאַתְוָון, וְאִיהִי תַלְיָא בְּמַחֲשַׁבְתָּא, וּנְקוּדִין תַּלְיָין בַּאֲמִירָה, אַתְוָון בַּעֲשִׂיָּיה, וְדָא אִיהוּ אוֹמֵר וְעוֹשֶׂה, מִסִּטְרָא דִימִינָא אֲמִירָה, מִסִּטְרָא דִשְׂמָאלָא עֲשִׂיָּה, עַמּוּדָא דְאֶמְצָעִיתָא כְּלִיל תַּרְוַיְיהוּ אוֹמֵר וְעוֹשֶׂה, וּבְמַאי אוֹמֵר וְעוֹשֶׂה, בְּהַוַיָּה, דְאִתְּמַר בָּהּ (בראשית א ג) יְהִי אוֹר וַיְהִי אוֹר, יְהִי אוֹר יְהִי י' בְּאוֹר וְאִתְעֲבִיד אַוִּיר דַּאֲחִיד בְּתַרְוַיְיהוּ בְּעַמּוּדָא דְאֶמְצָעִיתָא.</p>\n<p>וְאִית דְּפִיקוּ דְעִץ הַדַּעַת טוֹב וָרָע, דְּמֵהַאי אֲתַר יֵצֶר טוֹב וְיֵצֶר רָע, וְאִיהוּ רָזָא דְלַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת (שם ג כד), דְּאִתְהַפַּךְ מִמַּטֶּה לְנָחָשׁ וּמִנָּחָשׁ לַמַּטֶּה, דְּפִיקוּ דְיֵצֶר הַטּוֹב אַחֲזֵי בְּרִיאוּתָא וְאַסְוָותָא דְכָל אֵבָרִין, וּדְפִיקוּ דְיֵצֶר הָרָע אַחֲזֵי מַרְעָא דְכָל אֵבָרִין דְּגוּפָא, וְכָל מָאן דְּאַלִּים גָּבַר, אִי מִתְגַּבְּרִין זַכְוָון אִתְהַפַּךְ מִנָּחָשׁ לַמַּטֶּה, וּמִיָּד מַטֶּה כְּלַפֵּי חֶסֶד וְכָל גּוּפָא אִתְּסֵי, וְאִם מִתְגַּבְּרִין חוֹבִין אִתְהַפַּךְ מִמַּטֶּה לְנָחָשׁ וְנַשִּׁיךְ כָּל אֵבָרִין בְּכַמָּה נְשִׁיכִין דִּכְאֵיבִין וּמַרְעִין, בְּהַהוּא זִמְנָא אִתְּמַר בִּדְפִיקוּ, אֵין קוֹל עֲנוֹת גְּבוּרָה וְאֵין קוֹל עֲנוֹת חֲלוּשָׁה קוֹל עַנּוֹת אָנֹכִי שֹׁמֵעַ (שמות לב יח), קוֹל דְּעִנּוּיָא קוֹל דִּדְפִיקוּ דְבֵי מַרְעָא דְגָלוּתָא אָנֹכִי שֹׁמֵעַ.</p>\n<p>וְאִית דְפִיקוּ מֵאִילָנָא דְאִיהוּ בִּישׁ, לֵית בֵּיהּ טַב כְּלָל, דְּמִנֵּיהּ נָפִיק רוּחַ סְעָרָה, דְאַסְעִיר בֵּיהּ גּוּפֵיהּ דְּבַר נַשׁ, וְאִתְּמַר בֵּיהּ (מלכים א יט יא) רוּחַ חָזָק מְפָרֵק הָרִים, דְּאִינוּן גָּרְמִין דְּגוּפָא, וּמְשַׁבֵּר סְלָעִים, דְּאִינוּן צְלָעוֹת דְּגוּפָא דְאִינוּן כְּגַוְונָא דִסְלָעִים, וְהַאי אִיהוּ נָפִיק בְּזָדוֹן וְלֵית לֵיהּ מִשְׁקָל וְשִׁעוּר, וּבֵיהּ (יונה א ד) וְהָאֳנִיָּה דְאִיהוּ גוּפָא חִשְּׁבָה לְהִשָּׁבֵר, וְהַאי דְּפִיקוּ סָלִיק וְנָחִית בְּגַלֵּי יַמָּא, דְאִינוּן עֲשַׂר כִּתְרִין תַּתָּאִין, כְּגַוְונָא דְאִיהִי מַלְכוּת קַדִּישָׁא הָכִי אִיהוּ מַלְכוּת חַיָּיבָא, כְּגַוְונָא דְמִילָה הָכִי אִיהִי עָרְלָה, דְּתַמָּן סמא\"ל עָרֵל, וּבַת זוּגֵיהּ עָרְלָה, נָחָשׁ וְאֵשֶׁת זְנוּנִים.</p>\n<p>לָקֳבֵל תְּרֵי יַרְכֵי קְשׁוֹט מִסִּטְרָא דִמְסָאֲבוּ תאומיא\"ל תומיא\"ל, וּלְקִבְלַיְיהוּ אִתְּמַר (שמות טו ה) תְּהוֹמוֹת יְכַסְיֻמוּ יָרְדוּ בִמְצוֹלוֹת כְּמוֹ אָבֶן, לָקֳבֵל עַמּוּדָא דְאֶמְצָעִיתָא אִיהוּ עוגיא\"ל דְּמִתַּמָּן עוֹג מֶלֶךְ הַבָּשָׁן, מִסִּטְרָא דִתְרֵין דְּרוֹעִין אִינוּן (אגניא\"ל) עזיאל, אגגיאל מִתַּמָּן אֲגָג, וּבֵיהּ כִּי גָאֹה גָּאָה סוּס וְרֹכְבוֹ רָמָה בַיָּם (שם א), עוזיא\"ל, מִתַּמָּן עֲזָאזֵל, וּמִתַּמָּן עז\"א ועזא\"ל, וְאִיהוּ חזריא\"ל, יְכַרְסְמֶנָּה חֲזִיר מִיָּעַר (תהלים פ יד), וַעֲלֵיהּ אִתְּמַר (בראשית כז מ) וְעַל חַרְבְּךָ תִחְיֶה, וְאִיהוּ שעריא\"ל, דְּמִתַּמָּן רוּחַ סְעָרָה, וְאִיהוּ עִשָׂו אִישׁ שָׂעִיר, וּמִתַּמָּן שֵׂעָר בְּאִשָּׁה עִִרְוָה, וַעֲלֵיהּ אִתַּקַּף הַהוּא דְאִתְּמַר בֵּיהּ (שמות טו ב) עָזִּי וְזִמְרָת יָ\"הּ וַיְהִי לִי לִישׁוּעָה, יהו\"ה אִישׁ מִלְחָמָה יהו\"ה שְׁמוֹ וְגוֹמֵר.</p>\n<p>לָקֳבֵל בִּינָה דְאִתְּמַר בָּהּ אַלֵּף בִּינָה, אִלֵּין אַלּוּפֵי עִשָׂו, לָקֳבֵל חָכְמָה אָדָם בְּלִיַּעַל אִישׁ אָוְן, לְעִילָא כתריא\"ל (נ\"א כרתיא\"ל) לָקֳבֵל כֶּתֶר עִִלְיוֹן, וּמִתַּמָּן כָּרֵת לְכָל אִלֵּין דְּעָבְרִין עַל אוֹרַיְיתָא, וְאִינוּן כִּתְרִין תַּתָּאִין אִינוּן קְלִיפִין לַעֲשַׂר סְפִירָן, וַעֲשַׂר סְפִירָן מוֹחָא בְּגַוַּיְיהוּ, וְאִלֵּין קְלִיפִין אִינוּן מְחִיצָה בֵּין יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם, בְּאִלֵּין קְלִיפִין מִתְלַבֵּשׁ קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, לְקַיְימָא בִשְׁכִינְתֵּיהּ (תהלים קג יט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה, וּלְקַיְימָא בֵיהּ (שם מז ח) כִּי מֶלֶךְ עַל כָּל הָאָרֶץ אלהי\"ם, אֲבָל לְעִילָא בְּאַתְרֵיהּ אִתְּמַר (שם ח ה) לֹא יְגוּרְךָ רָע, אֶלָּא קְלִיפִין דִּילֵיהּ לְעִילָא אִינוּן לְבוּשִׁין מִכַּמָּה גַוָּונִין שַׁפִּירִין דִּנְהוֹרָא, דְּמִנְּהוֹן אִתְפַּשַּׁט קוּדְשָׁא בְּרִיךְ הוּא בְּגָלוּתָא, וְאִתְלַבַּשׁ בְּאִלֵּין אָחֳרָנִין, בְּגִין לְנַטְרָא לְיִשְׂרָאֵל, דְּאִינוּן מִתְלַבְּשִׁין בְּאִלֵּין קְלִיפִין, וְדָא אִיהוּ (ישעיה סג ט) בְּכָל צָרָתָם לוֹ צָר</p>"],[9500011217,"<p>וכו', בְּקַדְמֵיתָא יְהַב לוֹן בִּידָא דְשָׁלִיחַ דְּאִיהוּ גַבְרִיאֵל, וְלָא הֲוָה מְזוֹנָא לסמאל וּלְמַשִּׁרְיָין דִּילֵיהּ אֶלָּא עַל יְדֵי שְׁלִיחָא, בְּגִין חוֹבִין דְּיִשְׂרָאֵל אִתְלַבַּשׁ הוּא בְּהוֹן, וְכַבְיָכוֹל אָתֵי לֵיהּ עַל יְדֵי דְקוּדְשָׁא בְּרִיךְ הוּא, לְהַאי אִם יִשְׂרָאֵל אָזְלִין בְּאֹרַח מֵישַׁר וּמְקַיְּימִין אוֹרַיְיתָא וּפִקּוּדִין דִּילֵיהּ, וְאִם חַס וְשָׁלוֹם לָא מְקַיְּימִין אוֹרַיְיתָא וּפִקּוּדִין דִּילֵיהּ, יָהֵיב עֲשַׂר כִּתְרִין בִּידוֹי דְסמא\"ל, וְלָא צָרִיךְ מְזוֹנָא לָא מִידָא דְקוּדְשָׁא בְּרִיךְ הוּא, כָּל שֶׁכֵּן מִשְּׁלִיחָא דִילֵיהּ, וְדָא לְפַרְעֹה דְאָמַר (יחזקאל כט ג) לִי יְאוֹרִי וַאֲנִי עֲשִׂיתִנִי, בְּגִין דְּחָזָא כִּתְרִין נוּכְרָאִין בִּידָא דְסמא\"ל, דִּבְקַדְמֵיתָא כַּד הֲווֹ כִּתְרִין תַּתָּאִין בִּידָא דְקוּדְשָׁא בְּרִיךְ הוּא, מַה כְּתִיב בְּיִשְׂרָאֵל (דברים כח י) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יהו\"ה נִקְרָא עָלֶיךָ, וּבְזִמְנָא דְאִינוּן כִּתְרִין נוּכְרָאִין בִּידָא דְסמא\"ל, לָא דָחֲלִין אוּמִין דְּעָלְמָא מִיִּשְׂרָאֵל, וְעָבְדִין בְּהוּ כִּרְעוּתַיְיהוּ, עַד שַׁעִִתָּא דְפוּרְקָנָא דְיִתְקַיַּים בְּהוּ (זכריה יג ב) וְאֶת רוּחַ הַטּוּמְאָה אַעֲבִיר וכו', דְּאִלֵּין קְלִיפִין גָּרְמִין אַפְרָשׁוּתָא בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּבֵין יִשְׂרָאֵל, וְדָא אִיהוּ רָזָא כִּי אִם עֲוֹנוֹתֵיכֶם הָיוּ מַבְדִּילִים בֵּינֵיכֶם לְבֵין אלהיכ\"ם (ישעיה נט ב), וְעָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא אִלֵּין קְלִיפִין, וּלְאִתְחַזָּאָה לְיִשְׂרָאֵל בְּמוֹחָא מִלְּגָאו, הֲדָא הוּא דִכְתִיב (שם ל כ) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ וְהָיוּ עִינֶיךָ רוֹאוֹת אֶת מוֹרֶיךָ, וְלֹא יִהְיֶה מְחִיצָה בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ וּבֵין יִשְׂרָאֵל.</p>\n<p>וּבְזִמְנָא דַעֲשַׂר סְפִירָן מִתְלַבְּשָׁן בְּאִלֵּין קְלִיפִין, אִלֵּין דְּיָדְעִין בִּקְלִיפִין עָבְדִין אוֹמָאָה בִּשְׁמָהָן וּבַהֲוַיּוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא לְאִלֵּין קְלִיפִין וּבָטְלִין גְּזֵרָה, וְעַל אִלֵּין קְלִיפִין אָמְרוּ דְצָרִיךְ הַבְדָּלָה, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְלַבַּשׁ בְּהוֹן בְּיוֹמִין דְּחוֹל, וּבְשַׁבָּת אִתְפַּשַּׁט מִנְּהוֹן וְאִתְלַבַּשׁ בִּלְבוּשִׁין דְּקֹדֶשׁ, וַעֲשָׂרָה לְבוּשִׁין אִינוּן דְּקֹדֶשׁ, דְּאִתְּמַר בְּהוֹן (דברים לב יב) יהו\"ה בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר, בָּדָ\"ד עִִשֶׂר, כְּחוּשְׁבַּן עֲשַׂר קְלִיפוֹת דְּחוֹל, כַּד אִתְלַבַּשׁ בְּהוֹן אִתְּמַר (ויקרא יג מו) בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ, בְּהַהִיא קְלִיפָה דְגָרִים בַּר נַשׁ לְאִתְלַבְּשָׁא שֵׁם ה' בֵּיהּ נָטִיל נוּקְמָא, וּבְגִין דָּא לֹא תִשָּׂא אֶת שֵׁם יהו\"ה אלהי\"ך לַשָּׁוְא (שמות כ ז), וּבְגִין דָּא תַּקִּינוּ בְהַבְדָּלָה הַמַּבְדִּיל בֵּין קֹדֶשׁ לְחוֹל וּבֵין אוֹר לְחשֶׁךְ, דְּלָא יְחַבֵּר קְלִיפִין דְּחוֹל לִקְלִיפִין דְּקֹדֶשׁ, וְלָא יַעֲבִיד לוֹן תַּעֲרוֹבֶת.</p>\n<p>וְדָא אִיהוּ (ויקרא יט יט) שָׂדְךָ לֹא תִזְרַע כִּלְאָיִם וּבֶגֶד כִּלְאַיִם שַׁעַטְנֵז, וְכָל מָאן דְּעָרַב לוֹן אִתְּמַר בֵּיהּ (במדבר יט כ) אֶת מִקְדַּשׁ יהו\"ה טִמֵּא וְגוֹמֵר, דִּבְשַׁבָּת דְּאִתְפַּשַּׁט קוּדְשָׁא בְּרִיךְ הוּא מֵאִלֵּין לְבוּשִׁין וְאִתְלַּבַּשׁ בִּלְבוּשִׁין דְּקוּדְשָׁא, לָא צָרִיךְ לְקָרְבָא קֳדָמוֹהִי (נ\"א קדמיהון) לְבוּשִׁין דְּחוֹל, דְּמוֹחָא לָא מְקַבֵּל טוּמְאָה, הֲדָא הוּא דִכְתִיב (ירמיה כג כט) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם יהו\"ה, דְּבֵיהּ לָא יָכִיל לְאִתְעָרְבָא שׁוּם עִירוּב, אֶלָּא בִּלְבוּשִׁין דְּאִתְלַבַּשׁ בְּשַׁבָּת וְיוֹם טוֹב יָכִיל לְאִתְעָרְבָא, וּבְגִינַיְיהוּ מַנִּי לְמֶעֱבַד הַבְדָּלָה, דִּלְתַתָּא אִית אִילָנָא מְעוֹרָב טוֹב וָרָע כִּלְאַיִם, וַעֲלֵיהּ אִתְּמַר (בראשית ב יז) וּמֵעִץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, בְּגִין דְּהַהוּא מוֹחָא דִילֵיהּ בַּבְּרִיאָה, יָכִיל לְאִתְעָרְבָא עִמֵּיהּ קְלִיפָה, אֲבָל מוֹחָא דְאִיהוּ נְהוֹרָא בְּאֹרַח אֲצִילוּת לָא יָכִיל לְאִתְעָרְבָא עִמֵּיהּ (נ\"א ביה) שׁוּם תַּעֲרוֹבֶת.</p>\n<p>וְאִית אִילָנָא דְטוֹב וָרָע דִּקְלִיפִין, דְּאִינוּן גַּרְעִינִין אִינוּן מִלְּגָאו רָע, וּמוֹחָא דְקִיק מִלְּבָר טוֹב, וְאִית דְּמוֹחָא דְקִיקָא מִלְּבָר טַב וּמוֹחָא סַגִּי בִּישׁ מִלְּגָאו, כְּגוֹן דַּהֲבָא וְכַסְפָּא זְעִיר מְצוּפֶּה מִלְּבָר, וְעוֹפֶרֶת סִיגִים מִלְּגָאו, דָּא מוֹנִיטָא דְשִׁקְרָא, פוּמֵיהּ טַב וְלִבֵּיהּ בִּישׁ, וְאִית דְּאִיהוּ קְלִיפָה מִלְּבָר וּמוֹחָא מִלְּגָאו, וַעֲלַיְיהוּ אִתְּמַר גּוֹלֵל אוֹר מִפְּנֵי חשֶׁךְ וְחשֶׁךְ מִפְּנֵי אוֹר.</p>\n<p>וְאִית אִילָנָא לְתַתָּא דַעֲבוֹדָה זָרָה, דְּלֵית לֵיהּ מוֹחָא אֶלָּא קְלִיפָה מִלְּגָאו וּמִלְּבָר, וַעֲלֵיהּ אִתְּמַר (תהלים א ד) לֹא כֵן הָרְשָׁעִים כִּי אִם כַּמּוֹץ אֲשֶׁר תִּדְּפֶנּוּ רוּחַ, וְאִיהִי אֲשֵׁרָה דְנָטְעִין אוּמִין דְּעָלְמָא קֳדָם עֲבוֹדָה זָרָה, דְאִיבָּא דִילֵיהּ מוֹץ אֲשֶׁר תִּדְּפֶנּוּ רוּחַ, בְּזִמְנָא דְיֵיתֵי מַלְכָּא מְשִׁיחָא</p>"],[9500011218,"<p>עָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא כָּל אִלֵּין קְלִיפִין לְעִילָא וְאֶמְצָעִיתָא וְתַתָּא, וְלָא יְהֵא עִרְבוּבְיָא בְּפַמַּלְיָא דִלְעִילָא, בְּהַהוּא זִמְנָא (דברים לב יב) יהו\"ה בָּדָד יַנְחֶנּוּ לְיִשְׂרָאֵל וְאֵין עִמּוֹ אֵל נֵכָר, בְּהַהוּא זִמְנָא (בראשית ד ב) וַתּוֹסֶף לָלֶדֶת, אִיתּוֹסַף רוּחָא דְקוּדְשָׁא עַל יִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב (יחזקאל לו כו) וְנָתַתִּי לָכֶם לֵב חָדָשׁ וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם,</p>\n<p>(אמר המגיה זה הלשון מצאתי בס\"א)</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הֲווֹ אָזְלֵי בְּאָרְחָא, אִזְדַּמַּן רַבִּי אֶלְעָאי עִמְּהוֹן, אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר שְׁמַעְתְּ בְּהַאי קְרָא אַמַּאי אִתְּמַר בֵּיהּ אֶת אֶת תְּרֵי זִמְנֵי, בָּתַר דְּאָמַר וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו, מַאי אֶת הָבֶל, וְהָא תְלַת רִבּוּיִן הָכָא, תְּרֵין אֶתִין רִבּוּיִן, וַתּוֹסֶף לָלֶדֶת רִבּוּיָיא, הָא תְלַת רִבּוּיִין, אָמַר לֵיהּ שְׁמַעְנָא דִתְלַת רִבּוּיִין אִלֵּין אִינוּן תְּלַת טִפִּין דְּאִזְדְּרִיקוּ מֵאָדָם קַדְמָאָה (נ\"א קדמאה דאתמר בהון אלה), אָמַר לֵיהּ וְהָא אֲנָא שְׁמַעְנָא (בראשית ב ד) אֵלֶּה ת וֹלְדוֹת הַ שָּׁמַיִם וְ הָאָרֶץ תַּמָּן תֹה\"וּ, אָמַר לֵיהּ וַדַּאי הָכִי הוּא, דְמִתַּמָּן הֲוָה קַיִן יְסוֹדֵיהּ וְעִקְּרֵיהּ קֳדָם דְּאָתָא לְעָלְמָא, אָמַר וַדַּאי רָזָא עִלָּאָה אִתְגַּלְיָיא דְלָא שְׁמַעְנָא עַד הַשְׁתָּא.</p>\n<p>אָמַר לֵיהּ אִם כֵּן אִלֵּין טִפִּין דְּאִתּוֹסְפוּ הָכָא מַאי נִינְהוּ, אָמַר וַדַּאי עַל אִלֵּין תְּלַת טִפִּין שַׁרְיָין תְּלַת חָכְמוֹת, חַד אִיהוּ חָכְמַת הַמַּחֲשָׁבָה, וְתִנְיָינָא חָכְמַת הַדִּבּוּר, וּתְלִיתָאָה חָכְמַת הַמַּעֲשֶׂה, וְאִינוּן תְּלַת עָלְמִין סְתִימִין, תְּלַת טִפִּין דְּתַלְיָין מִן מוֹחָא עִלָּאָה סֶגוֹ\"ל קְרִינָן לֵיהּ, וְאִית תְּלַת עִלָּאִין עֲלַיְיהוּ דְתַלְיָין מִמּוֹחָא סְתִימָא דְעַתִּיקָא דְעַתִּיקִין, וְאִינוּן סֶגוֹלְתָּא, תְּלַת עִלָּאִין אִתְרְמִיזוּ בְּי' עִלָּאָה דְאִית לָהּ קוֹצָא לְעֵילָא וְקוֹצָא לְתַתָּא וְגַו בְּאֶמְצָעִיתָא, וּתְלַת טִפִּין תִּנְיָינִין דְּאִינוּן סֶגוֹ\"ל מִן י' תַּתָּאָה, וְרָזָא דְמִלָּה בְּרֵאשִׁית, תְּלַת מֵאָדָם קַדְמָאָה, וּתְלַת מֵאָדָם תַּתָּאָה, וּבְאִלֵּין תְּלַת נְקוּדִין אִתְּמַר (ישעיה מד ו) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אלהי\"ם, וְאִלֵּין אִינוּן תְּלַת גִּלְגּוּלִין דְּאָדָם קַדְמָאָה, דִּתְלַת טִפִּין דְּאִזְדְּרִיקוּ בִּתְלַת אֲבָהָן, דִּבְהוֹן.</p>\n<p>יְבָרֶכְךָ יהו\"ה יָאֵר יהו\"ה יִשָּׂא יהו\"ה, וּתְלַת תִּנְיָינִין בִּבְרִית וּתְרֵי סַמְכֵי קְשׁוֹט, דְּנֹחַ שֵׁם וָיֶפֶת מִתַּמָּן הֲווֹ, דְּאִתְּמַר בֵּיהּ נֹחַ אִישׁ צַדִּיק מִסִּטְרָא דְצַדִּיק חַי עָלְמִין, שֵׁם וָיְפֶת, מִסִּטְרָא דִתְרֵין סַמְכֵי קְשׁוֹט, וְרָזָא דְמִלָּה הָכָא, (משלי ל ד) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ כִּי תֵדָע, מַה שְּׁמוֹ בְּאִימָּא עִלָּאָה דְתַמָּן חָכְמָה, וּמַה שֶּׁם בְּנוֹ בְּאִימָּא תַּתָּאָה אִשְׁתְּמוֹדְעָא, אֲבָל תְּלַת גִּלְגּוּלִין בִּתְלַת אֲבָהָן, וּתְלַת בִּתְלַת סָמְכִין דִּלְתַתָּא, וְאִלֵּין שִׁית הֲווֹ עֲתִידִין לְמֶהֱוִי תְלַת בְּשֵׁת וּתְלַת בְּהֶבֶל, אֶלָּא דְפָרַח י' מִשֵּׁת דְּאִיהִי נְקֻדָּה כו'. (ע\"כ מס\"א).</p>\n<p>וְעוֹד וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, רַבִּי יוֹסֵי וְרַבִּי אֶלְעָאי הֲווֹ אָזְלֵי בְּאָרְחָא, אִזְדַּמַּן רַבִּי אֶלְעָזָר עִמְּהוֹן, אָמְרוּ וַדַּאי עֲלָךְ אִתְּמַר (בראשית כח יא) וַיִּפְגַּע בַּמָּקוֹם דְּאַעִִרַעִִנָא בִשְׁכִינְתָּא, אָמַר לוֹן עֲלַיְיכוּ אִתְּמַר (שם לב ב) וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אלהי\"ם, מַאי מַלְאֲכֵי אלהי\"ם, אִלֵּין דְּאִתְּמַר בְּהוֹן (תהלים קד ד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת, דְּרוּחִין דִּילְכוֹן מֵרוּחָא דְקוּדְשָׁא בְּרִיךְ הוּא, (נ\"א דקודשא) חָדוּ כֻּלְּהוּ בְאָרְחָא. אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר מַאי וַתּוֹסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל, וְעוֹד מַאי אָתָא לְרַבּוֹת וַתּוֹסֶף, וּתְרֵין אֶתִין אֶת אָחִיו אֶת הָבֶל.</p>\n<p>אָמַר לֵיהּ וַדַּאי וַתּוֹסֶף דָּא תוֹסֶפֶת רוּחָא דְקוּדְשָׁא דְאִיהוּ עַמּוּדָא דְאֶמְצָעִיתָא, מִתַּמָּן אִתּוֹסַף לֵיהּ רוּחָא דְקוּדְשָׁא, תְּרֵין אֶתִין לְרַבּוֹת בֵּיהּ נִשְׁמָתָא וְנַפְשָׁא מִשְּׁכִינְתָּא עִלָּאָה וְתַתָּאָה, וּמַאי הֲוָה תוֹסֶפֶת עַל רוּחָא דָא חָכְמָה מֵאָדָם עִלָּאָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי שְׁמַעִִנָא דִתְלַת רִבּוּיִין אִלֵּין, אִינוּן תְּלַת טִפִּין דְּאִזְדְּרִיקוּ מִמּוֹחָא סְתִימָא דְכָל סְתִימִין, וְאִלֵּין אִינוּן תְּלַת גִּלְגּוּלִין, וְאִלֵּין תְּלַת טִפִּין, שְׁמַעִִנָא דְאִינוּן לָקֳבֵל תְּלַת נָשִׁים, דְּאִתְּמַר בְּהוֹן (משלי יד א) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ, דְּחַד אוֹפָה וְחַד עוֹרֶכֶת וְחַד מְקַטֶּפֶת, לְהַהִיא דְאִתְּמַר בָּהּ (במדבר טו כ) רֵאשִׁית עֲרִיסֹתֵיכֶם חַלָּה, וְדָא חַלָּה דְפֶסַח דְּאִיהִי סֶגוֹלְתָּ\"א, אִיהִי טִפָּה קַדְמָאָה וּמִינָהּ אִזְדְּרִיקוּ תְּלַת טִפִּין, וְאִינוּן תְּלַת יוּדִין י' י' י' דְּאִינוּן סֶגוֹלְתָּ\"א וַדַּאי, וְאִינוּן י' יְבָרֶכְךָ י' יָאֵר י' יִשָּׂא, וּבְאָן אֲתַר אִזְדְּרִיקוּ בִּתְלַת אֲבָהָן, דְּתַמָּן נָחִית אָדָם בִּתְלַת גִּלְגּוּלִין, וּמֵאָן אֲתַר אִזְדְּרִיקוּ מֵהַהוּא דְנָחִית בְּהוֹן (דא יה\"ו) מִסִּטְרָא דְחָכְמָה עִלָּאָה.</p>\n<p>וְלָקֳבֵל תְּלַת טִפִּין אִלֵּין תַּקִּינוּ תְּלַת מַצּוֹת בַּפֶּסַח, חַד</p>"],[9500011219,"<p>מַצָּה דִלְעִילָא לְבָרְכָא בָהּ הַמּוֹצִיא, תִּנְיָינָא לֶחֶם מִשְׁנֶה, תְּלִיתָאָה לֶחֶם עוֹנִי בְּלָא מִלְחָא, דְּהָא אִתְּמַר (ויקרא ב יג) עַל כָּל קָרְבָּנְךָ תַּקְרִיב מֶלַח, בְּגִין דְּאִיהִי מַצָּה פְּרוּסָה, כְּגַוְונָא (דניאל ה כח) דִפְרֵיס פְּרִיסַת מַלְכוּתָךְ, עַד דִּתְהֵא שְׁלֵימָה לָא צָרִיךְ לְקָרְבָא עֲלָהּ מֶלַח, דְּאִיהוּ חֹלֵ\"ם, וּמַאי נִיהוּ חֹלֵם אֶמְצָעִי (דכלהו תלת), תְּלַת טִפִּין עִלָּאִין אִינוּן סֶגוֹלְתָּ\"א, דְתַלְיָין מִמּוֹחָא סְתִימָא עַתִּיקָא דְעַתִּיקִין.</p>\n<p>תְּלַת טִפִּין אִזְדְּרִיקוּ בְּגוּלְגַּלְתָּא מִמּוֹחָא תִּנְיָינָא וְאִינוּן סֶגוֹ\"ל, בְּאָן אִזְדְּרִיקוּ, בִּתְרֵי סַמְכֵי קְשׁוֹט וּבְרִית, דְּאִינוּן לְקִבְלַיְיהוּ נֹחַ שֵׁם וָיֶפֶת, נֹחַ אִזְדַּרִיק בַּצַּדִּיק, הֲדָא הוּא דִכְתִיב (בראשית ו ט) נֹחַ אִישׁ צַדִּיק, שֵׁם וָיֶפֶת בִּתְרֵי סַמְכֵי קְשׁוֹט, וַעֲלַיְיהוּ אִתְּמַר בָּרָא שִׁית, תְּלַת טִפִּין עִלָּאִין דְּאִינוּן סֶגוֹלְתָּ\"א, דְאִזְדְּרִיקוּ מִמּוֹחָא סְתִימָא, אִינוּן קוֹצָא דְאָת י' לְעִילָא וְקוֹצָא דִילָהּ לְתַתָּא, וְגַו בְּאֶמְצָעִיתָא דִילָהּ, מוֹחָא דְאִזְדְּרִיקוּ תְּלַת טִיפִּין אִלֵּין מִינָהּ, אִיהִי י', וְדָא י' דְּאִיהִי לְעִילָא מֵאָת א, י' לְתַתָּא מִן א מוֹחָא תִנְיָינָא, וּתְלַת טִיפִּין דְּאִזְדְּרִיקוּ מִינָהּ אִינוּן סֶגוֹ\"ל, תְּלַת טִפִּין דְּאָדָם קַדְמָאָה דְאִינוּן תְּלַת גִּלְגּוּלִים, וּתְלַת דְּאָדָם תִּנְיָינָא תְּלַת גִּלְגּוּלִין.</p>\n<p>מָאן אָדָם עִלָּאָה וְאָדָם תִּנְיָינָא, אֶלָּא (משלי ל ד) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ, מַה שְּׁמוֹ אָדָם עִלָּאָה, מַה שֶּׁם בְּנוֹ אָדָם תַּתָּאָה, וְתַרְוַיְיהוּ אִתְרְמִיזוּ בְהַהוּא קְרָא דְאָמַר מֹשֶׁה, (שמות ג יג) וְאָמְרוּ לִי מַה שְּׁמוֹ מָה אֹמַר, תְּלַת טִפִּין חַד אוֹפָה בְּמוֹחָא דְּאִיהוּ לָקֳבֵל יְמִינָא, דְאִיהוּ אוֹפֶה דְאִיהוּ שַׂר הָאוֹפִים, וְחַד עוֹרֶכֶת דָּא מוֹחָא דְאִיהוּ מִסִּטְרָא דִשְׂמָאלָא, דְאִתְּמַר בָּהּ (משלי ט ב) אַף עָרְכָה שֻׁלְחָנָהּ, וְהָא אוּקְמוּהוּ שֻׁלְחָן בַּצָּפוֹן לָקֳבֵל לִבָּא, וְחַד מְקַטֶּפֶת לָקֳבֵל מוֹחָא דְאִיהוּ לַאֲחוֹרָא כְּלַפֵּי כָּתֵף, וְלָקֳבֵל אִילֵּין תְּלַת טִפִּין אִינוּן תְּלַת יוּדִין דְּאִינוּן בְּיו\"ד ה\"י ואו ה\"י, דִמְעִידִין עַל עִלַּת כָּל הָעִלּוֹת, דַּעֲלֵיהּ אִתְּמַר (ישעיה מד ו) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אלהי\"ם, דְּאִיהוּ רִאשׁוֹן וְאַחֲרוֹן וּמִבַּלְעָדָיו אֵין אלהי\"ם.</p>\n<p>וּמִשִּׁית תִּקּוּנִין אִלֵּין בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי לְשֵׁת, לְמֶהֱוֵי שְׁמֵיהּ שִׁית, לְמֶהֱוִי בֵּיהּ תְּלַת גִּלְגּוּלִין דְּאָדָם וּתְלַת דְּהֶבֶל, אֶלָּא דְפָרַח י' מִשֵּׁת דְּאִיהִי נְקוּדָה אֶבֶן שְׁתִיָּה דְמִתַּמָּן הוּשְׁתַּת עָלְמָא.</p>\n<p>וּבְהַאי י' חָב יוֹסֵף, הֲדָא הוּא דִכְתִיב (בראשית מט כד) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ וַיָּפֹזּוּ זְרוֹעִי יָדָיו, מַאי וַיָּפֹזּוּ, דְאִזְדְּרִיקַת טִיפָּה דְאִיהִי י' בֵּין עִִשֶׂר אֶצְבְּעָאן, וְאִתְפְּלִיגַת לְעִִשֶׂר נִיצוֹצִין דְּאִזְדְּרִיקוּ מִקֶּשֶׁת דְּאִיהוּ בְּרִית, וּבְאָן אֲתַר אִזְדְּרִיקוּ בַּעֲשָׂרָה הֲרוּגֵי מַלְכוּת, אָמַר לֵיהּ, וְהָא שְׁמַעִִנָא דַעֲשָׂרָה הֲרוּגֵי מַלְכוּת בְּנֵי יַעֲקֹב הֲווֹ, אָמַר לֵיהּ חַס וְשָׁלוֹם, אֶלָּא בְדִיּוֹקְנַיְיהוּ הֲווֹ.</p>\n<p>אָמַר לֵיהּ וּמָאן גָּרִים דְּאִזְדְּרִיקוּ תַּמָּן, אָמַר לֵיהּ דִּיּוֹקְנָא דַאֲבוּהָ דְאִזְדַּמַּן לְגַבֵּיהּ, דַּהֲוָה דִיּוֹקְנָא דְאָדָם קַדְמָאָה, דָּא גָרִים דְּאִזְדְּרִיקוּ לוֹן, וְנָעַץ צִפָּרְנָיו בְּקַרְקַע וּבָרַח גַּרְמֵיהּ, וְלָא אִזְדְּרִיקוּ (בההיא זונה, דאי לאו דאתחזיאת ליה דיוקנא דאבוה לא הוו אזדריקו הכי, ודיוקנא דאבוה גרם דההיא טפה וינס ויצא החוצה, ולאו בעבירה, ובשכר וינס), (נ\"א בהאי זונה, דאי הוה זריק לון בהאי זונה, הוו ישראל טבעין בימא, ולאו למגנא אוקמוה קדמאין, בשכר וינוס).</p>"],[9500011220,"<p>הַיָּם רָאָה וַיָּנֹס (תהלים קיד ג), וְאִי לָא, לָא הֲווֹ נָפְקִין יִשְׂרָאֵל מִן יַמָּא, וְאִיהוּ קַבִּיל עוֹנְשֵׁיהּ בְּאִלֵּין עֲשָׂרָה הֲרוּגֵי מַלְכוּת, דַּהֲווֹ עֲתִידִין לְמֵיפַק מִינֵיהּ עֲשָׂרָה שִׁבְטִין, וּבְגִין דָּא הֲווֹ עֲשָׂרָה הֲרוּגֵי מַלְכוּת כְּגַוְונָא דַעֲשָׂרָה שִׁבְטִין דַּהֲווֹ עֲתִידִין לְמֵיפַק מִנֵּיהּ, וַהֲווֹ חָשְׁבִין חַבְרַיָּא דַעֲשָׂרָה בְּנֵי יַעֲקֹב הֲווֹ.</p>\n<p>אָמַר לֵיהּ אִם כֵּן מָאן יְהִיב רָזָא דָא בְשֵׁת, (אמר ליה נשמתהון דצדיקיא אתבריאו קדם דאתברי עלמא כמה דאוקמוה קדמאין), (נ\"א כמ\"ש בראשית, אין ראשית אלא נשמה, וכו' עי' לקמן קיב ע\"א), אָמַר לֵיהּ בְּגִין דָּא אָמַר קְרָא (ישעיה מו י) מַגִּיד מֵרֵאשִׁית אַחֲרִית, וּבְגִין דָּא שֵׁת אִיהוּ סִיּוּמָא דְאַתְוָון, וּמִינַיְיהוּ אִשְׁתְּמוֹדְעָאן רֵישָׁא דְאַתְוָון דְּאִיהוּ א\"ב בְּאַ\"תְּ בַּ\"שׁ, וְעוֹד שֵׁת, ש' דִּילֵיהּ אִינוּן תְּלַת עַנְפֵי אִילָנָא לְעִילָא, וְאִיהִי שֹׁרֶשׁ לְתַתָּא, וְאַחֲזֵי בְּהוֹן תְּלַת גִּלְגּוּלִין לְעִילָא, וּתְלַת לְתַתָּא.</p>\n<p>ת' תִּפְאֶרֶת גש'] שָׁלוֹם, כְּלִיל שִׁית סִטְרִין, וְדָא דַרְגָּא דְמֹשֶׁה, כְּלִיל תְּלַת אֲבָהָן וּתְלַת דַּרְגִּין תְּחוֹתַיְיהוּ, וְאִינוּן גִּלְגּוּלָא דְאָדָם, שֵׁת אֱנוֹשׁ הֶבֶל, נֹחַ שֵׁם יָפֶת, וּמִשֵּׁת וְאֱנוֹשׁ אִתְיַחֲסוּ כָּל דָּרִין, הֲדָא הוּא דִכְתִיב (בראשית ד כו) אָז הוּחַל לִקְרֹא בְּשֵׁם יהו\"ה, אָז הַהוּא דְאִתְּמַר בֵּיהּ (שמות ב י) (כי מן המים משיתהו), אָז הוּחַל לְמֵיתֵי בְּגִלְגּוּלָא, הַהוּא דְאִתְּמַר בֵּיהּ (שם טו א) אָז יָשִׁיר מֹשֶׁה.</p>\n<p>וּבְגִין דָּא שֵׁת מִתַּמָּן הוּשְׁתַּת עָלְמָא, וּבְגִין דָּא כִּי שָׁת לִי אלהי\"ם זֶרַע אַחֵר תַּחַת הֶבֶל, (בראשית ד כה) דְּאִתְּמַר בֵּיהּ בְּשַׁגַּם זֶה הֶבֶל, וְאִיּוֹב עֲלֵיהּ אָמַר (איוב לח לו) מִי שָׁת בַּטּוּחוֹת חָכְמָה, חָכְמָה מַיִ\"ם עִִלְיוֹנִים, מִתַּמָּן אִתְמַשַּׁךְ, וּבְגִין דָּא כִּי מִן הַמַּיִם מְשִׁיתִיהוּ, ש תְּלַת אֲבָהָן, וְדָא מ\"ש מִן מֹשֶׁה, ה' שְׁכִינְתָּא תַּתָּאָה, הֶבֶל ה' ל\"ב.</p>\n<p>וְכָפַל שְׁמֵיהּ תְּרֵין זִמְנִין מֹשֶׁה מֹשֶׁה (שמות ג ד), לְאַחֲדָא בִּתְרֵין הֵהִי\"ן ה' עִלָּאָה ה' תַּתָּאָה, וּלְאַחֲדָא בִּתְלַת עַנְפִין וּבִתְלַת שָׁרָשִׁין דְּאִינוּן שִׁית, תְּרֵי זִמְנִין מ\"ה מִמֹּשֶׁה אִיהוּ אַחֲזֵי רָזָא (משלי ל ד) מַה שְּׁמוֹ וּמַה שֶּׁם בְּנוֹ, דְּבִתְלַת אֲבָהָן אִתְלַבַּשׁ מ\"ה דִלְעִילָא, וּבִתְלַת דַּרְגִּין דִּלְתַתָּא מ\"ה דִּלְתַתָּא, וּמֹשֶׁה כְּלִיל תַּרְוַיְיהוּ, אִיהוּ מֶרְכַּבְתָּא שְׁלֵימָתָא עִלָּאָה וְתַתָּאָה, כְּגַוְונָא דָא ש מִן מֹשֶׁה תְּלַת אֲבָהָן, דְּאִתְּמַר בָּהּ (יחזקאל א י) וּפְנֵי אַרְיֵה אֶל הַיָּמִין וּפְנֵי שׁוֹר וּפְנֵי נֶשֶׁר כו', מ\"ה דְּמֹשֶׁה וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָ\"ם, וּבְגִין דְּאִיהוּ מֶרְכָּבָה לְעִילָא וְתַתָּא, אָמַר (שמות ג יג) וְאָמְרוּ לִי מַה שְּׁמוֹ מָה אֹמַר אֲלֵיהֶם, אַדְהָכִי הָא רַבִּי יִצְחָק וְרַבִּי יוּדָאִי וְרַבִּי יְהוּדָה וּשְׁאָר חַבְרַיָּיא קָאָתוּ, אָמַר לְהוּ רַבִּי שִׁמְעוֹן בְּמַאי עַסְקִיתּוּ, אָמְרוּ לֵיהּ שְׁמַעִִנָא בָּךְ וְאָתֵינָא לְגַבָּךְ, דִּשְׁאִילְנָא עֲלָךְ לְכָל חַבְרַיָּיא וְלָא אַשְׁכַּחְנָא מָאן דְּאוֹדַע לָן מִינָךְ, עַד דְּאַעִִרַעִִנָא בְּרַבִּי יוֹסֵי וְרַבִּי אֶלְעָאי וְרַבִּי אֶלְעָזָר דַּהֲווֹ מִתְעַסְּקִין בְּרָזָא דְהֶבֶל בְּכָל גִּלְגּוּלִין דִּילֵיהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן וַדַּאי עוֹבָדָא דְצַדִּיקַיָּא לְעִילָא תַלְיָא, וְתַמָּן אִשְׁתְּמוֹדָע כֹּלָּא, וְאִתְעָרוּתָא דִלְתַתָּא גְרִים אִתְעָרוּתָא דִלְעִילָא, בְּוַדַּאי רָזָא דְגִלְגּוּלָא בַאֲתַר חַד אִיהוּ, וְכָל גִּלְגּוּלִים אִינוּן כְּגַוְונָא דְגַלְגַּלִּים דְּסָלְקִין וְנָחֲתִין, וְגַלְגַּל חַד אִיהוּ קָבוּעַ בְּאֶמְצָעִיתָא בֵינַיְיהוּ, וְאִיהוּ לָא מִתְנַעִִנְעָא הָכָא וְהָכָא.</p>\n<p>וְרָזָא דְמִלָּה הָא אוּקְמוּהָ, (קהלת א ד) דּוֹר הֹלֵךְ וְדוֹר בָּא וְהָאָרֶץ לְעוֹלָם עֹמָדֶת, דְּאִיהִי קְבִיעָא בֵינַיְיהוּ (כגוונא דא, נפש איהו בקביעו דגופא, ורוחא סלקא ונחתא בגופא ומתפשטא בכל ורידי דלבא, כבר אמרנא דגלגולים אינון כגוונא דגלגלים דסלקין ונחתין בגלגול חד), כְּגַוְונָא דָא נֶפֶשׁ אִיהִי בִקְבִיעוּ דְגוּפָא, וְרוּחָא נָחְתָא וְסָלְקָא בְגוּפָא, וּמִתְפַּשְׁטָא בְכָל וָרִידֵי דְלִבָּא דְמִתְנַעִִנְעִין, הֲדָא הוּא דִכְתִיב (יחזקאל א כ) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ, אֲבָל נַפְשָׁא קְבִיעָא בְלִבָּא, כְּאִתְּתָא דְאִיהִי קְבִיעָא בְּבֵיתָא, הֲדָא הוּא דִכְתִיב (תהלים קיג ט) מוֹשִׁיבִי עֲקֶרֶת הַבַּיִת, וּבַעִִלָהּ (בראשית ח ז) וַיֵּצֵא יָצוֹא וָשׁוֹב, הָכִי דּוֹר הוֹלֵךְ וְדוֹר בָּא, דָּא עַמּוּדָא דְאֶמְצָעִיתָא, אִיהוּ אָזִיל וְאָתֵי בְגִלְגּוּלָא, אֲבָל שְׁכִינְתָּא לְעוֹלָם עוֹמָדֶת, אִיהִי לָא אָזְלָא בְגִלְגּוּלָא, וְלָא אִתְרְכִיבַת בַּאֲתַר אָחֳרָא, וּבְגִין</p>"],[9500011221,"<p>דָּא אִתְּמַר בָּהּ, (תהלים קכח ג) אֶשְׁתְּךָ כְּגֶפֶן פֹּרִיָּה, מַה גֶּפֶן לָא קַבִּילַת הַרְכָּבָה מִמִּין אָחֳרָא מִכָּל אִילָנָא דְעָלְמָא, הָכִי שְׁכִינְתָּא לָא קַבִּילַת עֲלֵיהּ הַרְכָּבָה אָחֳרָא בְעָלְמָא אֶלָּא מִבַּעִִלָהּ</p>\n<p>קָמוּ כֻּלְּהוּ חַבְרַיָּא וְאִשְׁתַּטְחוּ קַמֵּיהּ, וְאָמְרוּ אִלּוּ לָא אֲתֵינָא לְעָלְמָא אֶלָּא לְמִשְׁמַע דָּא דַי, פָּתַח וְאָמַר וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ (קהלת א ה), וְזָרַח הַשֶּׁמֶשׁ דָּא עַמּוּדָא דְאֶמְצָעִיתָא, דְאִיהוּ מֹשֶׁה בְּדִיּוֹקְנֵיהּ, וְזָרַח הֲדָא הוּא דִכְתִיב (דברים לג ב) יהו\"ה מִסִּינַי בָּא וְזָרַח מִשֵּׂעִיר לָמוֹ, וּבָא הַשָּׁמֶשׁ כַּד אִתְכַּנִּישׁ מֹשֶׁה, וְעִם כָּל דָּא דְאִתְכַּנִּישׁ אֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם, וְדָא יְהוֹשֻׁעַ דַּהֲוָה כְּגַוְונָא דְסִיהֲרָא דְאִיהִי שְׁכִינְתָּא.</p>\n<p>וְעוֹד וְזָרַח הַשֶּׁמֶשׁ דָּא מֹשֶׁה, כַּד יֵיתֵי בְּגִלְגּוּלָא בְּצַדִּיק גָּמוּר, וְכַד לָא אִיהוּ בְּצַדִּיק גָּמוּר וּבָא הַשָּׁמֶשׁ, אִתְכַּנִּישׁ מִנֵּיהּ, וְאָזַל וְאָתֵי בְּגִלְגּוּלָא עַד דְּאַשְׁכַּח אַתְרֵיהּ, וּבְגִין דָּא אֶל מְקוֹמוֹ שׁוֹאֵף זוֹרֵחַ הוּא שָׁם.</p>\n<p>וְעוֹד וְזָרַח הַשֶּׁמֶשׁ דָּא קוּדְשָׁא בְּרִיךְ הוּא, בְּאָן אֲתַר, בְּבַר נַשׁ דִּשְׁכִינְתָּא עִמֵּיהּ, כְּמָה דְאַתְּ אָמַר (שמות כא) בְּכָל הַמָּקוֹם אֲשֶׁר אַזְכִּיר אֶת שְׁמִי וְגוֹמֵר, וְתִרְגֵּם אֹנְקְלוֹס בַּאֲתַר דְּתִשְׁרֵי שְׁכִינְתֵּיהּ תַּמָּן, וְאִי לֵית שְׁכִינְתָּא תַמָּן וּבָא הַשָּׁמֶשׁ, אִתְכַּנַּשׁ מִנֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתָּאַר בַּחֲשׁוֹכָא וְשָׁלְטִין עֲלֵיהּ כַּמָּה מְחַבְּלִין וְכַמָּה יִסּוּרִין בִּישִׁין, דְּלַאו אִינוּן יִסּוּרִין שֶׁל אַהֲבָה, הֲדָא הוּא דִכְתִיב (דברים לא יז) עַל כִּי אֵין אלֹה\"י בְּקִרְבִּי מְצָאוּנִי הָרָעוֹת הָאֵלֶּה, דְּאִלֵּין רָעוֹת מְמַנָּן עַל כָּל עִתִּין וְרִגְעִין, דַּעֲלַיְיהוּ אִתְּמַר (איוב ז יח) וַתִּפְקְדֶנּוּ לִבְקָרִים לִרְגָעִים תִּבְחָנֶנּוּ, וְזֶהוּ שֶׁאָמַר דָּוִד (תהלים לא טז) בְּיָדְךָ עִתּוֹתָי וְגוֹמֵר, וּמָאן גָּרִים דְּלָא שַׁרְיָא שְׁכִינְתָּא עֲלֵיהּ, וְלָא נָהִיר שִׁמְשָׁא עֲלֵיהּ, בְּגִין הֲבַל דְּשִׁקְרָא וּמִלִּין דְּשִׁקְרָא דְנָפְקִין מִפּוּמוֹי, וּבְגִין דָּא (קהלת ח יד) יֶשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, אִית הֶבֶל וְאִית הֶבֶל, אִית הֶבֶל מִמָּארֵי דְשִׁקְרָא דְאִתְּמַר בְּהוֹן (ירמיה י טו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעִִתּוּעִים, דְּאִינוּן תּוֹעִים בְּעוֹבָדָא דְשִׁקְרָא.</p>\n<p>וְיֵשׁ הֶבֶל דְּאִתְּמַר בֵּיהּ, (דברים ח ג) כִּי עַל כָּל מוֹצָא פִי יהו\"ה יִחְיֶה הָאָדָם, וְדָא הֲבַל דְּאוֹרַיְיתָא, דְאִיהוּ חֲמִשָּׁה חוּמְשֵׁי תוֹרָה, מִן ב' דִּבְּרֵאשִׁית עַד ל' לְעִינֵי כָּל יִשְׂרָאֵל, וְדָא הוּא הֶבֶ\"ל, וְהָא שִׁית אִינוּן עִם זֶה סֵפֶר, אֶלָּא דָא ו' דְּאִיהוּ קוֹל דְּסָלִיק בְּהֶבֶל דְּאִיהוּ ה', זַכָּאָה אִיהוּ מָאן דִּמְחַבֵּר לוֹן כַּחֲדָא, וְאַפִּיק לוֹן מִפּוּמוֹי בִּרְחִימוּ וּדְחִילוּ דְי\"ה, וּבְגִין דָּא (קהלת ח יד) יֶשׁ הֶבֶל וכו', אֲשֶׁר יֵשׁ צַדִּיקִים שֶׁמַּגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים.</p>\n<p>אָמְרוּ לֵיהּ חַבְרַיָּא רַבִּי רַבִּי אִי הָכִי דְאִינוּן צַדִּיקַיָּיא אַמַּאי מַגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הָרְשָׁעִים, אָמַר לוֹן גִּלְגּוּלָא גָרִים לוֹן דְּיֵיתֵי לוֹן כְּעוֹבָדָא דְרַשִּׁיעַיָּא, כְּאִלּוּ הֲווֹ רַשִּׁיעַיָּא הָכִי יֵיתֵי לוֹן יִסּוּרִין וְדָחֲקִין, וְהַאי אִינוּן דְּנִשְׁמָתִין דִּלְהוֹן מִסִּטְרָא דְאָדָם וְהֶבֶל, דְּדָא חָאב בְּמַחֲשָׁבָה וְעוֹבָדָא, וּבְגִין דָּא אָמַר עֲלַיְיהוּ קְרָא (קהלת א טו) בְּשַׁגַּם זֶה הֶבֶל, גַּם לְרַבּוֹת אָדָם.</p>\n<p>אָמְרוּ לֵיהּ יְדַעִִנָא דְמַחֲשָׁבָה אִיהִי אָדָם קַדְמָאָה, מ\"ה דִלְעִילָא, מַ\"ה שְּׁמוֹ, עוֹבָדָא כ\"ח דִּילֵיהּ, כ\"ח אַתְוָון דְּעוֹבָדָא דִבְּרֵאשִׁית בָּרָא וכו', וְכֹלָּא חָכְמָה כֹּחַ מָה, אִם כֵּן בְּמַאי הֲווֹ יָכְלֵי לְמֶחטֵי הָכָא, אָמַר לוֹן בְּוַדַּאי כָּל מָאן דְּחָב בְּגוּפֵיהּ דְּתַמָּן עוֹבָדָא, וּבְנִשְׁמָתֵיהּ דְּתַמָּן מַחֲשָׁבָה, כְּאִלּוּ חָאב בְּהַהוּא דְאִתְבְּרֵי אִיהוּ בְּדִיּוֹקְנֵיהּ, הֲדָא הוּא דִכְתִיב (בראשית א כז) וַיִּבְרָא אלהי\"ם אֶת הָאָדָם בְּצַלְמוֹ כו'.</p>\n<p>וְיֵשׁ רְשָׁעִים שֶׁמַּגִּיעַ אֲלֵיהֶם כְּמַעֲשֵׂה הַצַּדִּיקִים, דְּאִית לוֹן עוּתְרָא וּשְׁלָם וַאֲרִיכוּ דְיוֹמִין בְּהַאי עָלְמָא, אָמְרוּ לֵיהּ בָּתַר דְּאִינוּן רְשָׁעִים אַמַּאי אִית לוֹן כָּל הַאי יְקָר, אָמַר לוֹן הַאי טוֹבָה דִלְהוֹן אִיהוּ הֶבֶל וּרְעוּת רוּחַ, דְּגִלְגּוּלָא דִלְהוֹן גָּרִים לוֹן דַּהֲווֹ רְשָׁעִים גְּמוּרִים, וְעָבְדוּ (זכוון כמה מנייהו, ואתקצרו בקצרות שנין ולא אשתלים לון), כַּמָּה מִינֵי טָבִין, אַיְיתִי לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא בְגִלְגּוּלָא לְאַשְׁלָמָא לוֹן אַגְרַיְיהוּ בְּהַאי עָלְמָא, הֲדָא הוּא דִכְתִיב (דברים ז י) וּמְשַׁלֵּם לְשֹׂנְאָיו אֶל פָּנָיו כו', וַעֲלַיְיהוּ אִתְּמַר (קהלת ח י) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וָבָאוּ כו'.</p>"],[9500011222,"<p>אַדְהָכִי הָא רַבִּי פִּנְחָס קָא נָחִית מִמְּתִיבְתָּא עִלָּאָה, וְאִתְחַזֵּי תְּחוֹת טוּלָא דְרַבִּי שִׁמְעוֹן, וְאָמַר לֵיהּ מַאי הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, וְכִי עַל הָאָרֶץ אִתְעֲבִיד הֶבֶל, אֶלָּא כְּמָה דְאַתְּ אָמַר (בראשית ב ו) וְאֵד יַעֲלֶה מִן הָאָרֶץ, דְּאִית הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, הֲבַל דִּצְלוֹתִין וַהֲבַל דְּאוֹרַיְיתָא אִתְעֲבִיד עַל אַרְעָא דְקוּדְשָׁא בְּרִיךְ הוּא דְאִיהִי שְׁכִינְתֵּיהּ, דְּאִתְּמַר בָּהּ (ישעיה סו א) וְהָאָרֶץ הֲדֹם רַגְלָי, וּמַאי נִיהוּ הֶבֶל דְּאִתְעֲבִיד עֲלֵיהּ, אֶלָּא הֲפוֹךְ הֶבֶל וְתִשְׁכְּחֵיהּ הַלֵּב, וּמִנֵּיהּ נָפִיק הֲבַל וְדָא נֶפֶשׁ וּבֵיהּ סָלִיק דִּבּוּר, רוּחָא נָפִיק מֵאוּדְנָא שְׂמָאלָא דְלִבָּא, וּמִנֵּיהּ נָפִיק קָלָא, וְקָלָא אִיהוּ אִילָנָא, דְאִתְפַּלַּג לְכַמָּה קָלִין דְּאִינוּן עַנְפִין דְּאִילָנָא, וְאִיבָּא דִילֵיהּ דִּבּוּר, וְתַרְוַיְיהוּ עִץ פְּרִי, וְאִינוּן גּוּף וּבְרִית, דָּא עִץ ו', וְדָא פְּרִי י' אוֹת הַבְּרִית.</p>\n<p>ה' תַּתָּאָה שָׁרְשָׁא דְאִילָנָא, דְאִית בֵּיהּ תְּלַת וָוִי\"ן לָקֳבֵל תְּלַת עַנְפִין דְּש', ה' עִלָּאָה תְּלַת עַנְפִין, וְאִינוּן תְּלַת וָוִי\"ן מִן וַיִּסַּע וַיָּבֹא וַיֵּט, הַאי אִיהוּ עִץ הַחַיִּים דְּאַעֲקַר עַנְפּוֹי דְּקִצֵּץ בִּנְטִיעוֹת וְאִסְתַּלַּק אִיבָּא, וְאִתְּמַר בְּאִלָנָא (דניאל ד יא) גֹּדּוּ אִילָנָא וְקַצִּצוּ עַנְפוֹהִי כו', בְּרַם עִקַּר שָׁרְשׁוֹהִי בְּאַרְעָא שְׁבֻקוּ, דְאִיהוּ ה' תַּתָּאָה, אִסְתַּלַּק הו\"י וְאִשְׁתָּאַר ה', וּבְגִין דָּא שָׁלֹשׁ מִשְׁמָרוֹת הֲוִ\"י הַלַּיְלָה, וּבְכָל מִשְׁמָר וּמִשְׁמָר יוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא וְשׁוֹאֵג כָּאֲרִי כו', ה' דְּהַלַּיְלָה עֲלָהּ קוּדְשָׁא בְּרִיךְ הוּא שׁוֹאֵג בְּשָׁלֹשׁ מִשְׁמָרוֹת דְּתַמָּן הו\"י, תַּמָּן הו\"י אִיהוּ וַדַּאי.</p>\n<p>וּמְנָא לָן דְּאַעֲקַר אָדָם אִילָנָא וְאִיבָּא וְעַנְפִין דִּילֵיהּ, וְלָא אִשְׁתָּאַר תַּמָּן אֶלָּא שָׁרְשָׁא דְאִיהִי ה' תַּתָּאָה, הֲדָא הוּא דִכְתִיב (בראשית ג ט) וַיֹּאמֶר לוֹ אַיֶּכָּה, כְּגַוְונָא דְאֵיכָה דְאִתְּמַר בֵּיהּ (איכה א א) אֵיכָה יָשְׁבָה בָדָד, אֵיךְ ה' יָשְׁבָה בָדָד, בְּגִין דָּא אִתְגַּלְגַּל אָדָם בִּתְלַת אֲבָהָן, דְּאִינוּן עַנְפִין דְּאִילָנָא וְגוּפָא וְאִיבָּא דְאִילָנָא, וְאִתְתַּקַּן מַה דְּאַעֲקַר, נָחִית בְּאַבְרָם וְנָטַע בֵּיהּ ה' דְּאִיהִי עַנְפִין דְּאִילָנָא, נָחִית בְּיִצְחָק וְעָבִיד אִיבָּא דְאִיהוּ י' מִן יִצְחָק, נָחִית בְּיַעֲקֹב וְנָטַע בֵּיהּ ו' דְּאִיהוּ אִילָנָא, דְאִתְּמַר בֵּיהּ וִאלֹהֵי יַעֲקוֹב.</p>\n<p>לְבָתַר אָתָא מֹשֶׁה דְאִתְּמַר בֵּיהּ (בראשית ו ג) בְּשַׁגַּם הוּא בָשָׂר, שַׁגַּם זֶה הֶבֶל, וְנָחִית חֲמִשָּׁה חוּמְשֵׁי תוֹרָה, דְאִיהִי שָׁרְשָׁא דְאִלָנָא, וְאַשְׁלִים אִילָנָא בִשְׁמָא דְיהוָֹ\"ה, וּבְגִין דָּא אִשְׁתַּלִּים בֵּיהּ שֵׁם יהו\"ה, כְּמָה דְאַתְּ אָמַר (שמות ג יג) וְאָמְרוּ לִי מַה שְּׁמוֹ מָה אֹמַר אֲלֵיהֶם, (שם ד א) כִּי יֹאמְרוּ לֹא נִרְאָה אֵלֶיךָ יהו\"ה, דְּלַאֲבָהָן לָא אִתְגְּלִי לוֹן, בְּגִין דְּלָא הֲוָה שְׁלִים שְׁמָא בַּאֲבָהָן, לָא אִתְגַּלְיָא לוֹן, הֲדָא הוּא דִכְתִיב (שם ו ג) וּשְׁמִי יהו\"ה לֹא נוֹדַעִִתִּי לָהֶם, בַּמֶּה דְחָב אָדָם אִתְתַּקַּן, וּבַמֶּה דְחָב הֶבֶל אִתְתַּקַּן, וְאִתְחַזַּר כֹּלָּא בְתִקּוּנֵיהּ בְּעַנְפּוֹי בְּשָׁרְשׁוֹי בְּגוּפֵיהּ בְּאִיבֵּיהּ, וְכֹלָּא אִשְׁתַּלִּים בְּבַ\"ר דְּאִיהוּ מֹשֶׁה, ב\"ר מִן בְּרֵאשִׁית, מַה דַּהֲוָה שֵׁת נָחִית תַּמָּן י' וְאִתְעֲבִיד שִׁי\"ת, וּמַתְחִיל בְּב' דְּאִיהִי בְרָכָה לְאַפָּקָא אַרְעָא מִלְּוָוטַיָּא, דְאִתְּמַר בָּהּ (בראשית ג יז) אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ, וּלְבָתַר נָחִית ר' עֲלָהּ דְאִיהִי רֵאשִׁית חָכְמָה, וְכַד קָרִיב לְטוּרָא דְסִינַי נָחִית א' מִן בְּרֵאשִׁית דְּאִיהִי אָנֹכִי, וְנָחִית עֲלָהּ כֶּתֶר, דְּאִינוּן אַתְוָון דְּעִִשֶׂר אֲמִירָן, וְאִשְׁתַּלִּים אִילָנָא בְכָל תִּקּוּנִין דִּילֵיהּ.</p>\n<p>אָמְרוּ לֵיהּ רַבִּי רַבִּי, הָא אִילָנָא שְׁלִים בְּיהוָֹ\"ה, אַמַּאי נָחִית א' מִן בְּרֵאשִׁית, אֶלָּא בְגִין דְּאִיהוּ נְבִיעוּ לְאַשְׁקָאָה אִילָנָא, דְּמִתַּמָּן אלהי\"ם מְלֵיאָ\"ה מִכָּל תֵּשַׁע סְפִירָאן, דְּאִינוּן בַּבְּרֵאשִׁית, שִׁית אִינוּן שִׁית סְפִירָאן, בָּרָא תְּלַת סְפִירָאן עִלָּאִין, אלהי\"ם אִיהוּ עֲשִׂירָאָה מְלֵיאָה מִכֻּלְּהוּ תֵּשַׁע, שְׁלִימוּ דְכֻלְּהוּ, וּבְגִין דָּא בְּרֵאשִׁית בָּרָא אלהי\"ם, בְּרֵאשִׁית בָּרָא עִם אלהי\"ם, אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, אָתוּ לְנַשְׁקָא לֵיהּ פָּרַח לְעִילָא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן חַבְרַיָּא בְּוַדַּאי קוּדְשָׁא בְּרִיךְ הוּא אִסְתַּכַּם עִמָּנָא, עִלָּאִין וְתַתָּאִין לְמֶהֱוִי בְּהַאי חִבּוּרָא, זַכָּאָה דָרָא דְהַאי אִתְגַּלְיָיא בֵיהּ, דְּעָתִיד כּוּלֵי הַאי לְאִתְחַדְּשָׁא עַל יְדָא דְמֹשֶׁה בְּסוֹף יוֹמַיָּא בְדָרָא בַתְרָאָה, לְקַיְימָא קְרָא (קהלת א ט) מַ\"ה שֶּׁ\"הָיָה ה\"וּא שֶׁיִּהְיֶה, וּבֵיהּ</p>"]]});
